export const AGENT_FILES: Record<string, string> = {
  "agy-session.sh": "#!/bin/bash\n# What runs in the tmux pane when the conversation is held with Antigravity: `agy`, in a loop.\n#\n# The sibling of claude-session.sh, and deliberately the same shape, because the pane's problems\n# are the CLI's only in their spelling: a CLI that exits would take the tmux session down with\n# it, so the loop restarts it and the restart has to resume the same conversation rather than\n# open a new one. What differs is three lines of vocabulary -\n#\n#   claude --resume <uuid>        agy --conversation <uuid>\n#   claude --continue             agy --continue\n#   ~/.claude/projects/<dir>/     ~/.gemini/antigravity-cli/brain/<uuid>/\n#\n# - and one real difference: agy already knows which conversation belongs to a directory. It\n# keeps `cache/last_conversations.json`, a map of workspace path to conversation id, so the id\n# this pane owns is read from there rather than inferred from which transcript file appeared\n# while the pane was running.\n#\n# bash rather than sh, like its sibling: `read` with no variable is a bashism.\nexport HOME=${HOME:-/app/.home}\n\n# Ctrl-C at the prompt below leaves you in a shell rather than closing the pane. While agy is\n# running it is agy that gets the signal, not this script, so this only fires where it is offered.\ntrap 'echo; exec /bin/bash' INT\n\n# agy, installed here if it is not here yet.\n#\n# terminal-tools.sh installs it at boot only when TOOLS_AGY=1, and nothing sets that: it is a\n# couple of hundred megabytes of a CLI most panes never run, so paying for it in every pod's\n# boot to serve the occasional Antigravity conversation is the wrong trade. The right moment is\n# this one - somebody has just asked for an Antigravity conversation, so install it for them.\n# It lands in the pane's own durable home, so this happens once per pod and not once per pane.\n#\n# The lock is for two panes opened together: the second waits for the first's binary rather\n# than running a second installer over the top of it. `mkdir` is the test and the claim in one\n# step, which is what makes it a lock; the stale check is for an installer whose pane was closed\n# mid-download.\nAGY_BIN=\"$HOME/.local/bin/agy\"\nLOCK=\"$HOME/.agy-install.lock\"\n\nif ! command -v agy >/dev/null 2>&1 && [ ! -x \"$AGY_BIN\" ]; then\n  if [ -d \"$LOCK\" ] && [ -n \"$(find \"$LOCK\" -maxdepth 0 -mmin +10 2>/dev/null)\" ]; then\n    rmdir \"$LOCK\" 2>/dev/null || true\n  fi\n\n  if mkdir \"$LOCK\" 2>/dev/null; then\n    echo \"[installing the antigravity cli - a minute, once for this pod]\"\n    # `--dir` is the only option this installer has besides `--help`. Given anything else it\n    # prints its usage and exits 0, which is how agy came to be \"installed\" in pods that did not\n    # have it: a successful-looking log line and no binary.\n    mkdir -p \"$HOME/.local/bin\"\n    curl -fsSL https://antigravity.google/cli/install.sh | bash -s -- --dir \"$HOME/.local/bin\"\n    rmdir \"$LOCK\" 2>/dev/null || true\n  else\n    echo \"[another pane is installing the antigravity cli - waiting for it]\"\n    for _ in $(seq 1 120); do\n      [ -x \"$AGY_BIN\" ] && break\n      sleep 5\n    done\n  fi\n  # The installer writes into a directory this shell already had on its PATH, so the shell's\n  # cache of \"there is no agy\" is what would be consulted next.\n  hash -r 2>/dev/null || true\nfi\n\n# Installed somewhere PATH does not look: the installer is told --skip-path, because a pane's\n# PATH is set by the pod rather than by a shell profile.\nif ! command -v agy >/dev/null 2>&1 && [ -x \"$AGY_BIN\" ]; then\n  export PATH=\"$HOME/.local/bin:$PATH\"\nfi\n\nif ! command -v agy >/dev/null 2>&1; then\n  echo \"[agy could not be installed - the installer's output is above, and $(dirname \"$HOME\")/.terminal-tools.log]\"\n  echo \"[dropping to a shell]\"\n  exec /bin/bash\nfi\n\n# This directory, trusted, before agy is asked to work in it.\n#\n# agy stops on \"Do you trust the contents of this project?\" in a directory it has not seen\n# before, and a pane holding a modal dialog is a pane that looks hung: the chat sees a CLI that\n# is running and says nothing, because nothing has been written to a transcript that does not\n# exist yet. claude has the same first-run question and claude-defaults.mjs answers it in\n# advance (hasTrustDialogAccepted); this is the same answer for the same reason.\n#\n# The file is agy's own `settings.json` and `trustedWorkspaces` is a list of paths. Merged\n# rather than written: somebody may have trusted other directories, and a pane is not the place\n# to forget them. node, because node is the one thing every one of these pods is guaranteed to\n# have, and a half-written settings file is worse than an unanswered dialog - so it is written\n# beside and renamed over.\ntrust_here() {\n  node -e '\n    const fs = require(\"fs\"), path = require(\"path\");\n    const file = process.argv[1], here = process.argv[2];\n    let settings = {};\n    try { settings = JSON.parse(fs.readFileSync(file, \"utf8\")) || {}; } catch {}\n    const trusted = Array.isArray(settings.trustedWorkspaces) ? settings.trustedWorkspaces : [];\n    if (trusted.includes(here)) { process.exit(0); }\n    settings.trustedWorkspaces = [...trusted, here];\n    try {\n      fs.mkdirSync(path.dirname(file), { recursive: true });\n      fs.writeFileSync(`${ file }.tmp`, `${ JSON.stringify(settings, null, 2) }\\n`);\n      fs.renameSync(`${ file }.tmp`, file);\n    } catch {}\n  ' \"$HOME/.gemini/antigravity-cli/settings.json\" \"$(pwd)\" 2>/dev/null || true\n}\n\ntrust_here\n\n# A prompt somebody queued for this conversation, used once and then gone. Read before the loop\n# and deleted before agy runs, so a crash on the prompt does not ask it again on every restart.\nQUEUE=${1:-}\nPROMPT=\"\"\n\nif [ -n \"$QUEUE\" ] && [ -f \"$QUEUE\" ]; then\n  PROMPT=$(cat \"$QUEUE\")\n  rm -f \"$QUEUE\"\nfi\n\n# Where this pane records which conversation is its own, so a restart resumes that one and not\n# whichever conversation another pane in the same directory touched last.\nIDFILE=${2:-}\nCONVERSATION=\"\"\n\nif [ -n \"$IDFILE\" ] && [ -f \"$IDFILE\" ]; then\n  CONVERSATION=$(cat \"$IDFILE\" 2>/dev/null)\nfi\n\n# Every conversation in agy's brain, one id per line, sorted - the set this pane diffs against\n# to find the one agy makes for it. The brain is a directory per conversation, so this is a\n# listing and nothing more.\nbrain_ids() {\n  ls -1 \"$HOME/.gemini/antigravity-cli/brain\" 2>/dev/null | sort\n}\n\n# agy's own record of which conversation belongs to this directory: `{\"<path>\": \"<uuid>\"}`.\nLAST=\"$HOME/.gemini/antigravity-cli/cache/last_conversations.json\"\n\n# The id for this working directory out of that map, or empty. node rather than jq, because\n# node is the one thing every one of these pods is guaranteed to have.\nread_conversation() {\n  [ -f \"$LAST\" ] || return 0\n  node -e '\n    const fs = require(\"fs\");\n    try {\n      const map = JSON.parse(fs.readFileSync(process.argv[1], \"utf8\"));\n      const id = map[process.argv[2]] || \"\";\n      if (/^[0-9a-f-]{8,}$/i.test(id)) { process.stdout.write(id); }\n    } catch {}\n  ' \"$LAST\" \"$(pwd)\" 2>/dev/null\n}\n\n# Whether another pane already owns a conversation.\n#\n# agy's map is keyed by WORKING DIRECTORY, and every conversation in this pod shares one -\n# /workspace/conversations, so that any pane's resume picker can see all of them. So the map's\n# entry for this directory is whichever conversation was touched last by ANY pane, not this\n# pane's. Adopting it is how a brand-new conversation came up as somebody else's: agy was handed\n# `--conversation <that id>` and said so - \"it was already open in another CLI instance on this\n# machine ... use /fork\" - with the previous conversation's turns above the prompt.\n#\n# Each pane records its own id beside the sessions (`<session>.id`, written by shell.sh's\n# MC_CONVERSATION), so those files are the register of what is spoken for. An id in the map that\n# is in one of them belongs to another pane, and this one starts fresh instead.\nclaimed_elsewhere() {\n  [ -n \"$1\" ] || return 1\n  [ -n \"$IDFILE\" ] || return 1\n\n  for f in \"$(dirname \"$IDFILE\")\"/*.id; do\n    [ -f \"$f\" ] || continue\n    [ \"$f\" = \"$IDFILE\" ] && continue\n    [ \"$(cat \"$f\" 2>/dev/null)\" = \"$1\" ] && return 0\n  done\n\n  return 1\n}\n\n# The conversation THIS pane made: the one that appeared in the brain since it started.\n#\n# Not the map's entry for this directory, which was the first attempt and was wrong twice over.\n# The map says which conversation agy touched last in a directory every pane shares, so a new\n# pane read somebody else's and resumed it - and once that somebody's tab was closed, taking its\n# id file with it, the entry was unclaimed as well as stale, so the ownership check below let it\n# through and a brand-new conversation opened on a dead one's turns.\n#\n# A set difference cannot be wrong that way: whatever is in the brain now and was not there when\n# this pane started is this pane's, by construction. Exactly one, or nothing - two conversations\n# appearing at once means another pane is starting beside this one, and guessing between them is\n# how this went wrong in the first place. claude-session.sh finds its transcript the same way.\nown_conversation() {\n  [ -f \"$BRAIN_BEFORE\" ] || return 0\n\n  fresh=$(comm -13 \"$BRAIN_BEFORE\" <(brain_ids) 2>/dev/null)\n\n  [ \"$(printf '%s' \"$fresh\" | grep -c .)\" = \"1\" ] || return 0\n  claimed_elsewhere \"$fresh\" && return 0\n\n  printf '%s' \"$fresh\"\n}\n\n# Where the pre-run listing of the brain is kept. One file per pane, in the pane's own home, so\n# two panes starting together do not read each other's snapshot.\nBRAIN_BEFORE=\"$HOME/.agy-brain-$$.before\"\ntrap 'rm -f \"$BRAIN_BEFORE\"' EXIT\n\nSTARTS=0\n\nwhile true; do\n  # Nothing is adopted from the map before agy runs.\n  #\n  # The map is keyed by working directory and every conversation here shares one, so its entry\n  # before this pane has run is somebody else's conversation, or a dead one whose pane was ended.\n  # This pane's own id comes from its IDFILE, written by the watcher below the moment agy makes a\n  # conversation - which is the only moment the map says anything about THIS pane.\n\n  # The opening prompt goes to the first start only, and interactively: -i runs it and stays in\n  # the session, which is the whole point of a pane. Cleared after the start that carried it, so\n  # a restart carries on rather than asking the same thing again.\n  OPEN=()\n  if [ -n \"$PROMPT\" ]; then\n    OPEN=(--prompt-interactive \"$PROMPT\")\n  fi\n\n  # The brain as it is before agy runs, which is what makes the id it creates identifiable.\n  brain_ids > \"$BRAIN_BEFORE\"\n\n  # Record which conversation this is as soon as agy has made one, rather than when agy exits -\n  # which, for a pane somebody is sitting in, is never. The chat finds a transcript by this id,\n  # so without it a conversation that was answering perfectly well in the terminal read as\n  # \"Waiting for the conversation to begin\" in the view, with the message sent to it marked as\n  # having no record. claude-session.sh carries the same watcher for the same reason.\n  #\n  # `own_conversation` rather than the raw map: until agy writes this pane's conversation the map\n  # still names the one next door, and recording that would be the adoption bug again, dressed as\n  # a watcher. It returns nothing until the id is one no other pane has claimed.\n  if [ -n \"$IDFILE\" ] && [ ! -s \"$IDFILE\" ]; then\n    (\n      for _ in $(seq 1 150); do\n        sleep 2\n        mine=$(own_conversation)\n        if [ -n \"$mine\" ]; then\n          printf '%s' \"$mine\" > \"$IDFILE\" 2>/dev/null || true\n          break\n        fi\n      done\n    ) &\n  fi\n\n  if [ -n \"$CONVERSATION\" ]; then\n    # By id, falling back to a fresh session: a conversation the brain no longer holds - a home\n    # that was cleared, an id written by a pane that died before its first turn - must not leave\n    # the pane dead on an error.\n    agy --dangerously-skip-permissions --conversation \"$CONVERSATION\" \"${OPEN[@]}\" 2>/dev/null ||\n      agy --dangerously-skip-permissions \"${OPEN[@]}\"\n  else\n    agy --dangerously-skip-permissions \"${OPEN[@]}\"\n  fi\n\n  PROMPT=\"\"\n\n  # Which conversation that was, now that agy has written it down. Recorded after the run as\n  # well as before it, because the first run of a pane is the one that creates the id.\n  # Which conversation that was, now that agy has written it down - and only if no other pane\n  # has it, because a pane that was handed no id and created none (agy refused, the login\n  # expired) must not then claim the conversation next door.\n  if [ -z \"$CONVERSATION\" ]; then\n    CONVERSATION=$(own_conversation)\n    if [ -n \"$CONVERSATION\" ] && [ -n \"$IDFILE\" ]; then\n      printf '%s' \"$CONVERSATION\" > \"$IDFILE\" 2>/dev/null || true\n    fi\n  fi\n\n  # A CLI that keeps exiting immediately is broken rather than exited, and restarting it is a\n  # spin. The same rule its sibling uses: count the starts that died young, and stop asking.\n  STARTS=$((STARTS + 1))\n  if [ \"$STARTS\" -ge 5 ]; then\n    echo\n    echo \"[agy keeps exiting immediately, which usually means an error.]\"\n    echo \"[press Enter to try again, or Ctrl-C for a shell]\"\n    read -r || exec /bin/bash\n    STARTS=0\n  else\n    echo \"[agy exited - restarting, Ctrl-C for a shell]\"\n    sleep 1\n  fi\ndone\n",
  "boot.sh": "#!/bin/sh\n# Entrypoint for the one agent pod.\n#\n# There is nothing to serve here, which is the whole difference between this pod and an\n# extension's. It exists so that the terminal a person opens with a chord from any page in\n# Rancher has somewhere to exec into, and everything that terminal needs - tmux, the claude CLI,\n# kubectl - is installed by /seed/terminal-tools.sh, the same script every extension pod's\n# terminal already runs. Sharing it is the point: a second, slightly different install is how\n# the agent would end up with a different claude from the ones it is meant to help.\n#\n# This stays root. An extension pod drops to the node user here because its dev server has to\n# own the tree webpack is watching; there is no dev server in this pod, and shell.sh drops each\n# pane to the node user itself, so dropping the container's own process would only mean the\n# install below could not use apt.\nset -e\n\nWORKSPACE=/workspace\nAGENT_HOME=\"$WORKSPACE/.home\"\n\n# One directory per conversation, under the hostPath so both outlive the pod. They are separate\n# because claude keys its history by working directory: two panes sharing one would mean the\n# second resumed the first's conversation instead of having its own.\nmkdir -p \"$WORKSPACE/sessions\" \"$AGENT_HOME\"\n\nif [ \"$(id -u)\" = 0 ]; then\n  # The hostPath arrives owned by root, and everything inside a pane is the node user. A login\n  # claude cannot write is a login that has to be done again after every restart, which is the\n  # one thing keeping HOME on this volume is for.\n  chown node:node \"$WORKSPACE\" \"$WORKSPACE/sessions\" \"$AGENT_HOME\"\nfi\n\n# In the background, because nothing in this pod is waiting for it and a terminal opened before\n# it finishes waits for it in shell.sh, where the waiting is visible. Idempotent and lock-guarded\n# on the other side, so the two overlapping is a wait rather than two installs.\nHOME_DIR=\"$AGENT_HOME\" /bin/sh /seed/terminal-tools.sh >\"$WORKSPACE/.terminal-tools.log\" 2>&1 &\n\n# The panes that were running when this pod last went down come back on their own. shell.sh\n# records every conversation pane it starts (/workspace/.panes/<session>: the arguments, one\n# per line); each is started again here, detached, once the tools it needs are installed, and\n# the loop inside resumes the conversation by its id. Before this, a restart - Rancher's or\n# this Deployment's - ended every conversation until somebody opened each one again, and a\n# fix left running overnight was found stopped in the morning. Staggered a little: each start\n# is a claude coming up.\n(\n  n=0\n  while ! command -v tmux >/dev/null 2>&1 || [ ! -x \"$AGENT_HOME/.local/bin/claude\" ]; do\n    n=$((n + 1))\n    [ \"$n\" -gt 90 ] && { echo \"tools never arrived; not restoring panes\"; exit 0; }\n    sleep 10\n  done\n  for f in \"$WORKSPACE\"/.panes/*; do\n    [ -f \"$f\" ] || continue\n    S=$(sed -n 1p \"$f\"); W=$(sed -n 2p \"$f\"); H=$(sed -n 3p \"$f\"); P=$(sed -n 5p \"$f\")\n    # Which CLI the conversation was held with. A file written before panes could be held with\n    # anything else has five lines, and an empty sixth reads as claude - which is what it was.\n    C=$(sed -n 6p \"$f\")\n    [ -n \"$S\" ] || continue\n    echo \"$(date -u +%FT%TZ) restoring pane $S in $W with ${C:-claude}\"\n    /bin/sh /seed/shell.sh \"$S\" \"$W\" \"$H\" start \"$P\" \"${C:-claude}\" || echo \"  could not restore $S\"\n    sleep 2\n  done\n  echo \"$(date -u +%FT%TZ) done\"\n) >\"$WORKSPACE/.panes.log\" 2>&1 &\n\n# A workspace on a downstream cluster has its tree on that cluster's node, not this one's, so it\n# is not at /workspaces/<name> here the way a local one is. Mount each such workspace over sshfs\n# so a pane sees its files like any other. sshfs needs FUSE (this container runs privileged, see\n# the Deployment) and allow_other so the node user's panes can read a mount root made by root\n# here. Backgrounded, with its tools installed first; it waits for the rest. See\n# /seed/mount-downstream.sh.\n(\n  apt-get update -qq >/dev/null 2>&1 && apt-get install -y -qq sshfs >/dev/null 2>&1\n  grep -q '^user_allow_other' /etc/fuse.conf 2>/dev/null || echo user_allow_other >> /etc/fuse.conf\n  /bin/sh /seed/mount-downstream.sh\n) >\"$WORKSPACE/.mounts.log\" 2>&1 &\n\n# A downstream workspace also needs the shared github-browser, which it cannot reach on its own\n# cluster. This daemon tunnels the browser's CDP into each downstream pod at 127.0.0.1:9223 over the\n# same kubectl-exec channel (ssh reverse-forward), so a github media upload run there works like a\n# local one. Needs an ssh client here; sshd is installed into each workspace pod by the daemon.\n# See /seed/tunnel-browser.sh. Backgrounded, tools installed first, like the mount above.\n(\n  command -v ssh >/dev/null 2>&1 || { apt-get update -qq >/dev/null 2>&1 && apt-get install -y -qq openssh-client >/dev/null 2>&1; }\n  /bin/sh /seed/tunnel-browser.sh\n) >\"$WORKSPACE/.tunnel.log\" 2>&1 &\n\n# Report each downstream workspace's live state into the registrar dev-api keeps, since dev-api runs\n# on local and cannot see downstream pods but this pod can. No extra tools (kubectl + node already\n# here), so it launches straight away. See /seed/registrar-state.sh.\n(\n  /bin/sh /seed/registrar-state.sh\n) >\"$WORKSPACE/.registrar.log\" 2>&1 &\n\n# The container's only remaining job is to stay up so there is something to exec into - and to\n# reap. The daemons started above poll with kubectl every ten or fifteen seconds and leave the\n# odd orphan behind; an orphan is reparented to PID 1, and `tail -f`, which never calls wait(),\n# turned every one of them into a permanent zombie - two thousand of them, climbing by ten a\n# minute, each holding a PID.\n#\n# Ignoring SIGCHLD is the whole fix: a process that ignores it has its children reaped by the\n# Identical files across the workspaces on this node, collapsed into one inode each.\n#\n# The install path already hardlinks a whole node_modules out of a template when the lockfile\n# hash matches exactly, and that is as far as it goes: a lockfile differing by one package\n# shares nothing, and every branch has its own. Seven workspaces on this node held 6.3 GiB of\n# node_modules, five of them a full private copy of very nearly the same thing.\n#\n# Deferred five minutes so a pod that is still installing tmux, claude and a checkout is not\n# also reading every file on the disk, then daily. See dedupe-trees.mjs for what it refuses to\n# touch and why that makes it safe to run under a working agent.\n#\n# `/workspaces`, not `$WORKSPACE`: the trees it is for are the workspaces' on the node's own\n# hostPath, and this pod's `/workspace` is its own sessions directory - which is what it was\n# passed, so the sweep on the timer had been walking a tree with nothing in it to collapse.\n(\n  sleep 300\n  while true; do\n    node /seed/dedupe-trees.mjs /workspaces 2>&1 || true\n    sleep 86400\n  done\n) >\"$WORKSPACE/.dedupe.log\" 2>&1 &\n\n# One copy of the repository's history for every checkout on this node.\n#\n# Deferred a little further than the dedupe: the first run on a node with no mirror clones the\n# whole of upstream, and a pod that has just started has better things to do with its network.\n# Daily after that, which keeps the mirror current and attaches any checkout made since. See\n# git-store.sh for the order of the attach and why each step is where it is.\n(\n  sleep 600\n  while true; do\n    /bin/sh /seed/git-store.sh 2>&1 || true\n    sleep 86400\n  done\n) >\"$WORKSPACE/.git-store.log\" 2>&1 &\n\n# Every live workspace's artifacts, kept where deleting the workspace cannot reach them.\n#\n# Quarter-hourly rather than daily: this is the window in which a workspace can be deleted by\n# some route that does not run the capture, and losing a morning's recordings is worse than\n# a walk over a few thousand names that writes nothing. See keep-artifacts.sh.\n(\n  sleep 120\n  while true; do\n    /bin/sh /seed/keep-artifacts.sh /workspaces 2>&1 || true\n    sleep 900\n  done\n) >\"$WORKSPACE/.artifacts.log\" 2>&1 &\n\n# kernel, reparented ones included, so nothing has to call wait() at all. SIGTERM is handled\n# explicitly because PID 1 is exempt from default signal dispositions - without a handler the\n# signal is discarded, and every delete of this pod sat out its full grace period before the\n# kill. python3 is in this image; tini is not.\nexec python3 -c '\nimport signal, sys, time\nsignal.signal(signal.SIGCHLD, signal.SIG_IGN)\nsignal.signal(signal.SIGTERM, lambda *_: sys.exit(0))\nsignal.signal(signal.SIGINT, lambda *_: sys.exit(0))\nwhile True:\n    time.sleep(3600)\n'\n",
  "chat-hook.mjs": "// What claude is doing, written down by claude itself.\n//\n// The chat view used to read a conversation's state off the terminal: regexes over the last\n// forty lines of a TUI, looking for \"esc to interrupt\" and a bare prompt. That is guesswork\n// about a picture, and it guessed wrong in both directions - \"working\" hours after claude had\n// stopped, because a spinner line was still in the scrollback, and \"ready\" while it was mid-tool.\n//\n// Claude Code has hooks for exactly these moments, and this is the one script behind all of\n// them. It is registered (claude-defaults.mjs) for:\n//\n//   SessionStart      claude is up, on this transcript\n//   UserPromptSubmit  a turn began, and what it began with\n//   Stop              the turn is over\n//   Notification      claude is waiting: an idle prompt, a permission prompt, a question\n//   SessionEnd        claude exited, and why\n//\n// Each firing rewrites one small file, `<sessions>/<pane>.state.json`, with the latest event,\n// and appends a line to `<pane>.events.jsonl` so a sequence can be read back when something\n// looks wrong. The pane is MC_SESSION, which shell.sh puts in claude's environment; the hook\n// payload itself only knows the transcript's uuid.\n//\n// Nothing here is authoritative on its own. The chat crosses it with the transcript (which\n// carries the turn boundaries too) and with whether the claude process is alive - a hook can\n// only record what claude lived to tell it.\nimport fs from 'node:fs';\nimport path from 'node:path';\n\nconst HOME = process.env.HOME || '/app/.home';\nconst SESSION = process.env.MC_SESSION || '';\nconst DIR = path.join(path.dirname(HOME), 'sessions');\n\nlet payload = {};\n\ntry {\n  payload = JSON.parse(fs.readFileSync(0, 'utf8') || '{}');\n} catch {\n  // A hook with nothing readable on stdin still records that it fired.\n}\n\nif (!SESSION) {\n  process.exit(0);\n}\n\nconst event = {\n  event:      payload.hook_event_name || process.argv[2] || 'unknown',\n  at:         new Date().toISOString(),\n  sessionId:  payload.session_id || '',\n  transcript: payload.transcript_path || '',\n  cwd:        payload.cwd || '',\n  pid:        process.ppid,\n};\n\n// The parts of each payload the chat reads. Kept short on purpose: the transcript has the\n// content, this has the moment.\nif (payload.prompt !== undefined) {\n  event.prompt = String(payload.prompt).slice(0, 2000);\n}\nif (payload.notification_type) {\n  event.notification = payload.notification_type;\n  event.message = String(payload.message || '').slice(0, 500);\n}\nif (payload.reason) {\n  event.reason = payload.reason;\n}\nif (payload.stop_hook_active !== undefined) {\n  event.stopHookActive = !!payload.stop_hook_active;\n}\n\ntry {\n  fs.mkdirSync(DIR, { recursive: true });\n  const state = path.join(DIR, `${ SESSION }.state.json`);\n\n  // Which transcript this pane is on, from the one place that knows for certain. The pane's\n  // loop (claude-session.sh) learns it by watching for a new transcript file, which misses\n  // when two appear or none does, and a pane without the file resumes by `--continue`'s guess.\n  // Every SessionStart - a start, a resume, a /clear - names the current one.\n  if (event.event === 'SessionStart' && event.sessionId) {\n    try {\n      fs.writeFileSync(path.join(DIR, `${ SESSION }.id`), `${ event.sessionId }\\n`);\n    } catch { /* the loop's own watcher is the fallback */ }\n  }\n  const tmp = `${ state }.${ process.pid }`;\n\n  // Rename, so a reader never sees half a file.\n  fs.writeFileSync(tmp, `${ JSON.stringify(event) }\\n`);\n  fs.renameSync(tmp, state);\n\n  const log = path.join(DIR, `${ SESSION }.events.jsonl`);\n\n  fs.appendFileSync(log, `${ JSON.stringify(event) }\\n`);\n  // Bounded: the last thousand lines are more than a debugging session needs.\n  try {\n    const stat = fs.statSync(log);\n\n    if (stat.size > 512 * 1024) {\n      const lines = fs.readFileSync(log, 'utf8').split('\\n');\n\n      fs.writeFileSync(log, `${ lines.slice(-500).join('\\n') }\\n`);\n    }\n  } catch { /* the trim is best-effort */ }\n} catch {\n  // A hook must never fail the turn it is observing.\n}\n\n/**\n * Tell the watcher to look now, on the three events that settle a turn.\n *\n * The state file above is the record; this is the doorbell. dev-api watches these conversations on\n * a thirty-second timer (server.mjs, the conversation listing), which is fine for a dot on a tab\n * and too slow for the one thing this is really for: a card the person put aside until its agent\n * stopped, which should come back when it stopped and not up to half a minute later.\n *\n * It carries no state. The listing re-reads everything itself, and it must - the two facts that\n * decide a conversation's state are tmux liveness and the transcript's mtime, and a hook can see\n * neither. So this says \"look\", never \"here is what happened\", and there is nothing to trust.\n *\n * Addressed by service DNS rather than by an environment variable, because `CLAUDE_HARNESS_API` is\n * set for a workspace's tool commands and is empty in this pod - and adding it to the agent\n * Deployment would reach no cluster that already has one, since that body is only ever created,\n * never patched.\n *\n * Bounded and swallowed, because of the rule above: one second, no retry, every failure ignored. A\n * dev-api that is rolling - which happens on every release - must not add a second to somebody's\n * turn, and the thirty-second sweep is what makes losing this harmless.\n */\nconst NOTIFY = new Set(['Stop', 'Notification', 'SessionEnd']);\n\nif (NOTIFY.has(event.event)) {\n  const api = process.env.CLAUDE_HARNESS_API || 'http://dev-api.dev-system.svc.cluster.local:8080';\n\n  try {\n    await fetch(`${ api }/conversations/refresh`, { method: 'POST', signal: AbortSignal.timeout(1000) });\n  } catch { /* the sweep will find it */ }\n}\n\nprocess.exit(0);\n",
  "chat-read.mjs": "/**\n * The one read a chat makes, as a script.\n *\n * Everything the view needs about a conversation - which transcript, how long it is, the bytes\n * since the last read, each subagent's last line, the hook's state file, whether the CLI is\n * running, and the pane itself - is one script producing one string, framed by the markers in\n * chat-frames.mjs. This builds that script.\n *\n * It lived inside `poll()` in chat-conversation.ts, which was fine while the browser was the\n * only thing that ran it. The pod runs it now too - over HTTP, instead of the browser opening\n * a WebSocket and forking a process every 1.5 seconds - and two copies of a hundred lines of\n * shell is the kind of thing that is identical on the day it is written and never again. So it\n * is one function with seven arguments, and both callers are the same caller.\n *\n * Pure and importless, so `node --test` loads it directly and `scripts/gen-chat-read.mjs` can\n * render it into the seed.\n */\n\n/**\n * @param {object} at\n * @param {string} at.id      The pane's id, e.g. `p-lte-issue-14904-1`.\n * @param {number|string} at.off   Bytes of the main transcript already read; 0 for a first read.\n * @param {string} at.sub     The subagent being followed, or '' for the main conversation.\n * @param {number|string} at.soff  Bytes of that subagent's transcript already read.\n * @param {string} at.nonce   This read's marker token. See frameNonce in chat-frames.mjs.\n * @param {string} at.projKey claude's directory name for the working directory.\n * @param {string} at.cli     Which CLI holds the pane: `claude` or `agy`.\n * @returns {string} A shell script whose stdout is the framed read.\n */\nexport function chatReadScript({ id, off, sub, soff, nonce, projKey, cli }) {\n  return [\n    // CAP bounds the FIRST read of a transcript. A conversation that has run for hours has a\n    // transcript of many megabytes, and shipping the whole of it through one exec (base64\n    // over the WebSocket, inside the poll's timeout) does not arrive - so the @@DATA block\n    // never lands whole, parseTranscript sees nothing, and the chat sits on \"Nothing has been\n    // said yet.\" even though the pane (read separately, below) is full. So on the first read\n    // (OFF is 0) only the last CAP bytes are taken: the recent history, which is what the\n    // view is for, small enough to arrive every time. A partial first line from cutting\n    // mid-file is dropped by parseTranscript, and the browser sets its offset to the true\n    // size, so every read after this one is just the delta.\n    `ID=${ JSON.stringify(id) }; OFF=${ off }; SUB=${ JSON.stringify(sub) }; SOFF=${ soff }; CAP=1048576; N=${ JSON.stringify(nonce) }`,\n    `PROJ=\"$HOME/.claude/projects/${ projKey }\"`,\n    'uuid=$(cat \"$(dirname \"$HOME\")/sessions/$ID.id\" 2>/dev/null)',\n    'FILE=\"\"',\n    /*\n     * Where the transcript is, which is the one thing about reading a conversation that the\n     * CLI decides.\n     *\n     * claude keeps one file per conversation in a directory named for the working directory;\n     * agy keeps a directory per conversation with the transcript inside it. Both are found\n     * from the same id file - the pane writes it (claude-session.sh, agy-session.sh) - so the\n     * difference here is a path and nothing else.\n     *\n     * Without an id file, claude falls back to the directory's transcript - but only one no\n     * other conversation has claimed. Conversations share a working directory, because every\n     * conversation of a workspace runs in its checkout, so \"the newest transcript\" is\n     * somebody else's as often as not.\n     *\n     * \"Exactly one transcript\" was the guard and it is not enough. A workspace with two\n     * conversations where only the first has ever run has exactly one transcript, and the\n     * second - which has no id file, because it has never started - was handed the first's.\n     * Two tabs, the same history under both, which is what it looks like from outside.\n     *\n     * So the candidate is refused when another conversation's `.id` file names it. Those\n     * files hold the transcript's uuid, so this asks the question directly and without\n     * taking an id apart in shell - the thing conversation-id.mjs exists so that nothing\n     * does. The case the fallback is actually for still works: a conversation whose id file\n     * has not landed yet, in a workspace where nothing else claims the transcript.\n     *\n     * agy gets no such fallback at all: its id lives in a map keyed by that shared\n     * directory, so the guess there is not \"probably somebody else's\" but \"certainly whoever\n     * ran last\" - see claimed_elsewhere in agy-session.sh.\n     */\n    ...(cli === 'agy' ? [\n      'BRAIN=\"$HOME/.gemini/antigravity-cli/brain\"',\n      'if [ -n \"$uuid\" ] && [ -f \"$BRAIN/$uuid/.system_generated/logs/transcript.jsonl\" ]; then FILE=\"$BRAIN/$uuid/.system_generated/logs/transcript.jsonl\"; fi',\n    ] : [\n      'if [ -n \"$uuid\" ] && [ -f \"$PROJ/$uuid.jsonl\" ]; then FILE=\"$PROJ/$uuid.jsonl\";',\n      'elif [ \"$(ls \"$PROJ\"/*.jsonl 2>/dev/null | wc -l)\" -eq 1 ]; then',\n      '  CAND=$(ls \"$PROJ\"/*.jsonl 2>/dev/null | head -1); CU=$(basename \"$CAND\" .jsonl)',\n      '  SESS=\"$(dirname \"$HOME\")/sessions\"',\n      '  if ! grep -lFx \"$CU\" \"$SESS\"/*.id 2>/dev/null | grep -qv \"^$SESS/$ID\\.id$\"; then FILE=\"$CAND\"; fi',\n      'fi',\n    ]),\n    'echo \"@@FILE-$N $FILE\"',\n    'if [ -n \"$FILE\" ] && [ -f \"$FILE\" ]; then size=$(wc -c < \"$FILE\"); echo \"@@SIZE-$N $size\"; FROM=$OFF; if [ \"$OFF\" -eq 0 ] && [ \"$size\" -gt \"$CAP\" ]; then FROM=$((size - CAP)); fi; echo \"@@FROM-$N $FROM\"; if [ \"$size\" -gt \"$FROM\" ]; then echo \"@@DATA-$N\"; tail -c +$((FROM+1)) \"$FILE\"; echo; echo \"@@ENDDATA-$N\"; fi; fi',\n    /*\n     * The chosen subagent's own transcript, capped the same way as the session's.\n     *\n     * claude keeps them beside the session's file, in a directory named for it. agy gives\n     * each subagent a brain of its own - a directory under the same root as the parent's,\n     * named for the subagent's conversation id - so there is no \"beside\" to point at, only\n     * another session read exactly like this one.\n     */\n    ...(cli === 'agy' ? [\n      'if [ -n \"$SUB\" ]; then SF=\"$BRAIN/$SUB/.system_generated/logs/transcript.jsonl\"; fi',\n    ] : [\n      'if [ -n \"$SUB\" ] && [ -n \"$FILE\" ]; then SF=\"${FILE%.jsonl}/subagents/agent-$SUB.jsonl\"; fi',\n    ]),\n    'if [ -n \"$SF\" ] && [ -f \"$SF\" ]; then ssize=$(wc -c < \"$SF\"); echo \"@@SSIZE-$N $ssize\"; SFROM=$SOFF; if [ \"$SOFF\" -eq 0 ] && [ \"$ssize\" -gt \"$CAP\" ]; then SFROM=$((ssize - CAP)); fi; if [ \"$ssize\" -gt \"$SFROM\" ]; then echo \"@@SDATA-$N\"; tail -c +$((SFROM+1)) \"$SF\"; echo; echo \"@@ENDSDATA-$N\"; fi; fi',\n    /*\n     * Every subagent's last line and when it was written, for the list of them.\n     *\n     * The head line carries the subagent's NAME after its mtime for agy, because that is\n     * the only place agy says what one is for: claude names a subagent in the Agent call\n     * that started it, which the transcript already has, and agy records it in a file of\n     * its own - `{\"subagentDescriptor\":{\"typeName\":\"repro-recorder\",\"role\":\"Misc bug\n     * recorder\"}}`. The reader takes everything after the mtime as the name, so claude's\n     * lines, which have nothing after it, are unchanged.\n     *\n     * NOTE the quoting. This grep used to be written `grep \"\\\"type\\\":\\\"assistant\\\"\"`,\n     * and in a single-quoted JavaScript string `\\\"` is just `\"` - so the shell was handed\n     * `grep \"\"type\":\"assistant\"\"`, which it concatenates into the pattern `type:assistant`.\n     * That matches nothing in a transcript, so every subagent's last line has been empty\n     * since this was written; only the mtime beside it (and so \"6 working\") ever worked.\n     * Single quotes inside a template literal, which survive both languages intact.\n     */\n    ...(cli === 'agy' ? [\n      'SUBS=\"$BRAIN/$uuid/.system_generated/subagents\"',\n      'if [ -n \"$uuid\" ] && [ -d \"$SUBS\" ]; then for f in \"$SUBS\"/*.json; do [ -f \"$f\" ] || continue; id=$(basename \"$f\" .json); T=\"$BRAIN/$id/.system_generated/logs/transcript.jsonl\"; [ -f \"$T\" ] || continue;',\n      /*\n       * The backslashes are doubled on purpose.\n       *\n       * A template literal refuses `\\(` as an invalid escape and `\\1` as an octal one, and\n       * a single-quoted string - how the broken grep above was written - drops the\n       * backslash silently and hands sed a pattern with no group in it. `\\\\(` in the\n       * source is `\\(` in the string, which is what sed's BRE wants.\n       */\n      `  role=$(sed -n 's/.*\"role\":\"\\\\([^\"]*\\\\)\".*/\\\\1/p' \"$f\" | head -1)`,\n      '  echo \"@@TAIL-$N $id $(stat -c %Y \"$T\") $role\"',\n      `  tail -c 6000 \"$T\" | grep -F '\"source\":\"MODEL\"' | tail -n 1 | cut -c1-3000`,\n      'done; echo \"@@ENDTAILS-$N\"; fi',\n    ] : [\n      'if [ -n \"$FILE\" ] && [ -d \"${FILE%.jsonl}/subagents\" ]; then for f in \"${FILE%.jsonl}\"/subagents/agent-*.jsonl; do [ -f \"$f\" ] || continue; id=$(basename \"$f\" .jsonl); id=${id#agent-}; echo \"@@TAIL-$N $id $(stat -c %Y \"$f\")\";',\n      `  tail -c 6000 \"$f\" | grep -F '\"type\":\"assistant\"' | tail -n 1 | cut -c1-3000`,\n      'done; echo \"@@ENDTAILS-$N\"; fi',\n    ]),\n    // The hook state file (seed/chat-hook.mjs): the last thing claude said it was doing.\n    'echo \"@@HOOK-$N\"; cat \"$(dirname \"$HOME\")/sessions/$ID.state.json\" 2>/dev/null; echo; echo \"@@ENDHOOK-$N\"',\n    /*\n     * Whether the CLI is running in the pane at all. The pane's own command is the loop that\n     * runs it (claude-session.sh, agy-session.sh), so the CLI is that loop's child - and a\n     * pane with the loop but no child is a shell, whatever the transcript's last line says.\n     *\n     * The program's name is the CLI's: this asked for `claude` on every pane, so an\n     * Antigravity pane with agy running in it reported nothing, and the chat said\n     * \"Antigravity is not running in this pane\" under a conversation that was answering.\n     */\n    `if tmux has-session -t \"mc-$ID\" 2>/dev/null; then P=$(tmux display -p -t \"mc-$ID\" \"#{pane_pid}\" 2>/dev/null); [ -n \"$P\" ] && pgrep -P \"$P\" -x ${ cli } >/dev/null 2>&1 && echo \"@@ALIVE-$N\"; fi`,\n    'echo \"@@PANE-$N\"',\n    'if tmux has-session -t \"mc-$ID\" 2>/dev/null; then tmux capture-pane -p -t \"mc-$ID\" | tail -n 40; else echo \"@@NOPANE-$N\"; fi',\n  ].join('\\n');\n}\n",
  "claude-credentials.mjs": "// One claude login, shared by every pod, through a Kubernetes Secret.\n//\n//   node /seed/claude-credentials.mjs pull    before claude starts\n//   node /seed/claude-credentials.mjs push    after it has run\n//   node /seed/claude-credentials.mjs sync    the daemon that keeps both in step\n//\n// The reason both halves exist is the same reason the harness mirrors its credential file\n// between the global session and the project containers: OAuth tokens refresh, and whoever\n// refreshed last has the only working one. Pull without push means every pod that did not do\n// the refresh is stranded on a token that has expired; push without pull means a pod that has\n// never been logged in stays that way.\n//\n// `sync` is what makes it happen without anyone thinking about it. claude reads its token once,\n// at startup, and rotates it as it runs - and the refresh token is single use, so the moment one\n// pod's claude refreshes, every other pod still holding the old one is a login waiting to fail.\n// The daemon runs one per pod: it pushes this pod's token up whenever it is the newer one (a\n// refresh here, or a fresh `/login` in one of its panes), and when a newer login arrives from\n// somewhere else it pulls that down and restarts the conversations here onto it, so they resume\n// on the live token instead of dying on the dead one. Log in once, anywhere, and every open\n// conversation reconnects itself.\n//\n// Newest wins, on `expiresAt`, which is the only ordering these two copies have in common: file\n// mtimes are per pod and a pod that merely read the file would otherwise look newer than the\n// pod that refreshed it. A restart is gated on the refresh token actually differing, so a pod\n// adopting a token does not then turn round and think itself behind.\n//\n// Only the `claudeAiOauth` block moves. Everything else in the local file belongs to the pod\n// it is in, and the Secret is not a backup of it.\n//\n// It never fails loudly. A pod with no kubectl, no rights, or no Secret yet is a pod that is\n// not sharing a login, which is a thing to say on the way past rather than a reason to stop a\n// terminal from opening.\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\n\nconst MODE = process.argv[2] || 'pull';\nconst NAMESPACE = 'dev-system';\nconst SECRET = 'claude-credentials';\nconst KEY = 'credentials.json';\nconst HOME = process.env.HOME || os.homedir();\nconst LOCAL = path.join(HOME, '.claude', '.credentials.json');\n\n// Where the pane's loop and this daemon meet. shell.sh gives each pane an `MC_RESTART_FLAG`\n// under here (named for its tmux session); touching it tells that pane's loop to reconnect the\n// moment claude next stops, without waiting for a keypress. `$(dirname HOME)` is the volume both\n// the home and the sessions directory sit on, so the flag outlives neither more nor less than\n// they do.\nconst RESTART_DIR = path.join(path.dirname(HOME), '.restart');\n\n// One daemon per pod. shell.sh fires `sync` on every pane attach; the lock is what makes the\n// second and every one after it a no-op rather than a second daemon pushing against the first.\nconst LOCK = path.join(path.dirname(HOME), '.login-sync.lock');\n\n// How often the daemon looks. Fifteen seconds is far below a token's lifetime and far above the\n// cost of two reads, so a login is adopted within a breath of arriving and nothing is busy.\nconst INTERVAL_MS = (Number(process.env.MC_LOGIN_SYNC_INTERVAL) || 15) * 1000;\n\nfunction say(message) {\n  console.log(`[credentials] ${ message }`); // eslint-disable-line no-console\n}\n\n/**\n * kubectl as this pod, never as whoever is watching it.\n *\n * `KUBECONFIG` naming nothing sends kubectl to the in-cluster config, which is the pod's own\n * ServiceAccount. That is normally what it would pick anyway, and in the agent pod it is not:\n * a pane there has a kubeconfig holding the Rancher credential of the person who opened the\n * panel, and this Secret is in `dev-system`, where that person may have no rights at all. The\n * shared claude login is a property of the pods, so it is read and written by the pods.\n */\nfunction kubectl(args) {\n  return execFileSync('kubectl', args, {\n    encoding: 'utf8',\n    stdio:    ['ignore', 'pipe', 'pipe'],\n    env:      { ...process.env, KUBECONFIG: '/dev/null' },\n  });\n}\n\n/** A command whose absence or failure is not worth stopping for; the output, or '' either way. */\nfunction quiet(cmd, args) {\n  try {\n    return execFileSync(cmd, args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });\n  } catch {\n    return '';\n  }\n}\n\nfunction readLocal() {\n  try {\n    return JSON.parse(fs.readFileSync(LOCAL, 'utf8'));\n  } catch {\n    return {};\n  }\n}\n\nfunction readRemote() {\n  try {\n    const encoded = kubectl(['-n', NAMESPACE, 'get', 'secret', SECRET, '-o', `jsonpath={.data.${ KEY.replace('.', '\\\\.') }}`]).trim();\n\n    return encoded ? JSON.parse(Buffer.from(encoded, 'base64').toString('utf8')) : {};\n  } catch {\n    return null;\n  }\n}\n\n/** When the access token in a copy runs out, or 0 for a copy that has none. */\nfunction expiresAt(blob) {\n  return Number(blob?.claudeAiOauth?.expiresAt) || 0;\n}\n\n/** The refresh token, which changes on every login and every rotation; '' when there is none. */\nfunction refreshToken(blob) {\n  return String(blob?.claudeAiOauth?.refreshToken || '');\n}\n\n/**\n * Replace the file in one step.\n *\n * A terminal starting while this writes would otherwise be able to read half a token, and the\n * mode is set on the temporary file rather than after the rename so the file is never briefly\n * readable by anything else on the node.\n */\nfunction writeLocal(blob) {\n  fs.mkdirSync(path.dirname(LOCAL), { recursive: true });\n\n  const tmp = path.join(path.dirname(LOCAL), `.credentials.${ process.pid }`);\n\n  fs.writeFileSync(tmp, `${ JSON.stringify(blob, null, 2) }\\n`, { mode: 0o600 });\n  fs.renameSync(tmp, LOCAL);\n}\n\n/** Send this pod's token up, when it is the newer one. Returns whether it did. */\nfunction pushUp(local, remote) {\n  if (expiresAt(local) <= expiresAt(remote)) {\n    return false;\n  }\n\n  const merged = { ...remote, claudeAiOauth: local.claudeAiOauth };\n  const encoded = Buffer.from(JSON.stringify(merged)).toString('base64');\n\n  try {\n    kubectl([\n      '-n', NAMESPACE, 'patch', 'secret', SECRET, '--type=merge',\n      '-p', JSON.stringify({ data: { [KEY]: encoded } }),\n    ]);\n\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/** Whether a pid is a live process this user can signal. */\nfunction alive(pid) {\n  try {\n    process.kill(pid, 0);\n\n    return true;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * Stop the claude running in a pane, having first told its loop to reconnect at once.\n *\n * The pane's shell is `claude-session.sh`, and while claude is running it is that shell's only\n * foreground child. Signalling the child ends the `claude ... ` line the loop is blocked on; the\n * loop then sees the flag this leaves and goes straight back to claude - which, because the loop\n * pulls before every start, comes up on the token just written. A pane with no claude child (one\n * sitting at the loop's prompt, or a plain shell) is left alone: it has nothing to reconnect and\n * will pull the new token itself the next time it starts claude.\n */\nfunction reconnectPane(session) {\n  const id = session.startsWith('mc-') ? session.slice(3) : session;\n  const panePid = quiet('tmux', ['list-panes', '-t', session, '-F', '#{pane_pid}']).split('\\n')[0]?.trim();\n\n  if (!panePid) {\n    return;\n  }\n\n  // The claude process, if this pane has one. It is a child of the pane shell, but which child\n  // is not something `comm` can be trusted for: node reports its `comm` as `MainThread`, not\n  // `node`, so the reliable mark is the CLI's own name somewhere in the command line (the\n  // `claude` wrapper, or the node process running `.../claude-code/cli.js`). If nothing matches\n  // but the pane does have children, claude is stopping it the blunt way - every direct child -\n  // which is safe here: the only other child the loop ever has is its short-lived transcript\n  // watcher, and a pane sitting idle at the loop's prompt has no children at all, so it is left\n  // alone to pick the token up itself on its next start.\n  const children = quiet('pgrep', ['-P', panePid]).split('\\n').map((s) => s.trim()).filter(Boolean);\n\n  if (!children.length) {\n    return;\n  }\n\n  const named = children.filter((pid) => /claude/i.test(quiet('cat', [`/proc/${ pid }/cmdline`]).replace(/\\0/g, ' ')));\n  const targets = named.length ? named : children;\n\n  try {\n    fs.mkdirSync(RESTART_DIR, { recursive: true });\n    fs.writeFileSync(path.join(RESTART_DIR, id), '');\n  } catch {\n    // No flag means the loop falls back to its keypress prompt - a worse reconnection, not a\n    // broken one, so it is not worth refusing the restart over.\n  }\n\n  targets.forEach((pid) => {\n    try {\n      process.kill(Number(pid), 'SIGTERM');\n    } catch {\n      // Gone already, which is the state we wanted it in.\n    }\n  });\n}\n\n/** Every conversation open in this pod, reconnected onto the token just pulled. */\nfunction reconnectAll() {\n  const sessions = quiet('tmux', ['ls', '-F', '#{session_name}'])\n    .split('\\n')\n    .map((s) => s.trim())\n    .filter((s) => s.startsWith('mc-'));\n\n  sessions.forEach(reconnectPane);\n}\n\n/**\n * One turn of the daemon: share up, or adopt and reconnect down.\n *\n * The two are exclusive and ordered by which copy is newer. A restart is taken only when the\n * refresh token has actually changed, not merely when `expiresAt` has - a pod that has just\n * adopted a token would otherwise reconnect its panes a second time on the next turn.\n */\nfunction syncOnce() {\n  const local = readLocal();\n  const remote = readRemote();\n\n  if (remote === null) {\n    return;\n  }\n\n  if (expiresAt(local) > expiresAt(remote)) {\n    if (pushUp(local, remote)) {\n      say('shared this pod\\'s newer login with the others');\n    }\n\n    return;\n  }\n\n  if (expiresAt(remote) > expiresAt(local) && refreshToken(remote) && refreshToken(remote) !== refreshToken(local)) {\n    writeLocal({ ...local, claudeAiOauth: remote.claudeAiOauth });\n    // The token is on disk, which is all a pane needs the next time it starts claude. What\n    // is deliberately not done here is restarting the panes that are running.\n    //\n    // It used to. A conversation in the middle of something is not a thing to interrupt on\n    // a timer, and this turn comes round every fifteen seconds: while a login was being\n    // refreshed - a normal hour of a working day - every pane in the pod was killed and\n    // started again, repeatedly, whatever it was doing. Whoever is using them decides when\n    // that is worth it: Settings has a button for the shared browser, and it runs `reconnect` below.\n    say('a newer shared login arrived; panes keep the token they started with until they are restarted');\n  }\n}\n\n/** Take the pod's single daemon slot, or bow out because another already holds it. */\nfunction takeLock() {\n  try {\n    const fd = fs.openSync(LOCK, 'wx');\n\n    fs.writeSync(fd, String(process.pid));\n    fs.closeSync(fd);\n\n    return true;\n  } catch {\n    let holder = 0;\n\n    try {\n      holder = Number(fs.readFileSync(LOCK, 'utf8').trim());\n    } catch {\n      holder = 0;\n    }\n\n    if (holder && alive(holder)) {\n      return false;\n    }\n\n    // A dead holder's lock is stale; take it over.\n    try {\n      fs.writeFileSync(LOCK, String(process.pid));\n\n      return true;\n    } catch {\n      return false;\n    }\n  }\n}\n\nfunction releaseLock() {\n  try {\n    if (Number(fs.readFileSync(LOCK, 'utf8').trim()) === process.pid) {\n      fs.unlinkSync(LOCK);\n    }\n  } catch {\n    // Someone else's now, or already gone: not ours to remove.\n  }\n}\n\n// ── Dispatch ────────────────────────────────────────────────────────────────────────────────\n\n/**\n * `reconnect [id]` - what the button asks for: this pod's conversations, or one of them, put\n * back onto the token on disk. The same mechanism the daemon used to run by itself, now only\n * when somebody says so. The conversation is kept: the pane is not killed, claude inside it is,\n * and the loop that owns the pane starts it again on the same conversation.\n */\nif (MODE === 'reconnect') {\n  const only = process.argv[3];\n\n  if (only) {\n    reconnectPane(only.startsWith('mc-') ? only : `mc-${ only }`);\n    say(`reconnected ${ only }`);\n  } else {\n    reconnectAll();\n    say('reconnected every conversation in this pod');\n  }\n\n  process.exit(0);\n}\n\nif (MODE === 'sync') {\n  if (!takeLock()) {\n    process.exit(0);\n  }\n\n  process.on('exit', releaseLock);\n  ['SIGTERM', 'SIGINT', 'SIGHUP'].forEach((sig) => process.on(sig, () => process.exit(0)));\n\n  syncOnce();\n  setInterval(syncOnce, INTERVAL_MS);\n} else {\n  const local = readLocal();\n  const remote = readRemote();\n\n  if (remote === null) {\n    say('the shared secret is not readable from this pod, so this terminal keeps its own login');\n    process.exit(0);\n  }\n\n  if (MODE === 'push') {\n    if (pushUp(local, remote)) {\n      say('pushed a newer token to the shared secret');\n    }\n\n    process.exit(0);\n  }\n\n  // pull\n  if (expiresAt(remote) <= expiresAt(local)) {\n    process.exit(0);\n  }\n\n  writeLocal({ ...local, claudeAiOauth: remote.claudeAiOauth });\n  say('pulled the shared login');\n}\n",
  "claude-defaults.mjs": "// The settings a fresh claude stops and asks for, answered in advance.\n//\n// A pod is a fresh machine every time, so without this the first thing the\n// editor's terminal shows is a theme picker, then a \"do you trust this folder\"\n// dialog, then a \"Yes, I accept\" for bypass permissions - three questions whose\n// answers are the same every time and none of which the person opening the\n// editor is being asked anything real by. What they should land in is a prompt,\n// or a login.\n//\n// Only the flags are set here. The login itself is pulled from a Kubernetes\n// Secret before the pane starts (see claude-credentials.mjs); what this file\n// adds for it is the Stop hook that pushes a refreshed token back, so the pod\n// that happens to refresh does not leave every other pod on a stale one.\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { execFileSync } from 'node:child_process';\n\nconst HOME = process.env.HOME || '/app/.home';\nconst CONFIG = path.join(HOME, '.claude.json');\nconst SETTINGS = path.join(HOME, '.claude', 'settings.json');\n\n// The directories a pane may start claude in, which is not the same list in\n// every pod: the dev server's tabs land in its own tree, and a workspace's land\n// in the checkout it cloned. shell.sh passes the pane's own directory; the\n// default is this pod's source and the app around it, which is what boot.sh's\n// background run has no directory to pass.\n//\n// Found rather than named, because the package directory is called whatever the package is\n// called - the same rule PACKAGE_DIR uses. A pod with no tree yet trusts /app alone.\nfunction packageDir() {\n  try {\n    const dirs = fs.readdirSync('/app/pkg', { withFileTypes: true }).filter((entry) => entry.isDirectory());\n\n    return dirs.length ? [path.join('/app/pkg', dirs[0].name)] : [];\n  } catch {\n    return [];\n  }\n}\n\nconst TRUSTED = (process.env.TRUST_DIRS ? process.env.TRUST_DIRS.split(':') : [...packageDir(), '/app']).filter(Boolean);\n\nfunction read(file) {\n  try {\n    return JSON.parse(fs.readFileSync(file, 'utf8'));\n  } catch {\n    // Missing, or half-written by a claude that was killed. Either way the\n    // defaults below are a better starting point than failing here.\n    return {};\n  }\n}\n\n// Written back only when something actually changed. claude rewrites this file\n// as it runs, and this can be called while a session is attached, so the common\n// case (everything already set) must not touch it at all.\nfunction update(file, mutate) {\n  const before = read(file);\n  const after = JSON.parse(JSON.stringify(before));\n\n  mutate(after);\n\n  if (JSON.stringify(after) === JSON.stringify(before)) {\n    return false;\n  }\n\n  try {\n    fs.mkdirSync(path.dirname(file), { recursive: true });\n    fs.writeFileSync(file, `${ JSON.stringify(after, null, 2) }\\n`, { mode: 0o600 });\n  } catch (e) {\n    // A pane that cannot be pre-answered is worth having; a pane that will not start is not.\n    // This threw and took the conversation with it when the file had ended up owned by root\n    // (see shell.sh, which now repairs that before we get here): every tab in the pod showed\n    // an EACCES stack instead of claude. Say what happened and let claude ask its questions.\n    console.log(`[claude] could not write ${ file }: ${ e?.message || e }`);\n\n    return false;\n  }\n\n  return true;\n}\n\nfunction claudeVersion() {\n  try {\n    return execFileSync('claude', ['--version'], { encoding: 'utf8' }).trim().split(' ')[0];\n  } catch {\n    return undefined;\n  }\n}\n\nconst changed = [\n  update(CONFIG, (config) => {\n    // Skips the whole first-run flow, the theme picker included.\n    config.hasCompletedOnboarding = true;\n\n    // claude re-runs onboarding when its version is newer than this, so it is\n    // stamped with whatever is installed rather than hardcoded.\n    const version = claudeVersion();\n\n    if (version) {\n      config.lastOnboardingVersion = version;\n    }\n\n    config.projects = config.projects || {};\n\n    for (const dir of TRUSTED) {\n      config.projects[dir] = {\n        ...config.projects[dir],\n        // The pod's tree came from this extension's own seed, so asking whether\n        // it is trusted is asking the wrong side.\n        hasTrustDialogAccepted:       true,\n        hasCompletedProjectOnboarding: true,\n      };\n    }\n  }),\n\n  // The \"Yes, I accept\" dialog for --dangerously-skip-permissions, which the\n  // pane's claude is always started with, and the hook that shares a refreshed\n  // token with the other pods.\n  update(SETTINGS, (settings) => {\n    settings.skipDangerousModePermissionPrompt = true;\n\n    // Which model a pane starts on. Opus, unless somebody picked something else themselves:\n    // a home that outlives the pod keeps whatever `/model` last chose, and a choice made in a\n    // session should survive the next tab. What does not survive is the fable default an\n    // earlier build wrote here, which is the one this replaces.\n    if (!settings.model || /fable/i.test(String(settings.model))) {\n      settings.model = 'opus';\n    }\n\n    // Stop, not a session end: it runs every time claude finishes a response,\n    // which is the only moment this can be sure a refresh has already landed in\n    // the file. The script itself does nothing when the local copy is not newer,\n    // so running it that often costs a comparison.\n    //\n    // Merged rather than assigned, so a hook someone added by hand survives, and\n    // matched on the command so this cannot accumulate copies of itself.\n    const hooks = settings.hooks || (settings.hooks = {});\n\n    /**\n     * Whether a hook names a script this pod does not have.\n     *\n     * Not every pod carries every script. The agent pod's /seed is the terminal and nothing\n     * else - there is no extension tree in it, so no provenance to record - and a hook whose\n     * script is absent does not quietly do nothing: it ends every single turn with a\n     * MODULE_NOT_FOUND printed into the pane, under the answer.\n     */\n    const missingScript = (command) => {\n      const named = /\\/seed\\/[A-Za-z0-9._-]+/.exec(command || '');\n\n      return !!named && !fs.existsSync(named[0]);\n    };\n\n    // Written first, and this is a prune rather than a guard on the registration below because\n    // the home these settings live in outlives the pod. /app and /workspace are both hostPaths,\n    // so a settings file written by a pod that had a script is read by a later one that does\n    // not, and nothing else would ever take the dead hook back out.\n    for (const [event, list] of Object.entries(hooks)) {\n      const kept = list\n        .map((entry) => ({ ...entry, hooks: (entry.hooks || []).filter((hook) => !missingScript(hook.command)) }))\n        .filter((entry) => entry.hooks.length);\n\n      // The event goes with its last hook, so a pod that runs none of them has no hooks block\n      // rather than a row of empty lists for a reader to wonder about.\n      if (kept.length) {\n        hooks[event] = kept;\n      } else {\n        delete hooks[event];\n      }\n    }\n\n    /**\n     * Add one hook to one event, once.\n     *\n     * Matched on the command string rather than on position, for the reason the credentials\n     * hook already had: this runs on every boot and on every tab, and a settings file that\n     * accumulated a copy of each hook per tab would run the same commit five times.\n     *\n     * Skipped outright when this pod does not have the script, which is what keeps the list\n     * below readable: every hook this product wants is stated once, and the pods that cannot\n     * run one simply do not get it.\n     */\n    const register = (event, command, matcher) => {\n      if (missingScript(command)) {\n        return;\n      }\n\n      const list = hooks[event] || (hooks[event] = []);\n      const already = list.some((entry) => (entry.hooks || []).some((hook) => hook.command === command));\n\n      if (!already) {\n        const entry = { hooks: [{ type: 'command', command }] };\n\n        if (matcher) {\n          entry.matcher = matcher;\n        }\n\n        list.push(entry);\n      }\n    };\n\n    register('Stop', 'node /seed/claude-credentials.mjs push');\n\n    // What claude is doing, for the chat view: see chat-hook.mjs for why each of these.\n    for (const event of ['SessionStart', 'UserPromptSubmit', 'Stop', 'Notification', 'SessionEnd']) {\n      register(event, 'node /seed/chat-hook.mjs');\n    }\n\n    // Provenance: what produced each line of a change, recorded while it is being made. See\n    // barn-provenance.mjs for what these three record and, just as importantly, for the four\n    // things they deliberately do not claim.\n    //\n    // claude's own hooks rather than anything read off the pane. `tmux send-keys` is\n    // write-only, so the product can say what it sent and nothing about what happened next,\n    // and the pane's output is a character stream rather than a sequence of typed events.\n    register('UserPromptSubmit', 'node /seed/barn-provenance.mjs prompt');\n    register('PostToolUse', 'node /seed/barn-provenance.mjs touch', 'Edit|Write|MultiEdit|NotebookEdit');\n\n    // Last, so a refreshed credential is already pushed by the time this commits: both are\n    // Stop hooks and they run in the order they are listed.\n    register('Stop', 'node /seed/barn-provenance.mjs stop');\n  }),\n].some(Boolean);\n\nconsole.log(changed ? '[claude] defaults written' : '[claude] defaults already set');\n",
  "claude-session.sh": "#!/bin/bash\n# What runs in the tmux pane: claude, in a loop.\n#\n# The loop is the point. If claude exits - a crash, a /quit, an update - the\n# pane would die with it and take the tmux session down, so the next tab would\n# come up blank instead of where you left off. Restarting keeps the session, and\n# `--continue` means the restart resumes the conversation rather than opening a\n# new one. A run that ends in under three seconds is treated as an error and\n# backed off, so a claude that cannot start does not spin.\n#\n# bash rather than sh: `read` with no variable name is a bashism, and this is\n# the pane's interactive shell anyway.\n# The pane's own home, set by shell.sh in the tmux environment. The default is\n# only for a pane started some other way.\nexport HOME=${HOME:-/app/.home}\n\n# Ctrl-C at the prompt below leaves you in a shell rather than closing the pane.\n# While claude is running it is claude that gets the signal, not this script, so\n# this only fires where it is offered.\ntrap 'echo; exec /bin/bash' INT\n\nif ! command -v claude >/dev/null 2>&1; then\n  echo \"[claude is not installed in this pod - see $(dirname \"$HOME\")/.terminal-tools.log]\"\n  echo \"[dropping to a shell]\"\n  exec /bin/bash\nfi\n\n# A prompt somebody queued for this conversation, used once and then gone.\n#\n# Read before the loop rather than inside it: it is what this conversation is\n# for, and a restart of claude within the same pane should carry on rather than\n# ask the same thing again. Deleted before claude runs, not after, so a claude\n# that crashes on the prompt does not ask it again on every restart.\nQUEUE=${1:-}\nPROMPT=\"\"\n\nif [ -n \"$QUEUE\" ] && [ -f \"$QUEUE\" ]; then\n  PROMPT=$(cat \"$QUEUE\")\n  rm -f \"$QUEUE\"\nfi\n\n# The opening prompt is not run here, in a claude of its own, any more: that made a transcript\n# beside the one the loop below then started and recorded, so a reopened pane resumed the empty\n# loop conversation and the work the prompt began was stranded. It is handed instead to the\n# first fresh start inside the loop, so it runs in the very conversation this pane records and\n# resumes. Used once and then cleared - see the loop.\n\n# Which conversation belongs to this pane, when several share a directory.\n#\n# `--continue` resumes whatever was touched last in the working directory. That was safe while\n# every pane had a directory of its own; the agent panel now puts them all in one, so that any\n# pane's resume picker can see every conversation - and `--continue` would then have a pane\n# adopt whichever conversation another pane touched last, on its very first start.\n#\n# So a pane records the conversation it opened and resumes that one by name. The id comes from\n# claude's own transcripts: one .jsonl per conversation, named for it, under\n# ~/.claude/projects/<working directory with slashes turned to dashes>. The file that appears\n# while this pane is running is this pane's.\n#\n# $2 is where to keep that id. With no $2 - an extension's terminal, which still has a directory\n# to itself - this falls back to --continue, which is right there.\nID_FILE=${2:-}\nPROJECT_DIR=\"$HOME/.claude/projects/$(pwd | tr '/' '-')\"\n\ntranscripts() {\n  ls \"$PROJECT_DIR\"/*.jsonl 2>/dev/null | sort\n}\n\nBEFORE=$(mktemp)\nAFTER=$(mktemp)\ntrap 'rm -f \"$BEFORE\" \"$AFTER\"' EXIT\n\n# Only when exactly one transcript appeared. If another pane opened a conversation in the same\n# moment there is no way to tell them apart, and no id is better than the wrong one: no id\n# starts fresh, the wrong one resumes a stranger's conversation.\nremember_conversation() {\n  [ -n \"$ID_FILE\" ] || return 0\n\n  transcripts > \"$AFTER\"\n\n  new=$(comm -13 \"$BEFORE\" \"$AFTER\")\n\n  if [ \"$(printf '%s' \"$new\" | grep -c .)\" = \"1\" ]; then\n    basename \"$new\" .jsonl > \"$ID_FILE\"\n  fi\n}\n\nFAILS=0\n\nwhile true; do\n  start=$(date +%s)\n\n  # Adopt the latest shared login before (re)starting. claude reads its token once, at startup,\n  # so a restart is how this pane takes on a login done in another conversation - the sync\n  # (claude-credentials.mjs) stops claude here when a newer one arrives, and this is what makes\n  # the pane that comes back up hold it.\n  node /seed/claude-credentials.mjs pull >/dev/null 2>&1 || true\n\n  transcripts > \"$BEFORE\"\n\n  # Record which transcript this is as soon as claude has made one, not only when it exits:\n  # a pane that dies with its pod (the usual way one ends) never reaches remember_conversation,\n  # and the next start would open a new conversation instead of picking this one up.\n  if [ -n \"$ID_FILE\" ] && [ ! -s \"$ID_FILE\" ]; then\n    (\n      for _ in $(seq 1 150); do\n        sleep 2\n        new=$(comm -13 \"$BEFORE\" <(transcripts) 2>/dev/null)\n        if [ \"$(printf '%s' \"$new\" | grep -c .)\" = \"1\" ]; then\n          basename \"$new\" .jsonl > \"$ID_FILE\"\n          break\n        fi\n      done\n    ) &\n  fi\n\n  CONVERSATION=\"\"\n  if [ -n \"$ID_FILE\" ] && [ -s \"$ID_FILE\" ]; then\n    CONVERSATION=$(cat \"$ID_FILE\")\n  fi\n\n  # The queued opening prompt, given only to a fresh start and only once: it is what a new\n  # conversation is for, so it has to run in the conversation this pane records and resumes, not\n  # in one beside it. An empty array expands to no argument, so a start with nothing queued is\n  # unchanged. A resume never wants it. Cleared below, so a restart carries on rather than asks\n  # again.\n  OPEN=()\n  [ -n \"$PROMPT\" ] && OPEN=(\"$PROMPT\")\n\n  if [ -n \"$CONVERSATION\" ]; then\n    # This pane's own, by name. Falls through to a fresh one when it has been removed, which is\n    # what resuming something no longer there should do.\n    claude --dangerously-skip-permissions --resume \"$CONVERSATION\" 2>/dev/null ||\n      claude --dangerously-skip-permissions \"${OPEN[@]}\"\n  elif [ -n \"$ID_FILE\" ]; then\n    # First start in a shared directory: open a new conversation rather than adopt one.\n    claude --dangerously-skip-permissions \"${OPEN[@]}\"\n  else\n    # --continue fails when the directory has no conversation yet, which is the\n    # only reason for the fallback.\n    claude --dangerously-skip-permissions --continue 2>/dev/null ||\n      claude --dangerously-skip-permissions \"${OPEN[@]}\"\n  fi\n\n  PROMPT=\"\"\n\n  remember_conversation\n\n  end=$(date +%s)\n\n  # A newer shared login landed while this pane was running: the sync (claude-credentials.mjs)\n  # asked for a reconnection and stopped claude to get one. Go straight back - the top of the\n  # loop has already pulled the new token - without the pause below, which is for a person.\n  if [ -n \"$MC_RESTART_FLAG\" ] && [ -f \"$MC_RESTART_FLAG\" ]; then\n    rm -f \"$MC_RESTART_FLAG\"\n    echo \"\"\n    echo \"[a newer login arrived - reconnecting this conversation]\"\n    continue\n  fi\n\n  # A conversation is the pane, so a claude that stopped is one to bring back on its own rather\n  # than one to wait at a prompt for: having to press Enter to get your conversation back, and\n  # then resume it by hand, is the thing this loop exists to prevent. It restarts and the top of\n  # the loop resumes, so the pane returns to where it was without a keystroke.\n  #\n  # The exception is a claude that cannot stay up. Several starts that each died within a few\n  # seconds is a claude that is broken, not one that was exited, and restarting that is a spin -\n  # so after a run of them, and only then, the pane waits at a prompt where it can be dropped to\n  # a shell instead of churning. A start that lasted resets the count.\n  if [ $((end - start)) -lt 10 ]; then\n    FAILS=$((FAILS + 1))\n  else\n    FAILS=0\n  fi\n\n  if [ \"$FAILS\" -ge 3 ]; then\n    FAILS=0\n    echo \"\"\n    echo \"[claude keeps exiting immediately, which usually means an error.]\"\n    echo \"[press Enter to try again, Ctrl-C for a shell]\"\n    read -r || exec /bin/bash\n  else\n    echo \"\"\n    echo \"[claude exited - restarting, Ctrl-C for a shell]\"\n    # A short pause so a person who wanted out has a window for Ctrl-C (the trap drops to a\n    # shell), and so a claude failing just over the ten-second mark cannot spin at full speed.\n    sleep 2\n  fi\ndone\n",
  "dedupe-trees.mjs": "#!/usr/bin/env node\n// Collapse identical files across the workspaces on this node into one inode each.\n//\n// Every workspace is a checkout of the same repository, so their node_modules are the same\n// packages with a few differing versions. The install path already hardlinks a whole\n// node_modules out of a template when the lockfile hash matches exactly (apps.ts, lte.ts) - and\n// that is the trouble: a lockfile differing by one package shares nothing, and every PR branch\n// has its own lockfile. Measured on this node: seven workspaces, three templates, 6.3 GiB of\n// node_modules of which five workspaces held a full private copy.\n//\n// So this is the other half, and it keys on content rather than on a lockfile: files of equal\n// size and equal SHA-1 become one inode. It is safe here for the reason the install path's\n// comment already gives - nothing patches installed packages in place, and yarn replaces a file\n// rather than editing it, so a workspace that installs later breaks its own link and leaves\n// everybody else's copy alone.\n//\n// What it will not touch, because those ARE written in place - and a write through one path of a\n// hardlink is a write to every path that holds it:\n//   - a checkout's own working files: an editor and an agent's edit tool both write O_TRUNC\n//   - anything under a `.cache`, `.vite`, `.turbo` or `.git` directory\n//   - `node_modules/.bin` (symlinks, and rewritten by every install)\n//   - anything that is not a regular file, or is already the same inode\n//\n// Run from boot.sh: once a few minutes after start, then daily. It is interruptible - a link is\n// one rename-free `link()` call - and re-running it is a no-op.\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\n\n/** Where the trees are. One filesystem, which is what makes a hardlink possible at all. */\nconst ROOTS = process.argv.slice(2).length ? process.argv.slice(2) : ['/workspaces'];\n\n/** Below this a link saves nothing worth the inode churn: a block is 4 KiB. */\nconst MIN_BYTES = 4096;\n\n/*\n * What is never collapsed, and why each one.\n *\n * `.git` - git rewrites an index and a packfile by writing a new one and renaming over the old,\n *   which is safe for a hardlink, but it also keeps a lock file and a reflog it appends to. A\n *   repository is not worth the argument: it is 71 MiB of the ~1 GiB this sweep is after, and\n *   sharing git objects properly is `alternates`, not inode tricks.\n * `.cache`, `.vite`, `.turbo` - build caches, written in place by design.\n * `.bin` - symlinks and shims an install rewrites.\n * `.home/.claude`, `.home/.gemini` - a CLI's state: transcripts, settings and a conversation's\n *   own files, appended to while it runs.\n */\nconst SKIP_DIRS = new Set([\n  '.cache', '.vite', '.turbo', '.git', '.bin', '.yarn-integrity', '.claude', '.gemini', '.npm',\n]);\n\n/**\n * The trees worth walking: the ones nothing edits in place.\n *\n * It began as node_modules only, which is where the duplication was assumed to be. Measured\n * afterwards, node_modules was 3.9 GiB of it and the rest was everywhere else - 380 MiB of\n * `bin` across seven workspaces because each carries its own 54 MiB `gh`, and 1.3 GiB of homes\n * carrying their own copies of claude, jq and gh again.\n *\n * It is deliberately NOT the whole workspace. A hardlink is shared by every path that holds it,\n * so a write THROUGH one path is a write to all of them - and the one thing a workspace exists\n * for is somebody editing its checkout. An editor saving a file, or an agent's edit tool, opens\n * it O_TRUNC and writes in place: collapse two branches' identical `Card.vue` and an edit in one\n * workspace silently rewrites the other's checkout and leaves it dirty. So the checkout's own\n * working files are off limits, and what is left is the three kinds of tree nothing writes\n * through: installed packages, the tool binaries, and a home's cached toolchain.\n */\nfunction trees(root) {\n  const found = [];\n  const add = (...parts) => {\n    const candidate = path.join(...parts);\n\n    if (isDir(candidate)) {\n      found.push(candidate);\n    }\n  };\n\n  for (const entry of read(root)) {\n    if (entry === '.shared') {\n      for (const hash of read(path.join(root, entry, 'template'))) {\n        add(root, entry, 'template', hash, 'node_modules');\n      }\n      continue;\n    }\n    // `.artifacts` is somebody's evidence, already hardlinked into place by the capture.\n    if (entry.startsWith('.')) {\n      continue;\n    }\n\n    const workspace = path.join(root, entry);\n\n    if (!isDir(workspace)) {\n      continue;\n    }\n\n    // The leased tools and the home's own `.local/bin`: `gh`, `jq`, `claude`, `agy`.\n    add(workspace, 'bin');\n    add(workspace, '.home');\n    add(workspace, 'node_modules');\n\n    // Each checkout beside them contributes its node_modules and nothing else.\n    for (const child of read(workspace)) {\n      if (child === 'bin' || child === '.home' || child === 'artifacts' || child.startsWith('.')) {\n        continue;\n      }\n      add(workspace, child, 'node_modules');\n    }\n  }\n\n  return found;\n}\n\nfunction read(dir) {\n  try {\n    return fs.readdirSync(dir);\n  } catch {\n    return [];\n  }\n}\n\nfunction isDir(p) {\n  try {\n    return fs.statSync(p).isDirectory();\n  } catch {\n    return false;\n  }\n}\n\n/** Every regular file in a tree, with the facts a dedupe decides on. */\nfunction* files(dir) {\n  let entries = [];\n\n  try {\n    entries = fs.readdirSync(dir, { withFileTypes: true });\n  } catch {\n    return;\n  }\n\n  for (const entry of entries) {\n    const full = path.join(dir, entry.name);\n\n    if (entry.isDirectory()) {\n      if (!SKIP_DIRS.has(entry.name)) {\n        yield* files(full);\n      }\n      continue;\n    }\n    if (!entry.isFile()) {\n      continue;\n    }\n\n    try {\n      const stat = fs.lstatSync(full);\n\n      if (stat.isFile() && stat.size >= MIN_BYTES) {\n        yield { path: full, size: stat.size, ino: stat.ino, dev: stat.dev, mode: stat.mode };\n      }\n    } catch { /* a file that went away mid-walk is not this run's business */ }\n  }\n}\n\nfunction sha1(file) {\n  try {\n    return crypto.createHash('sha1').update(fs.readFileSync(file)).digest('hex');\n  } catch {\n    return '';\n  }\n}\n\n/**\n * Link `from` to `to`, via a temporary name.\n *\n * `link()` refuses an existing target, so the replacement is link-then-rename: at no point is\n * the path missing, and a crash leaves either the old file or the new link, never a gap. If\n * anything fails the original is untouched - which is the whole safety argument for doing this\n * to somebody's dependencies while they work.\n */\nfunction relink(keep, drop) {\n  const temp = `${ drop }.dedupe-${ process.pid }`;\n\n  try {\n    fs.linkSync(keep, temp);\n    fs.renameSync(temp, drop);\n\n    return true;\n  } catch {\n    try {\n      fs.unlinkSync(temp);\n    } catch { /* nothing to clean */ }\n\n    return false;\n  }\n}\n\nfunction main() {\n  const bySize = new Map();\n  let seen = 0;\n\n  for (const root of ROOTS) {\n    for (const tree of trees(root)) {\n      for (const file of files(tree)) {\n        seen++;\n        const key = `${ file.dev }:${ file.size }`;\n\n        (bySize.get(key) || bySize.set(key, []).get(key)).push(file);\n      }\n    }\n  }\n\n  let linked = 0;\n  let saved = 0;\n\n  for (const group of bySize.values()) {\n    if (group.length < 2) {\n      continue;\n    }\n    const byHash = new Map();\n\n    for (const file of group) {\n      const digest = sha1(file.path);\n\n      if (!digest) {\n        continue;\n      }\n      const same = byHash.get(digest);\n\n      if (!same) {\n        byHash.set(digest, file);\n        continue;\n      }\n      // Already one inode: nothing to do, and linking would be a no-op that costs a rename.\n      if (same.ino === file.ino) {\n        continue;\n      }\n      if (relink(same.path, file.path)) {\n        linked++;\n        saved += file.size;\n      }\n    }\n  }\n\n  const mib = (saved / (1024 * 1024)).toFixed(0);\n\n  console.log(`[dedupe] ${ seen } files considered, ${ linked } linked, ${ mib } MiB reclaimed`);\n}\n\nmain();\n",
  "git-store.sh": "#!/bin/sh\n# One copy of the repository, for every checkout on this node.\n#\n# Seven workspaces on this node, seven checkouts of rancher/dashboard, 873 MiB of `.git` between\n# them - and nearly all of it the same objects, because they are the same repository. It is the\n# last of the three per-workspace costs: the package caches became one store, the tool binaries\n# became one install, and this is the history.\n#\n# WHY NOT THE OBVIOUS THING. The dedupe sweep cannot touch a `.git` (it is written in place by\n# too much), and `cp -al`/`clone --local` hardlinking does not apply either, because every\n# checkout here is SHALLOW: the bootstrap in apps.ts does `git fetch --depth 1`, which is the\n# right thing for a workspace that wants one branch quickly, and git refuses to hardlink out of\n# a shallow source. So the mechanism has to be the one git provides for exactly this: an\n# ALTERNATE, a second object directory a repository is allowed to read from.\n#\n# WHAT THE STORE IS. A full mirror of upstream, kept here, plus the fork's branches under\n# `refs/fork/*`. Full rather than shallow on purpose: a shallow repository cannot serve as\n# anybody's alternate - a shallow boundary is a property of one repository, and lending objects\n# across one is how a repository ends up believing it has history it has not got.\n#\n# WHAT ATTACHING DOES, and the order matters:\n#\n#   1. The workspace's own refs are fetched INTO the mirror, under `refs/workspaces/<name>/*`.\n#      First, and the whole safety argument. Once a workspace reads its objects out of the\n#      mirror, a `git gc` in the mirror that pruned an unreferenced object would break that\n#      workspace with no warning and no way back. After this step every object any workspace\n#      depends on is reachable from a ref the mirror itself holds.\n#   2. The alternate is written, so the workspace can see the mirror's objects.\n#   3. The workspace is unshallowed against the mirror - locally, no network. With the alternate\n#      already in place this transfers almost nothing: the objects are already visible.\n#   4. `fsck`, BEFORE anything is deleted. If the repository is not whole at this point the\n#      alternate comes straight back off and the workspace is exactly as it was.\n#   5. `repack -a -d -l`: `-l` packs only what is NOT in the alternate, `-d` drops what is now\n#      redundant. This is the step that reclaims the disk, and it is deliberately last.\n#   6. `fsck` again. If this fails - it should not, the objects are in the mirror - the local\n#      packs are refetched from the mirror rather than left broken.\n#\n# Nothing here touches a worktree. Uncommitted changes, the index and stashes are untouched by\n# every command above; `refs/stash` is one of the refs step 1 copies into the mirror.\n#\n# Run from boot.sh: once at start, then daily to keep the mirror current.\nset -u\n\nSTORE=${STORE:-/workspaces/.store}\nMIRROR=\"$STORE/git/dashboard.git\"\nUPSTREAM=${UPSTREAM:-https://github.com/rancher/dashboard.git}\nFORK=${FORK:-https://github.com/codyrancher/dashboard.git}\n\n# Root owns this pod and the checkouts belong to the node user, which git calls dubious\n# ownership and refuses to work with.\n#\n# A config FILE, not `-c` and not GIT_CONFIG_COUNT, and this was established by testing all\n# three. Every local fetch here runs `git upload-pack` in the OTHER repository as a child\n# process, and that child does the ownership check on its own: a `-c` does not survive the\n# re-exec, and neither does GIT_CONFIG_COUNT/KEY/VALUE - measured, both still fail with\n# \"detected dubious ownership\" naming the source repository. GIT_CONFIG_GLOBAL names a file,\n# the child reads it like any global config, and the fetch goes through. The file is this\n# store's own, so root's ~/.gitconfig is left alone.\nGITCONFIG=\"$STORE/.gitconfig\"\nGIT_CONFIG_GLOBAL=\"$GITCONFIG\"\nexport GIT_CONFIG_GLOBAL\n\nsay() {\n  echo \"[git-store] $*\"\n}\n\nprepare() {\n  mkdir -p \"$STORE/git\" 2>/dev/null\n  [ -f \"$GITCONFIG\" ] || printf '[safe]\\n\\tdirectory = *\\n' > \"$GITCONFIG\"\n}\n\nensure_mirror() {\n  if [ -d \"$MIRROR\" ]; then\n    # --prune would delete a remote-tracking ref that upstream deleted; the workspace namespaces\n    # are not touched by it, which is why they are where they are.\n    git -C \"$MIRROR\" fetch --quiet --prune origin '+refs/heads/*:refs/heads/*' 2>&1 | tail -2\n    git -C \"$MIRROR\" fetch --quiet --no-tags fork '+refs/heads/*:refs/fork/*' 2>&1 | tail -2\n    say \"mirror up to date ($(du -sh \"$MIRROR\" 2>/dev/null | cut -f1))\"\n\n    return 0\n  fi\n\n  say 'building the mirror; this is the one slow run'\n  mkdir -p \"$STORE/git\" || return 1\n  rm -rf \"$MIRROR.partial\"\n\n  # Into a .partial name and moved when complete, so an interrupted clone is never mistaken for\n  # a mirror - a half-built one would be attached to and would be missing objects.\n  git clone --mirror \"$UPSTREAM\" \"$MIRROR.partial\" || { rm -rf \"$MIRROR.partial\"; return 1; }\n  git -C \"$MIRROR.partial\" remote add fork \"$FORK\" 2>/dev/null\n  git -C \"$MIRROR.partial\" fetch --no-tags fork '+refs/heads/*:refs/fork/*' || true\n  mv \"$MIRROR.partial\" \"$MIRROR\" || return 1\n  say \"mirror built ($(du -sh \"$MIRROR\" 2>/dev/null | cut -f1))\"\n}\n\nattached() {\n  grep -qs \"$MIRROR/objects\" \"$1/.git/objects/info/alternates\" 2>/dev/null\n}\n\ndetach() {\n  rm -f \"$1/.git/objects/info/alternates\"\n}\n\nattach() {\n  work=$1\n  name=$(basename \"$(dirname \"$work\")\")\n\n  [ -d \"$work/.git\" ] || return 0\n  if attached \"$work\"; then\n    say \"$name: already attached\"\n\n    return 0\n  fi\n\n  before=$(du -sm \"$work/.git\" 2>/dev/null | cut -f1)\n\n  # 1. Its refs into the mirror, so the mirror can never gc an object it depends on.\n  if ! git -C \"$MIRROR\" fetch --quiet --no-tags \"$work\" \"+refs/*:refs/workspaces/$name/*\"; then\n    say \"$name: could not copy its refs into the mirror; leaving it alone\"\n\n    return 1\n  fi\n\n  # 2. The alternate.\n  mkdir -p \"$work/.git/objects/info\"\n  echo \"$MIRROR/objects\" >> \"$work/.git/objects/info/alternates\"\n\n  # 3. Unshallow against the mirror. Local, and nearly free with the alternate in place.\n  if [ -f \"$work/.git/shallow\" ]; then\n    git -C \"$work\" fetch --quiet --unshallow \"$MIRROR\" 2>/dev/null ||\n      git -C \"$work\" fetch --quiet \"$MIRROR\" 2>/dev/null || true\n  fi\n\n  # 4. Whole BEFORE anything is deleted, or the alternate comes back off.\n  if ! git -C \"$work\" fsck --connectivity-only --no-progress >/dev/null 2>&1; then\n    detach \"$work\"\n    say \"$name: not whole with the alternate attached; reverted, nothing deleted\"\n\n    return 1\n  fi\n\n  # 5. The step that reclaims the disk: pack only what the alternate has not got.\n  git -C \"$work\" repack -a -d -l --quiet 2>/dev/null\n  git -C \"$work\" prune-packed 2>/dev/null\n\n  # 6. And whole afterwards. If not, take the objects back from the mirror rather than leave a\n  # broken checkout - the mirror has them, that is the point of it.\n  if ! git -C \"$work\" fsck --connectivity-only --no-progress >/dev/null 2>&1; then\n    say \"$name: not whole after repack; refetching from the mirror\"\n    detach \"$work\"\n    git -C \"$work\" fetch --quiet \"$MIRROR\" '+refs/heads/*:refs/heads/*' 2>/dev/null\n\n    return 1\n  fi\n\n  after=$(du -sm \"$work/.git\" 2>/dev/null | cut -f1)\n  say \"$name: attached, .git ${before}M -> ${after}M\"\n}\n\nprepare\nensure_mirror || { say 'the mirror is not there and could not be built; nothing attached'; exit 1; }\n\n# The checkouts run as the node user and read their objects out of here; the mirror is built by\n# root. Owned by node so a workspace is never reading somebody else's repository.\nchown -R node:node \"$MIRROR\" 2>/dev/null || true\n\n# One spot. `.store` is where the node's durable data lives, and the two that were already\n# central are given their place in it by name - a link, not a move, because dev-api and the\n# capture address them by their own paths and a move would be a rename nothing else knows about.\n[ -e \"$STORE/artifacts\" ] || ln -s /workspaces/.artifacts \"$STORE/artifacts\" 2>/dev/null\n[ -e \"$STORE/packages\" ] || ln -s /workspaces/.shared \"$STORE/packages\" 2>/dev/null\n\n# Named checkouts, or every one on the node. Naming one is how this was tested before it was\n# ever pointed at somebody's working tree: the same code path, run against a copy.\nif [ \"$#\" -gt 0 ]; then\n  for work in \"$@\"; do\n    attach \"$work\"\n  done\nelse\n  for work in /workspaces/*/dashboard; do\n    [ -d \"$work/.git\" ] || continue\n    attach \"$work\"\n  done\nfi\n\nsay \"store: $(du -sh \"$STORE/git\" 2>/dev/null | cut -f1) of history, serving $(grep -ls \"$MIRROR/objects\" /workspaces/*/dashboard/.git/objects/info/alternates 2>/dev/null | wc -l) attached checkouts\"\n",
  "keep-artifacts.sh": "#!/bin/sh\n# Keep every live workspace's artifacts, continuously, instead of only as it is deleted.\n#\n# The capture used to run in one place: removeWorkspaceTree, just before the `rm -rf`. That is\n# the right moment but the only one, and it makes the evidence depend on the delete going\n# through this code - a workspace removed by deleting its Installation, a tree cleaned up by\n# hand, a node that lost the pod, and the recordings a review comment points at are gone with\n# no way back. The files are meant to be the sticky half of a workspace that is meant to be\n# disposable; something has to hold them that is not the delete path.\n#\n# So: the same `cp -al` the capture does, on a timer. It costs nothing to repeat - a hardlink to\n# an inode that is already linked here is skipped by `cp -n`, and a file that has not changed is\n# the same inode - so this walks a few thousand names and writes almost nothing.\n#\n# The set keeps the workspace's name, which is what the Artifacts page already reads a subject\n# out of (`artifact-subjects.mjs`: `lte-pr-19612` is pull request 19612, and a live workspace and\n# every kept set that agree about that are one subject on the page). Nothing here needs to know\n# that - it only has to put the files where that page looks.\n#\n# What it will not do is delete anything, here or there. A file removed from a workspace stays\n# in the set: \"it stays until somebody decides to remove it\" is the whole contract.\nset -u\n\nROOT=${1:-/workspaces}\nSETS=\"$ROOT/.artifacts\"\n\nmkdir -p \"$SETS\" 2>/dev/null || true\n\nkept=0\nfor src in \"$ROOT\"/*/artifacts; do\n  [ -d \"$src\" ] || continue\n\n  ws=$(basename \"$(dirname \"$src\")\")\n  case \"$ws\" in .*) continue ;; esac\n\n  # Nothing recorded is not a failure, and must not leave an empty set behind.\n  [ -n \"$(ls -A \"$src\" 2>/dev/null)\" ] || continue\n\n  dst=\"$SETS/$ws\"\n  mkdir -p \"$dst\" 2>/dev/null || continue\n\n  # `-u`, not `-n`. `-n` leaves every name already in the set exactly as it is, which is right\n  # for a recording - written once, under a name nothing reuses - and wrong for the one kind of\n  # artifact that is rewritten in place: a review note an agent keeps adding to. With `-n` the\n  # set would hold the first paragraph it ever wrote and never the finished note. `-u` keeps the\n  # newer of the two, and `-f` is what lets it: a hardlink cannot be made over an existing name,\n  # so the old one is unlinked first - which removes the set's own name for it, not the file.\n  # An unchanged file has the same timestamp and is skipped, so a run over a settled workspace\n  # still writes nothing.\n  cp -alfu \"$src/.\" \"$dst/\" 2>/dev/null || cp -afu \"$src/.\" \"$dst/\" 2>/dev/null || true\n\n  # Only when there is nothing there to say it: a tag written at capture time carries a\n  # `capturedAt` and may say what the name cannot, and this is not the place to overrule it.\n  if [ ! -f \"$dst/.set.json\" ]; then\n    printf '{\"workspace\":\"%s\",\"keptBy\":\"live\"}' \"$ws\" > \"$dst/.set.json\" 2>/dev/null || true\n  fi\n\n  kept=$((kept + 1))\ndone\n\necho \"[artifacts] $kept live workspace(s) kept into $SETS\"\n",
  "mount-downstream.sh": "#!/bin/sh\n# Keep each downstream-hosted workspace mounted at /workspaces/<name> in this agent pod, so a\n# conversation's pane - which always runs here - sees the files of a workspace running on another\n# cluster exactly as it sees a local one.\n#\n# A local workspace's tree is on this pod's node and is already at /workspaces/<name> through the\n# shared hostPath; this touches only workspaces on another cluster, whose tree is on that\n# cluster's node and so absent here. Their files ride sshfs over the kubectl-exec channel - no\n# sshd, no port-forward, no keys - through the Rancher proxy for the workspace's own cluster,\n# authenticated by the durable token in the downstream-exec Secret. FUSE needs this container to\n# be privileged (the Deployment sets it) and allow_other so the node user's panes can read a\n# mount root made here. The exec tunnel for commands is the workspace's own bin/dev-shell, which\n# layout.mjs writes cluster-aware to match. See downstream-conversation-mount.\nSECRET=/var/run/downstream-exec\nWRAP=/workspace/.mounts\nSFTP=/usr/lib/openssh/sftp-server\nLOCAL=local\nPATH=/workspace/.home/.local/bin:/usr/local/bin:/usr/bin:/bin:$PATH\nexport PATH\n\n# The tools this needs arrive asynchronously: kubectl from terminal-tools.sh, sshfs from boot.sh.\nn=0\nwhile ! command -v sshfs >/dev/null 2>&1 || ! command -v kubectl >/dev/null 2>&1; do\n  n=$((n + 1))\n  [ \"$n\" -gt 120 ] && { echo \"sshfs/kubectl never arrived; not mounting\"; exit 0; }\n  sleep 10\ndone\n\n# Run this instead of ssh: sshfs appends \"host -s sftp\", which is ignored, and the command pipes\n# straight to sftp-server in the workspace pod over the exec channel via the cluster's proxy.\nwrite_wrapper() {\n  name=$1; cluster=$2\n  mkdir -p \"$WRAP\"\n  cat > \"$WRAP/$name.sftp\" <<EOF\n#!/bin/sh\nexec kubectl --server=$RURL/k8s/clusters/$cluster --token=$TOKEN --insecure-skip-tls-verify=true exec -i -n dev-$name deploy/dev-$name -c workspace -- $SFTP\nEOF\n  chmod +x \"$WRAP/$name.sftp\"\n}\n\n# The node image has no sftp-server; install it once per pod (idempotent, fast when present).\nensure_sftp() {\n  name=$1; cluster=$2\n  kubectl --server=\"$RURL/k8s/clusters/$cluster\" --token=\"$TOKEN\" --insecure-skip-tls-verify=true \\\n    exec -n \"dev-$name\" \"deploy/dev-$name\" -c workspace -- \\\n    sh -c \"test -x $SFTP || { apt-get update -qq && apt-get install -y -qq openssh-sftp-server; } >/dev/null 2>&1\" >/dev/null 2>&1\n}\n\nmount_one() {\n  name=$1; cluster=$2; dir=/workspaces/$name\n  # Already mounted and answering: nothing to do. A live sshfs mount stats quickly.\n  if mountpoint -q \"$dir\" 2>/dev/null; then\n    timeout 5 ls \"$dir\" >/dev/null 2>&1 && return 0\n    # Mounted but dead: the exec channel dropped and reconnect did not bring it back, so every\n    # access is an I/O error (and mkdir below would fail on it). Force it off - lazily, in case a\n    # handle is stuck - so it can be remounted fresh this pass.\n    echo \"$(date -u +%FT%TZ) $name mount is dead, remounting\"\n    fusermount3 -uz \"$dir\" 2>/dev/null || umount -l \"$dir\" 2>/dev/null\n  fi\n  ensure_sftp \"$name\" \"$cluster\"\n  write_wrapper \"$name\" \"$cluster\"\n  mkdir -p \"$dir\" 2>/dev/null\n  sshfs -o ssh_command=\"$WRAP/$name.sftp\" x:/workspaces/$name \"$dir\" \\\n    -o reconnect,ServerAliveInterval=15,ServerAliveCountMax=3,allow_other 2>/dev/null \\\n    && echo \"$(date -u +%FT%TZ) mounted $name ($cluster)\"\n}\n\n# The seed - bin/dev-shell (cluster-aware, since DEV_CLUSTER is set), the tools, .claude, CLAUDE.md.\n# For a local workspace the workspace pod fetches this itself (workspace-tools ensureSeed); a\n# downstream pod cannot reach the local dev-api, so it is laid out here instead, from the agent pod\n# which can - written into the mount, which is the workspace pod's own disk. Refreshed only when the\n# seed version or the workspace's issue/pr changes, recorded in the same .dev-seed marker ensureSeed\n# reads, so the browser side skips a workspace this has already done.\nSEED_URL=http://dev-api.dev-system.svc:8080/agent-seed\nSEEDJSON=/workspace/.dev-seed.json\nLAYOUT=/workspace/.dev-layout.mjs\nSEEDVER=\n\nfetch_seed() {\n  curl -fsS -m 30 \"$SEED_URL\" -o \"$SEEDJSON\" 2>/dev/null || return 1\n  node -e \"const s=require(process.argv[1]);require('fs').writeFileSync(process.argv[2],s['layout.mjs'])\" \"$SEEDJSON\" \"$LAYOUT\" 2>/dev/null || return 1\n  SEEDVER=$(curl -fsS -m 10 \"$SEED_URL/version\" 2>/dev/null | sed -n 's/.*\"version\" *: *\"\\([^\"]*\\)\".*/\\1/p')\n  [ -n \"$SEEDVER\" ] || SEEDVER=unknown\n  return 0\n}\n\nlayout_one() {\n  name=$1; cluster=$2; dir=/workspaces/$name\n  [ -f \"$LAYOUT\" ] || return 0\n  issue=$(printf '%s' \"$name\" | sed -n 's/^issue-\\([0-9][0-9]*\\).*/\\1/p')\n  pr=$(printf '%s' \"$name\" | sed -n 's/^pr-\\([0-9][0-9]*\\).*/\\1/p')\n  marker=\"$SEEDVER:$issue:$pr:$name\"\n  [ \"$(cat \"$dir/.dev-seed\" 2>/dev/null)\" = \"$marker\" ] && return 0\n  if DEV_PROJECT=\"$name\" DEV_ISSUE=\"$issue\" DEV_PR=\"$pr\" DEV_CLUSTER=\"$cluster\" \\\n     DEV_ROOT=\"$dir\" DEV_WORKDIR=\"$dir/dashboard\" DEV_HOME=\"$dir/.home\" DEV_SEED_FILE=\"$SEEDJSON\" \\\n     node \"$LAYOUT\" >/dev/null 2>&1; then\n    printf '%s' \"$marker\" > \"$dir/.dev-seed\"\n    echo \"$(date -u +%FT%TZ) laid out seed for $name ($cluster)\"\n  fi\n}\n\nwhile true; do\n  TOKEN=$(cat \"$SECRET/token\" 2>/dev/null)\n  RURL=$(cat \"$SECRET/rancherUrl\" 2>/dev/null)\n  if [ -n \"$TOKEN\" ] && [ -n \"$RURL\" ]; then\n    fetch_seed\n    # The workspaces this Rancher knows, each with the cluster it runs on. Read on this (local)\n    # cluster, where every workspace's Installation lives whatever cluster it deploys to.\n    kubectl get appinstances.appsplus.io -A -o jsonpath='{range .items[*]}{.metadata.labels.dev\\.rancher\\.io/workspace}{\" \"}{.metadata.labels.dev\\.rancher\\.io/cluster}{\"\\n\"}{end}' 2>/dev/null | \\\n    while read -r name cluster; do\n      [ -n \"$name\" ] && [ -n \"$cluster\" ] || continue\n      [ \"$cluster\" = \"$LOCAL\" ] && continue\n      # A preview is a built page with no shell, so nothing runs a conversation in it.\n      case \"$name\" in preview-*) continue ;; esac\n      # mount_one mounts if absent and remounts if the existing mount has gone dead.\n      mount_one \"$name\" \"$cluster\"\n      # Once it answers, lay the seed into it (from here - the workspace pod can't fetch it itself).\n      timeout 5 ls \"/workspaces/$name\" >/dev/null 2>&1 && layout_one \"$name\" \"$cluster\"\n    done\n  fi\n  sleep 20\ndone\n",
  "rancher-credential.sh": "#!/bin/sh\n# Give this pod's panes the identity of the person who opened the terminal.\n#\n#   /bin/sh /seed/rancher-credential.sh <home-dir>\n#\n# Run by shell.sh before a pane starts, and a no-op everywhere except the agent pod, where the\n# file exists at all.\n#\n# ---------------------------------------------------------------------------\n# Why a pod needs this when it already has a ServiceAccount.\n#\n# It has one, and it is bound to cluster-admin, and that is the wrong credential twice over.\n# Rancher does not accept a Kubernetes ServiceAccount token - it resolves to `system:cattle:error`\n# and every call comes back 401 or 403 - so the Studio's own API, which forwards whatever\n# credential its caller presented, answers this pod 401 and there is nothing it can do about it.\n# And where the ServiceAccount does work, against the apiserver directly, it works as\n# cluster-admin: more than the person watching the terminal is likely to have, attributable to\n# nobody, and the same for everyone who opens the panel.\n#\n# So the browser mints a Rancher API token as whoever is signed in, puts it in a Secret, and\n# this reads it back. What the pane gets is that person's rights and no more:\n#\n#   ~/.kube/config      kubectl, through Rancher's cluster proxy, as them\n#   ~/.rancher/env      RANCHER_TOKEN and the two addresses, for curl\n#\n# One token reaches all of it, which is the point of doing it this way rather than per API:\n# Rancher's own /v1 and /v3, the apiserver under /k8s/clusters/local, the Studio's service, and\n# any extension in the API registry, since a registry entry's URL is a path on the same host.\n#\n# It never fails loudly. A pod whose Secret has not been written yet - nobody has opened the\n# panel since it was created - is a pod with no Rancher identity, which is a thing to say on the\n# way past and not a reason to refuse somebody a terminal.\nset -e\n\nHOME_DIR=${1:-/workspace/.home}\n\n# The pod's own namespace, read rather than named: this pod moved from `extension-studio` to\n# `dev-agents` and a script that names one of them is wrong in a pod of the other. The\n# ServiceAccount's own namespace file is the pod's, whichever that is.\nNAMESPACE=$(cat /var/run/secrets/kubernetes.io/serviceaccount/namespace 2>/dev/null || echo dev-agents)\nSECRET=${AGENT_CREDENTIAL_SECRET:-agent-credential}\n\n# A pod still in the old namespace reads the old name, so the same script serves both until every\n# pod has rolled.\nif [ \"$NAMESPACE\" = extension-studio ]; then\n  SECRET=extension-studio-agent-credential\nfi\n\nsay() {\n  echo \"[rancher] $1\"\n}\n\n# The ServiceAccount, explicitly, because the file this script is about to write would otherwise\n# be the credential it uses to read its own replacement. `KUBECONFIG` naming nothing sends\n# kubectl to the in-cluster config, which is the SA - checked in the pod rather than assumed.\nsa_kubectl() {\n  KUBECONFIG=/dev/null kubectl \"$@\"\n}\n\nTOKEN=$(sa_kubectl -n \"$NAMESPACE\" get secret \"$SECRET\" -o jsonpath='{.data.token}' 2>/dev/null | base64 -d 2>/dev/null || true)\n\nif [ -z \"$TOKEN\" ]; then\n  say \"no Rancher credential yet - the panel writes one when somebody opens it\"\n  exit 0\nfi\n\nUSER_NAME=$(sa_kubectl -n \"$NAMESPACE\" get secret \"$SECRET\" -o jsonpath='{.data.user}' 2>/dev/null | base64 -d 2>/dev/null || true)\n\nif [ -z \"$RANCHER_URL\" ]; then\n  say \"RANCHER_URL is not set on this pod, so there is no address to point a credential at\"\n  exit 0\nfi\n\n# Written whole and moved into place, and the mode set on the temporary file rather than after\n# the rename, so a second pane starting mid-write reads either the old file or the new one and\n# never a half of either, and neither is ever briefly readable by anything else on the node.\nwrite_private() {\n  dest=$1\n  tmp=\"$dest.$$\"\n\n  mkdir -p \"$(dirname \"$dest\")\"\n  cat > \"$tmp\"\n  chmod 600 \"$tmp\"\n  mv \"$tmp\" \"$dest\"\n}\n\n# `insecure-skip-tls-verify`, because RANCHER_URL is the node's address and Rancher's\n# certificate is issued for its hostname. This is the same hop the browser makes and the same\n# one every curl in the seeded CLAUDE.md makes with -k; pretending otherwise would mean shipping\n# a kubeconfig that cannot connect.\nwrite_private \"$HOME_DIR/.kube/config\" <<EOF\napiVersion: v1\nkind: Config\nclusters:\n- name: rancher\n  cluster:\n    server: $RANCHER_URL/k8s/clusters/local\n    insecure-skip-tls-verify: true\ncontexts:\n- name: rancher\n  context:\n    cluster: rancher\n    user: rancher\ncurrent-context: rancher\nusers:\n- name: rancher\n  user:\n    token: $TOKEN\nEOF\n\n# Sourced rather than exported, because tmux passes this script's environment into a session it\n# creates and not into one it attaches to - so a pane that came back from a reload would have\n# had the variables and the next one would not. A file both of them read has no such difference.\nwrite_private \"$HOME_DIR/.rancher/env\" <<EOF\n# Sourced by a pane: . ~/.rancher/env\nRANCHER_URL=$RANCHER_URL\nRANCHER_TOKEN=$TOKEN\nEXTENSION_STUDIO_API=http://extension-studio-api:8006\nexport RANCHER_URL RANCHER_TOKEN EXTENSION_STUDIO_API\nEOF\n\nif [ \"$(id -u)\" = 0 ]; then\n  chown -R node:node \"$HOME_DIR/.kube\" \"$HOME_DIR/.rancher\" 2>/dev/null || true\nfi\n\nsay \"acting as ${USER_NAME:-the signed-in user}\"\n",
  "rancher-ec2.mjs": "#!/usr/bin/env node\n// A Rancher on one EC2 instance, made directly, with nothing between here and AWS.\n//\n// WHY THIS EXISTS, beside the Apps Plus `rancher-single` app that does the same job.\n//\n// That app asks for a Rancher like this: an AppInstance renders a Fleet Bundle, Fleet delivers\n// it, Rancher's CAPI provisioner builds an EC2 node and registers it as a downstream cluster of\n// the parent, a Helm release installs Rancher into that cluster, and a bootstrap sidecar\n// configures it. Seven links, and every one of them has to keep working for ever - including a\n// cluster-agent tunnel from AWS back to a Rancher on somebody's home connection, and two\n// Ranchers reconciling one `cattle-system` because the installed one runs --add-local=true.\n//\n// Measured across fifty days and four instances, that tunnel never once held for five seconds.\n// The specific defect behind it is fixed (a missing `cattle-system/rancher` Service), but the\n// chain is still seven links long and each is a way to lose a Rancher.\n//\n// This is the other answer: run one EC2 instance whose user-data installs docker and starts\n// `rancher/rancher` as a container. Three links - the instance, docker, the image - and the\n// parent is not one of them. Nothing here registers a cluster, nothing waits on Fleet, and no\n// agent has to dial home. It is the shape that has been working in the rancher-now project all\n// along.\n//\n// WHAT IT GIVES UP, honestly. There is no downstream cluster, so the parent cannot proxy into\n// it (it cannot today either - the agent is dead) and Fleet cannot deliver to it, which is how\n// shares reach an instance now. A share here is another container on the same box, or a\n// manifest applied with the instance's own kubeconfig; both are simpler than a Bundle.\n//\n// No SDK and no AWS CLI: the CLI is 222 MB in a pod that is rebuilt often, and the EC2 Query\n// API over SigV4 is sixty lines of crypto that is already in node.\nimport crypto from 'node:crypto';\nimport { execFileSync } from 'node:child_process';\n\nconst REGION = process.env.AWS_REGION || 'us-west-2';\n/** How this script recognises its own instances, and nothing else's. */\nconst TAG = 'dev.rancher.io/rancher';\n\n/**\n * The credential, read from the one place it already lives.\n *\n * Rancher keeps cloud credentials in cattle-global-data as `amazonec2credentialConfig-*` keys.\n * Read through kubectl with this pod's own ServiceAccount rather than copied anywhere: there is\n * no second store to rotate, and nothing here ever prints it.\n */\nfunction credential(name) {\n  const raw = execFileSync('kubectl', [\n    'get', 'secret', '-n', 'cattle-global-data', name, '-o', 'json',\n  ], { encoding: 'utf8' });\n  const data = JSON.parse(raw).data || {};\n  const get = (key) => Buffer.from(data[`amazonec2credentialConfig-${ key }`] || '', 'base64').toString('utf8').trim();\n  const id = get('accessKey');\n  const secret = get('secretKey');\n\n  if (!id || !secret) {\n    throw new Error(`${ name } is not an amazonec2 credential`);\n  }\n\n  return { id, secret, region: get('defaultRegion') || REGION };\n}\n\nconst hmac = (key, value) => crypto.createHmac('sha256', key).update(value, 'utf8').digest();\nconst sha256 = (value) => crypto.createHash('sha256').update(value, 'utf8').digest('hex');\n\n/**\n * One EC2 Query API call, signed.\n *\n * POST with a form body, which keeps the canonical request trivial: the path is always `/`, the\n * query string is always empty, and the only signed headers are the three that have to be.\n */\nasync function ec2(cred, params) {\n  const host = `ec2.${ cred.region }.amazonaws.com`;\n  const body = new URLSearchParams({ Version: '2016-11-15', ...params }).toString();\n  const now = new Date().toISOString().replace(/[:-]|\\.\\d{3}/g, '');\n  const day = now.slice(0, 8);\n  const scope = `${ day }/${ cred.region }/ec2/aws4_request`;\n  const canonical = [\n    'POST', '/', '',\n    `content-type:application/x-www-form-urlencoded; charset=utf-8`,\n    `host:${ host }`,\n    `x-amz-date:${ now }`,\n    '', 'content-type;host;x-amz-date', sha256(body),\n  ].join('\\n');\n  const toSign = ['AWS4-HMAC-SHA256', now, scope, sha256(canonical)].join('\\n');\n  const signature = hmac(\n    hmac(hmac(hmac(hmac(`AWS4${ cred.secret }`, day), cred.region), 'ec2'), 'aws4_request'),\n    toSign,\n  ).toString('hex');\n  const response = await fetch(`https://${ host }/`, {\n    method:  'POST',\n    headers: {\n      'content-type': 'application/x-www-form-urlencoded; charset=utf-8',\n      'x-amz-date':   now,\n      authorization:  `AWS4-HMAC-SHA256 Credential=${ cred.id }/${ scope }, SignedHeaders=content-type;host;x-amz-date, Signature=${ signature }`,\n    },\n    body,\n  });\n  const text = await response.text();\n\n  if (!response.ok) {\n    // The message, not the whole XML document, and never the request that carried the key.\n    throw new Error(`EC2 ${ params.Action } -> ${ response.status }: ${ (/<Message>([^<]*)</.exec(text) || [])[1] || text.slice(0, 200) }`);\n  }\n\n  return text;\n}\n\n/** Everything between a repeated XML tag, which is all the parsing this needs. */\nfunction all(xml, tag) {\n  return [...xml.matchAll(new RegExp(`<${ tag }>([\\\\s\\\\S]*?)</${ tag }>`, 'g'))].map((m) => m[1]);\n}\n\nfunction one(xml, tag) {\n  return (new RegExp(`<${ tag }>([\\\\s\\\\S]*?)</${ tag }>`).exec(xml) || [])[1] || '';\n}\n\n/**\n * The newest Ubuntu 24.04 image, asked of AWS rather than written down.\n *\n * A hard-coded AMI id is wrong in every region but one and goes stale the first time Canonical\n * publishes; this is one call and is always right.\n */\nasync function ubuntu(cred) {\n  const xml = await ec2(cred, {\n    Action:                      'DescribeImages',\n    'Owner.1':                   '099720109477',\n    'Filter.1.Name':             'name',\n    'Filter.1.Value.1':          'ubuntu/images/hvm-ssd-gp3/ubuntu-noble-24.04-amd64-server-*',\n    'Filter.2.Name':             'state',\n    'Filter.2.Value.1':          'available',\n  });\n  const images = all(xml, 'item')\n    .filter((i) => one(i, 'imageId'))\n    .map((i) => ({ id: one(i, 'imageId'), at: one(i, 'creationDate') }))\n    .sort((a, b) => b.at.localeCompare(a.at));\n\n  if (!images.length) {\n    throw new Error('no Ubuntu 24.04 image found in this region');\n  }\n\n  return images[0].id;\n}\n\n/**\n * What the instance runs on first boot.\n *\n * `--restart=unless-stopped` is the whole availability story: the box reboots, docker comes\n * back, Rancher comes back. No agent, no tunnel, nothing to reconnect.\n *\n * The two sysctls are not optional - Rancher runs k3s inside this container and the default\n * inotify limits are too low for it, which shows up as a Rancher that starts and then wedges.\n */\nfunction userData(image, password, registryAuth = '') {\n  /*\n   * A Prime image comes from a registry that refuses an anonymous pull, so the box logs in\n   * before it runs anything. The credentials are passed to docker on stdin rather than as\n   * `-p` - `docker login -p` puts them in the process list, where every other process on the\n   * box can read them - and the whole script is still user-data, which anything on the box can\n   * read from the metadata service, so this is no worse than the bootstrap password already\n   * sitting beside it and no better either. Empty for a community image, where it costs a shell\n   * branch and nothing else.\n   */\n  const login = registryAuth\n    ? `printf '%s' '${ registryAuth.password }' | docker login ${ registryAuth.host } -u '${ registryAuth.user }' --password-stdin\\n`\n    : '';\n\n  return Buffer.from(`#!/bin/bash\nset -eux\nexport DEBIAN_FRONTEND=noninteractive\napt-get update -y\napt-get install -y docker.io\nsystemctl enable --now docker\nsysctl -w fs.inotify.max_user_instances=1024 || true\nsysctl -w fs.inotify.max_user_watches=524288 || true\necho 'fs.inotify.max_user_instances=1024' >> /etc/sysctl.conf\necho 'fs.inotify.max_user_watches=524288' >> /etc/sysctl.conf\n\n# The certificate, decided here because only here knows the address.\n#\n# Let's Encrypt needs a NAME, and this box is given an IP minutes after anything that could\n# have written a name into this script. sslip.io resolves <ip>.sslip.io straight back to that\n# ip with no DNS to own, which is the same trick the shares already use - so the instance asks\n# the metadata service what it is and hands Rancher --acme-domain for that name. Rancher then\n# gets and renews the certificate itself; there is no cert-manager and nothing to expire\n# quietly.\n#\n# IMDSv2: the token call first, because a plain GET of the metadata service is refused on a\n# modern AMI and would leave HOST empty.\nTOK=$(curl -sX PUT 'http://169.254.169.254/latest/api/token' -H 'X-aws-ec2-metadata-token-ttl-seconds: 300' || true)\nIP=$(curl -s -H \"X-aws-ec2-metadata-token: $TOK\" http://169.254.169.254/latest/meta-data/public-ipv4 || true)\nHOST=\"\\${IP}.sslip.io\"\necho \"$HOST\" > /var/log/rancher-host\n\n${ login }docker run -d --name rancher --privileged --restart=unless-stopped \\\\\n  -p 80:80 -p 443:443 \\\\\n  -e CATTLE_BOOTSTRAP_PASSWORD='${ password }' \\\\\n  ${ image } --acme-domain \"$HOST\"\ntouch /var/log/rancher-bootstrap-done\n`).toString('base64');\n}\n\n/** The name this instance's certificate is for, and what server-url has to say. */\nconst hostFor = (ip) => `${ ip }.sslip.io`;\n\n/** Which build of Rancher, by where it is pulled from. Kept in step with ranchers.ts. */\nconst REGISTRIES = {\n  community:       '',\n  'prime-staging': 'stgregistry.suse.com',\n  prime:           'registry.rancher.com',\n};\n\n/** The default, and the same number the extension's create form starts on. */\nconst DEFAULT_VERSION = 'v2.12.3';\n\n/**\n * The image to run: the registry host in front of a tag.\n *\n * The repository is `rancher/rancher` in every one of them - community and both SUSE\n * registries - so a version is a version whichever is chosen and only the host changes.\n * RANCHER_EC2_IMAGE still wins over both, for a build that is not any of these.\n */\nfunction rancherImage(version, registry) {\n  const host = REGISTRIES[registry || 'community'] ?? '';\n  const tag = String(version || DEFAULT_VERSION).trim().replace(/^:/, '');\n\n  return `${ host ? `${ host }/` : '' }rancher/rancher:${ tag }`;\n}\n\n/**\n * What to log in to the registry with, or '' when there is nothing to log in to.\n *\n * Both SUSE registries refuse an anonymous pull, so a Prime instance with no credentials would\n * boot, pull nothing and sit at a docker error nobody is watching - the kind of failure this\n * tool exists to not have. It is refused here instead, while there is somebody to tell.\n */\nfunction registryAuth(registry) {\n  const host = REGISTRIES[registry || 'community'] ?? '';\n\n  if (!host) {\n    return '';\n  }\n  const user = (process.env.PRIME_REGISTRY_USER || '').trim();\n  const password = (process.env.PRIME_REGISTRY_PASSWORD || '').trim();\n\n  if (!user || !password) {\n    throw new Error(`${ host } refuses an anonymous pull, so a Prime instance needs PRIME_REGISTRY_USER and PRIME_REGISTRY_PASSWORD in the environment.`);\n  }\n\n  return { host, user, password };\n}\n\n/**\n * Where to put it, when nobody said.\n *\n * The point of this tool is that `create <name>` works, so the network it needs is discovered\n * rather than configured: the account's default VPC, one of its default subnets, and a security\n * group of this tool's own. A caller that knows better still passes RANCHER_EC2_SUBNET and\n * RANCHER_EC2_SG and none of this runs.\n */\nasync function defaultNetwork(cred) {\n  const vpcs = await ec2(cred, {\n    Action: 'DescribeVpcs', 'Filter.1.Name': 'isDefault', 'Filter.1.Value.1': 'true',\n  });\n  const vpcId = one(vpcs, 'vpcId');\n\n  if (!vpcId) {\n    throw new Error('no default VPC in this region; set RANCHER_EC2_SUBNET and RANCHER_EC2_SG');\n  }\n\n  const subnets = await ec2(cred, {\n    Action: 'DescribeSubnets', 'Filter.1.Name': 'vpc-id', 'Filter.1.Value.1': vpcId,\n  });\n  const subnet = all(subnets, 'item').map((i) => one(i, 'subnetId')).filter(Boolean)[0];\n\n  return { vpcId, subnet };\n}\n\n/**\n * The security group, found or made.\n *\n * 80 and 443 from anywhere, because the whole point of this Rancher is that it has a public\n * address a browser and an agent can reach. Nothing else is opened - no 22, because this box is\n * not meant to be logged into: it runs one container and `docker logs` is reachable through\n * nothing here. Add SSH deliberately if you want it.\n */\nasync function securityGroup(cred, vpcId) {\n  const existing = await ec2(cred, {\n    Action:             'DescribeSecurityGroups',\n    'Filter.1.Name':    'group-name',\n    'Filter.1.Value.1': 'rancher-ec2',\n    'Filter.2.Name':    'vpc-id',\n    'Filter.2.Value.1': vpcId,\n  });\n  const found = one(existing, 'groupId');\n\n  if (found) {\n    return found;\n  }\n\n  const made = await ec2(cred, {\n    Action:           'CreateSecurityGroup',\n    GroupName:        'rancher-ec2',\n    GroupDescription: 'Rancher on one EC2 instance (dev-extension)',\n    VpcId:            vpcId,\n  });\n  const id = one(made, 'groupId');\n\n  for (const [n, port] of [80, 443].entries()) {\n    await ec2(cred, {\n      Action:                                  'AuthorizeSecurityGroupIngress',\n      GroupId:                                 id,\n      [`IpPermissions.${ n + 1 }.IpProtocol`]: 'tcp',\n      [`IpPermissions.${ n + 1 }.FromPort`]:   String(port),\n      [`IpPermissions.${ n + 1 }.ToPort`]:     String(port),\n      [`IpPermissions.${ n + 1 }.IpRanges.1.CidrIp`]: '0.0.0.0/0',\n    });\n  }\n\n  return id;\n}\n\nasync function create(cred, name, opts) {\n  const ami = opts.ami || await ubuntu(cred);\n  let { subnet, securityGroup: sg } = opts;\n\n  if (!subnet || !sg) {\n    const net = await defaultNetwork(cred);\n\n    subnet = subnet || net.subnet;\n    sg = sg || await securityGroup(cred, net.vpcId);\n  }\n  const password = opts.password || crypto.randomBytes(16).toString('base64url');\n  const params = {\n    Action:                                        'RunInstances',\n    ImageId:                                       ami,\n    InstanceType:                                  opts.type,\n    MinCount:                                      '1',\n    MaxCount:                                      '1',\n    UserData:                                      userData(opts.image, password, opts.registryAuth),\n    'BlockDeviceMapping.1.DeviceName':             '/dev/sda1',\n    'BlockDeviceMapping.1.Ebs.VolumeSize':         String(opts.rootSize),\n    // gp3 for the same reason the Apps Plus app chose it: a gp2 root's baseline is 3 IOPS per\n    // GiB, and etcd inside this container is what everything else waits behind.\n    'BlockDeviceMapping.1.Ebs.VolumeType':         'gp3',\n    'BlockDeviceMapping.1.Ebs.DeleteOnTermination': 'true',\n    'TagSpecification.1.ResourceType':             'instance',\n    'TagSpecification.1.Tag.1.Key':                'Name',\n    'TagSpecification.1.Tag.1.Value':              name,\n    'TagSpecification.1.Tag.2.Key':                TAG,\n    'TagSpecification.1.Tag.2.Value':              name,\n  };\n\n  if (sg) {\n    params['SecurityGroupId.1'] = sg;\n  }\n  if (subnet) {\n    params.SubnetId = subnet;\n  }\n  if (opts.keyName) {\n    params.KeyName = opts.keyName;\n  }\n  // AWS validates everything and launches nothing, which is how this tool is tested without\n  // billing somebody for a box. It answers with a DryRunOperation error on success, so that\n  // one error is the pass.\n  if (opts.dryRun) {\n    params.DryRun = 'true';\n\n    try {\n      await ec2(cred, params);\n    } catch (e) {\n      const ok = /DryRunOperation|Request would have succeeded/.test(String(e.message || e));\n\n      console.log(JSON.stringify({\n        dryRun: true, ok, ami, subnet, securityGroup: sg, detail: ok ? 'would launch' : String(e.message || e),\n      }));\n\n      return '';\n    }\n\n    console.log(JSON.stringify({ dryRun: true, ok: false, detail: 'AWS did not answer DryRunOperation' }));\n\n    return '';\n  }\n\n  const xml = await ec2(cred, params);\n  const id = one(xml, 'instanceId');\n\n  // Kept in a Secret, not the ConfigMap the dashboard reads: `configure` needs it minutes\n  // later, and asking somebody to copy a password out of a log is how it ends up in one.\n  savePassword(name, password);\n\n  console.log(JSON.stringify({\n    name, instanceId: id, ami, password, state: 'pending',\n  }));\n\n  return id;\n}\n\nasync function list(cred) {\n  const xml = await ec2(cred, {\n    Action:             'DescribeInstances',\n    'Filter.1.Name':    `tag:${ TAG }`,\n    'Filter.1.Value.1': '*',\n    'Filter.2.Name':    'instance-state-name',\n    'Filter.2.Value.1': 'pending',\n    'Filter.2.Value.2': 'running',\n    'Filter.2.Value.3': 'stopped',\n  });\n\n  /*\n   * Sliced on `<instanceId>` rather than on `<item>`.\n   *\n   * EC2 nests items three deep - reservationSet > item > instancesSet > item - and the tag set\n   * inside an instance is a list of items too, so matching `<item>` with a regex pairs the\n   * wrong open and close tags and the name came back empty. `instanceId` is the first field of\n   * each instance, so the text from one to the next is exactly that instance's own fields.\n   */\n  const at = [...xml.matchAll(/<instanceId>([^<]+)<\\/instanceId>/g)];\n\n  return at.map((m, n) => {\n    const block = xml.slice(m.index, n + 1 < at.length ? at[n + 1].index : undefined);\n    const tags = all(one(block, 'tagSet'), 'item');\n\n    return {\n      name:  tags.map((t) => (one(t, 'key') === TAG ? one(t, 'value') : '')).find(Boolean) || '',\n      id:    m[1],\n      state: one(one(block, 'instanceState'), 'name'),\n      ip:    one(block, 'ipAddress'),\n    };\n  }).filter((i) => i.id);\n}\n\n/**\n * Every instance in the account, tagged or not.\n *\n * Because the ones that cost money quietly are the ones nothing lists. A node left behind by a\n * deleted Rancher keeps running, keeps its public address, and in at least one case kept\n * dialling the parent 6,302 times in six hours - and `list` could not see it, because `list`\n * only knows instances this tool tagged.\n */\nasync function orphans(cred) {\n  const xml = await ec2(cred, {\n    Action:             'DescribeInstances',\n    'Filter.1.Name':    'instance-state-name',\n    'Filter.1.Value.1': 'running',\n    'Filter.1.Value.2': 'pending',\n  });\n  const at = [...xml.matchAll(/<instanceId>([^<]+)<\\/instanceId>/g)];\n\n  return at.map((m, n) => {\n    const block = xml.slice(m.index, n + 1 < at.length ? at[n + 1].index : undefined);\n    const tags = all(one(block, 'tagSet'), 'item');\n    const named = (key) => tags.map((t) => (one(t, 'key') === key ? one(t, 'value') : '')).find(Boolean) || '';\n\n    return {\n      id:      m[1],\n      ours:    !!named(TAG),\n      name:    named(TAG) || named('Name') || '(untagged)',\n      ip:      one(block, 'ipAddress'),\n      state:   one(one(block, 'instanceState'), 'name'),\n      since:   one(block, 'launchTime'),\n    };\n  }).filter((i) => i.id);\n}\n\n/**\n * Terminate, by this tool's name for it or by instance id.\n *\n * The id form exists for the ones this tool did not create: a node left behind by a deleted\n * Rancher is not tagged, so `list` cannot see it, and the only handle anybody has is the id or\n * the Name tag that shows in `orphans`.\n *\n * It refuses an ambiguous match rather than picking one. This call cannot be undone, the\n * account has a dozen instances belonging to other people in it, and \"it matched two, so I did\n * the first\" is not a sentence worth being able to write afterwards.\n */\nasync function remove(cred, name) {\n  let found = (await list(cred)).filter((i) => i.name === name || i.id === name);\n\n  if (!found.length) {\n    found = (await orphans(cred))\n      .filter((i) => i.id === name || i.name === name)\n      .map((i) => ({ name: i.name, id: i.id, state: i.state, ip: i.ip }));\n  }\n\n  if (found.length > 1) {\n    throw new Error(`${ name } matches ${ found.length } instances (${ found.map((i) => i.id).join(', ') }); name one by id`);\n  }\n\n  if (!found.length) {\n    throw new Error(`no instance called ${ name }`);\n  }\n  console.error(`terminating ${ found[0].id } (${ found[0].name }, ${ found[0].ip || 'no public ip'})`);\n  for (const [n, instance] of found.entries()) {\n    await ec2(cred, { Action: 'TerminateInstances', [`InstanceId.${ n + 1 }`]: instance.id });\n  }\n  console.log(JSON.stringify({ terminated: found.map((i) => i.id) }));\n}\n\n/**\n * What the extension reads, because a browser cannot call EC2.\n *\n * One ConfigMap in dev-system holding every instance this tool knows about. Written after each\n * create, delete and sync, so the list in the sidebar is the list in the account rather than a\n * second thing to keep in step by hand.\n *\n * The bootstrap password is NOT in here. It is shown once, by `create`, and this record is read\n * by every page of the dashboard; a password in it would be a password in everybody's browser.\n */\n/**\n * Is Rancher actually answering, as opposed to the box being switched on?\n *\n * `state: running` is EC2's opinion of the hardware and says nothing about the container - a\n * box that is up but pulling the image, or whose Rancher has fallen over, reports `running`\n * just the same. The status beside an instance should be the status of the thing you click\n * through to, so the record carries the answer to /ping.\n */\nasync function answering(ip) {\n  try {\n    const r = await fetch(`https://${ hostFor(ip) }/ping`, { signal: AbortSignal.timeout(8000) });\n\n    return r.ok;\n  } catch {\n    return false;\n  }\n}\n\nasync function record(cred) {\n  const instances = await list(cred);\n  const health = Object.fromEntries(await Promise.all(\n    instances.filter((i) => i.ip).map(async(i) => [i.id, await answering(i.ip)]),\n  ));\n  const doc = JSON.stringify({\n    at: new Date().toISOString(),\n    instances: instances.filter((i) => i.name).map((i) => ({\n      up: !!health[i.id],\n      // The sslip name, not the bare address: that is the name the Let's Encrypt certificate\n      // is issued for, so it is the only one a browser opens without a warning.\n      name: i.name, instanceId: i.id, state: i.state, ip: i.ip, url: i.ip ? `https://${ hostFor(i.ip) }` : '',\n    })),\n  });\n\n  // Rendered once and applied through a pipe, so it is a create-or-update rather than a create\n  // that fails the second time.\n  const yaml = execFileSync('kubectl', [\n    'create', 'configmap', 'dev-rancher-ec2', '-n', 'dev-system',\n    `--from-literal=instances.json=${ doc }`, '--dry-run=client', '-o', 'yaml',\n  ], { encoding: 'utf8' });\n\n  // The LABELLED output is what gets applied. Piping `yaml` here instead was a label that was\n  // computed, printed to nowhere and dropped - the ConfigMap landed unlabelled and nothing\n  // selecting on the label could find it.\n  const labelled = execFileSync('kubectl', [\n    'label', '--local', '-f', '-', 'dev.rancher.io/kind=rancher-ec2', '--dry-run=client', '-o', 'yaml',\n  ], { encoding: 'utf8', input: yaml });\n\n  execFileSync('kubectl', ['apply', '-f', '-'], { encoding: 'utf8', input: labelled });\n\n  return instances;\n}\n\n// ── Making it a Rancher somebody can actually use ──────────────────────────────────────────\n//\n// A box running `rancher/rancher` is a login prompt, not a Rancher: no address it knows itself\n// by, no Cluster Management, no way in but a bootstrap password nobody wants to share. The\n// Apps Plus app does the rest with a sidecar that has kubectl inside the cluster; there is no\n// sidecar here, so the same work is done over Rancher's own API from this pod.\n//\n// Everything below is idempotent. `configure` is safe to run again, and running it again is how\n// a half-finished instance is finished.\n\n/** A token for the instance, from the bootstrap password. */\nasync function login(url, password) {\n  const r = await fetch(`${ url }/v3-public/localProviders/local?action=login`, {\n    method:  'POST',\n    headers: { 'content-type': 'application/json' },\n    body:    JSON.stringify({ username: 'admin', password, ttl: 3600000 }),\n  });\n\n  if (!r.ok) {\n    throw new Error(`login -> ${ r.status } (is the bootstrap password right?)`);\n  }\n\n  return (await r.json()).token;\n}\n\nasync function api(url, token, path, method = 'GET', body = null) {\n  const r = await fetch(`${ url }${ path }`, {\n    method,\n    headers: {\n      authorization: `Bearer ${ token }`,\n      ...(body ? { 'content-type': 'application/json' } : {}),\n    },\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  const text = await r.text();\n\n  if (!r.ok) {\n    throw new Error(`${ method } ${ path } -> ${ r.status }: ${ text.slice(0, 200) }`);\n  }\n\n  return text ? JSON.parse(text) : null;\n}\n\n/** What this Rancher's own GitHub login should look like: whatever the parent's does. */\nfunction parentGithub() {\n  const read = (args) => {\n    try {\n      return execFileSync('kubectl', args, { encoding: 'utf8' }).trim();\n    } catch {\n      return '';\n    }\n  };\n  const clientId = read(['get', 'authconfig', 'github', '-o', 'jsonpath={.clientId}']);\n  const principals = read(['get', 'authconfig', 'github', '-o', 'jsonpath={.allowedPrincipalIds}']);\n  const secret = read([\n    'get', 'secret', '-n', 'cattle-global-data', 'githubconfig-clientsecret',\n    '-o', 'jsonpath={.data.clientsecret}',\n  ]);\n\n  const allowed = (() => {\n    try {\n      return JSON.parse(principals || '[]');\n    } catch {\n      return [];\n    }\n  })();\n\n  /*\n   * The rancher org, always.\n   *\n   * An instance is made to be shown to somebody - a share, a reviewer, whoever is being asked\n   * to look at the thing - and an allow-list of one person is a Rancher only its maker can\n   * open. `github_org://9343010` is the rancher organisation, which is the same id the Apps\n   * Plus app has written into every instance it has ever made; this keeps the two paths\n   * agreeing about who gets in.\n   */\n  const RANCHER_ORG = 'github_org://9343010';\n\n  return {\n    clientId,\n    clientSecret: secret ? Buffer.from(secret, 'base64').toString('utf8') : '',\n    allowed:      [...new Set([...allowed, RANCHER_ORG])],\n  };\n}\n\n/**\n * Everything the sidecar does for an Apps Plus instance, over the API instead.\n *\n * Order matters in one place only: the client secret has to exist before the AuthConfig that\n * names it, because Rancher resolves `cattle-global-data:githubconfig-clientsecret` when the\n * config is saved and refuses one that points at nothing.\n */\nasync function configure(cred, name, opts) {\n  const found = (await list(cred)).find((i) => i.name === name);\n\n  if (!found?.ip) {\n    throw new Error(`no running instance called ${ name }`);\n  }\n  const host = hostFor(found.ip);\n  const url = `https://${ found.ip }`;\n  const password = opts.password || readPassword(name);\n\n  if (!password) {\n    throw new Error(`no bootstrap password for ${ name }; pass RANCHER_EC2_PASSWORD`);\n  }\n\n  process.env.NODE_TLS_REJECT_UNAUTHORIZED = '0'; // its cert is for the sslip name, not the ip\n  const token = await login(url, password);\n  const done = [];\n\n  // 1. The address it tells everything else to reach it on - the sslip name the certificate\n  //    is for, not the bare ip, or every agent it ever provisions gets a TLS error.\n  await api(url, token, '/v3/settings/server-url', 'PUT', { name: 'server-url', value: `https://${ host }` });\n  done.push(`server-url https://${ host }`);\n\n  /*\n   * 2. First-time setup, finished.\n   *\n   * Logging in with the bootstrap password is not the same as having set the thing up: Rancher\n   * keeps `first-login: true` until the wizard is done, and shows \"Welcome to Rancher - it\n   * looks like this is your first time visiting\" to everybody, including the person who has\n   * just been handed the address. The wizard sets three things and so does this.\n   *\n   * telemetry is set to `out` rather than left unset, because unset is a question Rancher will\n   * ask the first person through the door and nobody asked for this box to phone home.\n   */\n  const setting = async(nameOf, value) => {\n    try {\n      await api(url, token, `/v3/settings/${ nameOf }`, 'PUT', { name: nameOf, value });\n\n      return true;\n    } catch {\n      return false;\n    }\n  };\n  // Reported one at a time, by whether it took. The first version said \"eula, telemetry out,\n  // first-login false\" as one line whatever happened, and telemetry-opt had in fact failed -\n  // a summary that is written before the result is a summary that can be wrong.\n  const eula = await setting('eula-agreed', new Date().toISOString());\n  const telemetry = await setting('telemetry-opt', 'out');\n\n  await api(url, token, '/v3/settings/first-login', 'PUT', { name: 'first-login', value: 'false' });\n  done.push(`first-login false${ eula ? ', eula agreed' : ', EULA NOT set' }${ telemetry ? ', telemetry out' : ', telemetry-opt NOT set' }`);\n\n  // 3. Cluster Management and the rest. Not dynamic: they take on the next start, and Rancher\n  //    in this container restarts itself when a feature changes.\n  for (const flag of ['multi-cluster-management', 'fleet', 'rke2']) {\n    await api(url, token, `/v3/features/${ flag }`, 'PUT', { name: flag, value: true }).catch(() => undefined);\n  }\n  done.push('features: multi-cluster-management, fleet, rke2');\n\n  // 4. GitHub, mirroring the parent's own configuration so the same people get in.\n  const gh = parentGithub();\n\n  if (!gh.clientId || !gh.clientSecret) {\n    done.push('github login SKIPPED: the parent has no clientId/secret to copy');\n  } else if (!gh.allowed.length) {\n    /*\n     * Refused rather than guessed at, and this is the one place in this file worth being\n     * timid. `accessMode: restricted` with an empty allow-list is a Rancher that lets nobody\n     * in through GitHub - and since enabling GitHub is also what stops the local admin being\n     * the way in, getting this wrong locks the owner out of a box they are paying for.\n     */\n    done.push('github login SKIPPED: the parent lists no allowed principals, and enabling restricted access with an empty list would lock everyone out');\n  } else {\n    /*\n     * `/v3/githubConfigs/github`, not the Steve path.\n     *\n     * `PUT /v1/management.cattle.io.authconfigs/github` answers 403 \"Method PUT not\n     * supported\" - Steve does not take writes for this kind. The v3 resource advertises an\n     * `update` link and takes the whole config, with the client secret as a literal; Rancher\n     * puts it in cattle-global-data itself, so there is no secret to create first.\n     */\n    await api(url, token, '/v3/githubConfigs/github', 'PUT', {\n      name:                'github',\n      type:                'githubConfig',\n      enabled:             true,\n      accessMode:          'restricted',\n      allowedPrincipalIds: gh.allowed,\n      clientId:            gh.clientId,\n      clientSecret:        gh.clientSecret,\n      hostname:            'github.com',\n      tls:                 true,\n    });\n    done.push(`github login for ${ gh.allowed.length } principal(s)`);\n  }\n\n  /*\n   * 5. The cloud credentials, so this Rancher can provision something of its own.\n   *\n   * The same set the Apps Plus app hands an instance: the secrets in cattle-global-data that\n   * carry `dev.rancher.io/propagate-to-instances`, copied verbatim. They are secrets rather\n   * than /v3/cloudcredentials objects because that is what Rancher reads its credential list\n   * from, and copying the object the working path already copies is one fewer shape to get\n   * wrong.\n   */\n  for (const cc of propagatedCredentials()) {\n    await api(url, token, '/v1/secrets', 'POST', {\n      type:       'Opaque',\n      metadata:   { name: cc.name, namespace: 'cattle-global-data', annotations: cc.annotations },\n      data:       cc.data,\n    }).catch(() => undefined); // already there on a second run\n  }\n  const copied = propagatedCredentials().length;\n\n  done.push(copied ? `${ copied } cloud credential(s) copied` : 'no cloud credentials marked to propagate');\n\n  console.log(JSON.stringify({\n    name, url: `https://${ host }`, ip: found.ip, configured: done,\n  }, null, 1));\n}\n\n/**\n * The cloud credentials marked to travel, read from the parent.\n *\n * `dev.rancher.io/propagate-to-instances` is the extension's own marker and the Apps Plus path\n * already uses it, so what an instance gets is decided in one place rather than two. The\n * annotations Kubernetes and Helm add are dropped; `field.cattle.io/name` is kept, because\n * without it the credential shows in Rancher's list with no name.\n */\nfunction propagatedCredentials() {\n  try {\n    const raw = execFileSync('kubectl', [\n      'get', 'secrets', '-n', 'cattle-global-data',\n      '-l', 'dev.rancher.io/propagate-to-instances', '-o', 'json',\n    ], { encoding: 'utf8' });\n    let items = JSON.parse(raw).items || [];\n\n    // The marker is an annotation on these, not a label, so the selector above matches nothing\n    // and everything has to be read and filtered. Kept as a selector too in case they are ever\n    // labelled: a narrower server-side read is better when it works.\n    if (!items.length) {\n      items = (JSON.parse(execFileSync('kubectl', [\n        'get', 'secrets', '-n', 'cattle-global-data', '-o', 'json',\n      ], { encoding: 'utf8' })).items || [])\n        .filter((x) => (x.metadata?.annotations || {})['dev.rancher.io/propagate-to-instances'] === 'true');\n    }\n\n    return items.map((x) => ({\n      name:        x.metadata.name,\n      data:        x.data || {},\n      annotations: Object.fromEntries(Object.entries(x.metadata.annotations || {})\n        .filter(([k]) => k.startsWith('field.cattle.io/'))),\n    }));\n  } catch {\n    return [];\n  }\n}\n\n/** The bootstrap password, kept where only an admin can read it - never in the ConfigMap. */\nfunction savePassword(name, password) {\n  const yaml = execFileSync('kubectl', [\n    'create', 'secret', 'generic', `dev-rancher-ec2-${ name }`, '-n', 'dev-system',\n    `--from-literal=password=${ password }`, '--dry-run=client', '-o', 'yaml',\n  ], { encoding: 'utf8' });\n\n  execFileSync('kubectl', ['apply', '-f', '-'], { encoding: 'utf8', input: yaml });\n}\n\nfunction readPassword(name) {\n  try {\n    const b64 = execFileSync('kubectl', [\n      'get', 'secret', '-n', 'dev-system', `dev-rancher-ec2-${ name }`, '-o', 'jsonpath={.data.password}',\n    ], { encoding: 'utf8' }).trim();\n\n    return b64 ? Buffer.from(b64, 'base64').toString('utf8') : '';\n  } catch {\n    return '';\n  }\n}\n\nasync function main() {\n  const [verb, name] = process.argv.slice(2);\n  const opts = {\n    credential:    process.env.RANCHER_EC2_CREDENTIAL || '',\n    type:          process.env.RANCHER_EC2_TYPE || 't3.xlarge',\n    rootSize:      process.env.RANCHER_EC2_ROOT || '100',\n    image:         process.env.RANCHER_EC2_IMAGE || rancherImage(process.env.RANCHER_EC2_VERSION, process.env.RANCHER_EC2_REGISTRY),\n    registryAuth:  registryAuth(process.env.RANCHER_EC2_REGISTRY),\n    securityGroup: process.env.RANCHER_EC2_SG || '',\n    subnet:        process.env.RANCHER_EC2_SUBNET || '',\n    keyName:       process.env.RANCHER_EC2_KEY || '',\n    ami:           process.env.RANCHER_EC2_AMI || '',\n    password:      process.env.RANCHER_EC2_PASSWORD || '',\n    dryRun:        process.env.RANCHER_EC2_DRYRUN === '1',\n  };\n\n  if (!opts.credential) {\n    throw new Error('RANCHER_EC2_CREDENTIAL must name a cattle-global-data secret (a cc-xxxxx)');\n  }\n  const cred = credential(opts.credential);\n\n  if (verb === 'create') {\n    if (!name) {\n      throw new Error('create needs a name');\n    }\n    await create(cred, name, opts);\n    await record(cred).catch(() => undefined);\n  } else if (verb === 'orphans') {\n    const rows = await orphans(cred);\n\n    console.log(JSON.stringify({\n      ours:  rows.filter((r) => r.ours),\n      other: rows.filter((r) => !r.ours),\n    }, null, 1));\n  } else if (verb === 'configure') {\n    if (!name) {\n      throw new Error('configure needs a name');\n    }\n    await configure(cred, name, opts);\n  } else if (verb === 'sync') {\n    // What boot.sh runs on a timer: the account is the truth, this copies it where the\n    // dashboard can see it.\n    console.log(JSON.stringify(await record(cred), null, 1));\n  } else if (verb === 'list') {\n    console.log(JSON.stringify(await list(cred), null, 1));\n  } else if (verb === 'delete') {\n    if (!name) {\n      throw new Error('delete needs a name');\n    }\n    await remove(cred, name);\n    await record(cred).catch(() => undefined);\n  } else {\n    console.error('usage: rancher-ec2.mjs create <name> | configure <name> | list | orphans | sync | delete <name>');\n    process.exit(2);\n  }\n}\n\nmain().catch((e) => {\n  console.error(String(e?.message || e));\n  process.exit(1);\n});\n",
  "registrar-state.sh": "#!/bin/sh\n# Report each downstream workspace's live state into the `dev-workspaces-downstream` ConfigMap on\n# local, so dev-api can fold it into the `dev-workspaces` registrar the sidebar reads. dev-api runs\n# on local and cannot see downstream pods; this pod already reaches them (the downstream-exec token\n# through the Rancher proxy, like the mount daemon). This is the single writer of that ConfigMap.\n# See dev-api's reconcileRegistrar.\nSECRET=/var/run/downstream-exec\nNS=dev-system\nCM=dev-workspaces-downstream\nLOCAL=local\nDIR=/workspace/.registrar\nPATH=/workspace/.home/.local/bin:/usr/local/bin:/usr/bin:/bin:$PATH\nexport PATH\n\n# kubectl from terminal-tools.sh, node from the image.\nn=0\nwhile ! command -v kubectl >/dev/null 2>&1 || ! command -v node >/dev/null 2>&1; do\n  n=$((n + 1))\n  [ \"$n\" -gt 120 ] && { echo \"kubectl/node never arrived; not reporting downstream state\"; exit 0; }\n  sleep 10\ndone\nmkdir -p \"$DIR\"\n\nwhile true; do\n  TOKEN=$(cat \"$SECRET/token\" 2>/dev/null)\n  RURL=$(cat \"$SECRET/rancherUrl\" 2>/dev/null)\n  if [ -n \"$TOKEN\" ] && [ -n \"$RURL\" ]; then\n    # Every workspace and the cluster it runs on, from the local Installations. KUBECONFIG=/dev/null\n    # makes kubectl use this pod's own in-cluster service account against the local apiserver. A failed\n    # read here would truncate the list to empty, and an empty list would blank every downstream\n    # workspace to \"starting\" this tick (the node pass would iterate nothing). On any doubt do nothing\n    # this tick, exactly as dev-api skips when its Installation list read throws - do it BEFORE the rm\n    # so the previous state.json survives untouched (last-good) rather than being rebuilt from empty.\n    if ! KUBECONFIG=/dev/null kubectl get appinstances.appsplus.io -A \\\n      -o jsonpath='{range .items[*]}{.metadata.labels.dev\\.rancher\\.io/workspace}{\" \"}{.metadata.labels.dev\\.rancher\\.io/cluster}{\"\\n\"}{end}' </dev/null > \"$DIR/list\" 2>/dev/null; then\n      sleep 15\n      continue\n    fi\n    rm -f \"$DIR\"/*.deploy.json 2>/dev/null\n    : > \"$DIR/downstream\"\n    # Read from a file (not a pipe) and give every inner command </dev/null, so an exec that holds\n    # stdin cannot swallow the rest of the list (the bug that once left all but the first workspace).\n    while read -r name cluster; do\n      [ -n \"$name\" ] && [ -n \"$cluster\" ] || continue\n      [ \"$cluster\" = \"$LOCAL\" ] && continue\n      case \"$name\" in preview-*|storybook-*) continue ;; esac\n      # Every downstream workspace we mean to report, whether or not the read below succeeds. The node\n      # pass carries a failed read's LAST-GOOD state forward rather than blanking it to \"starting\".\n      echo \"$name\" >> \"$DIR/downstream\"\n      # On a read failure leave no file (the rm above cleared it): absent = \"could not read\", which\n      # the node pass treats as last-good, not as \"stopped\". A '{}' here would flap it to \"starting\".\n      kubectl --server=\"$RURL/k8s/clusters/$cluster\" --token=\"$TOKEN\" --insecure-skip-tls-verify=true \\\n        get deploy \"dev-$name\" -n \"dev-$name\" -o json </dev/null > \"$DIR/$name.deploy.json\" 2>/dev/null \\\n        || rm -f \"$DIR/$name.deploy.json\"\n    done < \"$DIR/list\"\n    # One node pass -> { name: { state, detail, replicas, ready, lastSeen } }, mirroring api.ts\n    # stateOf at the Deployment level (pod-level error detail is left to the browser). For a workspace\n    # whose read failed this tick, keep the previous entry (its lastSeen ages, so staleness shows)\n    # instead of flapping it. Workspaces no longer in the list are dropped. Then apply on local\n    # (create-or-update). A node crash leaves the previous state.json untouched - last-good, not blank.\n    node -e '\n      const fs = require(\"fs\"), path = require(\"path\");\n      const dir = process.argv[1];\n      let prev = {};\n      try { prev = JSON.parse(fs.readFileSync(path.join(dir, \"state.json\"), \"utf8\")); } catch (e) {}\n      const names = fs.readFileSync(path.join(dir, \"downstream\"), \"utf8\").split(\"\\n\").map((s) => s.trim()).filter(Boolean);\n      const out = {};\n      for (const name of names) {\n        let d = null;\n        try { d = JSON.parse(fs.readFileSync(path.join(dir, name + \".deploy.json\"), \"utf8\")); } catch (e) {}\n        if (d && d.metadata) {\n          const replicas = (d.spec && d.spec.replicas) || 0;\n          const ready = (d.status && d.status.readyReplicas) || 0;\n          const state = replicas === 0 ? \"stopped\" : ready > 0 ? \"running\" : \"starting\";\n          out[name] = { state, detail: \"\", replicas, ready, lastSeen: new Date().toISOString() };\n        } else if (prev[name]) {\n          out[name] = prev[name]; // read failed this tick: keep last-good, let lastSeen age\n        } else {\n          out[name] = { state: \"starting\", detail: \"\", replicas: 0, ready: 0, lastSeen: new Date().toISOString() };\n        }\n      }\n      fs.writeFileSync(path.join(dir, \"state.json\"), JSON.stringify(out));\n    ' \"$DIR\" 2>/dev/null || true\n    KUBECONFIG=/dev/null kubectl -n \"$NS\" create configmap \"$CM\" \\\n      --from-file=state.json=\"$DIR/state.json\" --dry-run=client -o yaml 2>/dev/null \\\n      | KUBECONFIG=/dev/null kubectl apply -f - >/dev/null 2>&1\n  fi\n  sleep 15\ndone\n",
  "session-claude.md": "# Where you are\n\nYou are claude, in a pod of your own - `agent`, in the `dev-agents` namespace of the cluster this\nRancher manages. You are not inside any extension. You are the one agent that can see all of\nthem, opened with Ctrl+Shift+backtick from any page in the Rancher dashboard.\n\nThis pod used to live in `extension-studio` and was called `extension-studio-agent`; the\nextensions still do live there, which is why the commands below name that namespace and not\nyours. Your node directory kept its old name too - `/var/lib/rancher/extension-studio/agent` is\nwhat `/workspace` is - because renaming it would have meant copying every conversation anybody\nhas between two directories on the node.\n\n`/seed/shell.sh` copies this file into a session's directory the first time that session starts.\nIt is yours to edit. Later sessions get the original again.\n\nEvery conversation shares `/workspace/conversations`, and `/workspace` is on the node's disk, so\na login and a conversation both survive this pod being restarted. Sharing the directory is what\nlets you `/resume` a conversation somebody had in another tab; which one is yours is recorded in\n`/workspace/sessions/<session>.id`. Your session is a tmux session: whoever opened it can close\nthe panel, close the browser, or reload the page, and you keep running.\n\n`node`, `npm`, `yarn`, `git`, `curl`, `tmux` and `kubectl` are here. There is no extension source\nin this pod - `/workspace` is yours, not anybody's tree.\n\n## Reaching the extensions\n\nEvery extension is one Deployment, one Service and one pod in `extension-studio`. The objects are\nnamed `<extension>-extension`, and the container to exec into is always `devserver`:\n\n```bash\nkubectl -n extension-studio get deploy            # every extension, plus the three that are not one\nkubectl -n extension-studio get pods -o wide\nkubectl -n extension-studio exec -it deploy/base-extension -c devserver -- bash\n```\n\nInside one, the extension's source is the single directory under `/app/pkg`, and `/app` is that\npod's own node disk. So a file read out of an extension is:\n\n```bash\nkubectl -n extension-studio exec deploy/base-extension -c devserver -- \\\n  sh -c 'cd /app/pkg/*/ && cat package.json'\n```\n\nTwo other pods are in there and are not extensions: `browser` is a Chromium with its debugging\nprotocol open on port 9222, and `extension-studio-api` is the Studio's own service.\n\n## Editing an extension\n\nTwo calls, before any looking around. Between them they answer everything that is otherwise\nworked out by probing, and both are cheap.\n\n```bash\n. ~/.rancher/env\ncurl -s \"$EXTENSION_STUDIO_API/v1/extensions/base\" -H \"Authorization: Bearer $RANCHER_TOKEN\"\n```\n\n```json\n{ \"name\": \"apps-plus\", \"ready\": true, \"pod\": \"apps-plus-extension-7d9f...\",\n  \"container\": \"devserver\", \"tree\": \"/app/pkg/base\", \"packageName\": \"base\",\n  \"guide\": \"/app/pkg/base/CLAUDE.md\", \"source\": \"base\" }\n```\n\n**`tree` is not `/app/pkg/<name>`, and this is the thing that catches everybody.** An extension\ncreated from another is a copy of that one's tree, so an extension the cluster calls `apps-plus`\nis served out of `/app/pkg/base` by a package whose `package.json` still says `\"name\": \"base\"`.\nRenaming it is a change to the extension like any other, and one nobody has asked for by\ndefault. Use `tree`; do not derive it.\n\n### Their trees are mounted here\n\nYou do not have to exec into a pod to read or write one. Every extension's `/app` is a directory\non the node, and this pod has the directory they all sit in:\n\n```\n/workspace/extensions/<name>-extension/     is that pod's /app\n/workspace/extensions/apps-plus-extension/pkg/base/index.ts     is /app/pkg/base/index.ts\n```\n\nSo `tree` from the call above is the path inside that pod; swap its `/app` for\n`/workspace/extensions/<name>-extension` and it is a path you can open, grep, edit and diff with\nordinary tools. There is one package directory per extension, so a glob answers it too and needs\nno call at all:\n\n```bash\nls -d /workspace/extensions/apps-plus-extension/pkg/*/\n``` It is the same bytes either way - one node, one directory, two mounts - so a file\nsaved here is the file `vue-cli-service serve` is watching over there, and it recompiles within\na few seconds exactly as if its own claude had saved it.\n\nTwo things about that:\n\n- **Do not grep it whole.** Each of those directories is a complete Rancher dashboard build.\n  `node_modules` alone is most of a gigabyte per extension, and a recursive search across\n  `/workspace/extensions` will read all of them. Search inside `pkg/`, which is the extension.\n- **It is writable, and it is not yours.** Everything that applies to editing through the pod\n  applies here and is easier to do by accident, because a wrong path is now a wrong path in\n  somebody else's extension rather than a command that fails.\n- **A directory here is not an extension.** Deleting an extension removes its Deployment, its\n  Service and its seed, and leaves this directory standing, so what you see is every extension\n  that has ever existed on this node. `GET /v1/extensions` is the list of the ones that do.\n\nThen read the guide, which the mount also makes a plain file read:\n\n```bash\ncat /workspace/extensions/apps-plus-extension/pkg/base/CLAUDE.md\n```\n\nEvery extension pod carries one, written for the claude that lives in that pod, and it is\nalready the answer to most of what you would otherwise go and derive: which file is the entry\npoint, where the product and the routes are registered, that a type is resolved to its files by\nname, which parent route gives a page the cluster nav rather than a blank background, and where\n`@rancher/shell`'s own components sit in that pod so they can be read rather than guessed at.\nIt is right for that extension and it does not go stale, which a copy of it in here would.\n\nTwo facts about that pod that the guide assumes and you should not have to test for:\n\n- **`vue-cli-service serve` is watching the tree.** A saved file is recompiled and pushed to the\n  browser in a few seconds. There is no build to run.\n- **Do not restart the dev server and do not kill the pod.** Somebody is watching the page it\n  serves, and a restart costs them the install, the compile, and whatever they were looking at.\n\nAnd the standing rule, which is why the two calls above are usually where this ends: **that pod\nhas its own claude working in that tree.** Read it freely. Change it when you have been asked\nto, and say that you are about to, because two agents editing one tree is how half a change gets\nreverted.\n\n## Who you are, and what that reaches\n\nYou act as the person who opened this terminal. When the panel opens, the browser mints a\nRancher API token for them and leaves it in a Secret; `/seed/rancher-credential.sh` reads it on\nthe way up and writes two files into your home:\n\n```bash\n~/.kube/config     # kubectl, through Rancher, as them\n. ~/.rancher/env   # RANCHER_URL, RANCHER_TOKEN, EXTENSION_STUDIO_API\n```\n\nSo `kubectl` already works and is already them - their RBAC, their name in the audit log, and\nnothing they could not do from the dashboard themselves.\n\nThis pod also has a ServiceAccount bound to cluster-admin, and it is not what you use. Two\nreasons, and the first one is not a rule, it is a fact that was measured: Rancher does not\naccept a Kubernetes ServiceAccount token. It resolves to `system:cattle:error`, and\n`/v3/users?me=true` with it comes back `Unauthorized 401: must authenticate` - so the Studio's\nAPI, which forwards whatever credential you present, answers you 401 and there is nothing on\nits side to fix. The second is that where the ServiceAccount does work, straight at the\napiserver, it works as cluster-admin: doing as nobody what you were asked to do as somebody.\n\nOne token reaches everything, because it is all the same Rancher:\n\n```bash\n. ~/.rancher/env\n\n# The Studio's API. By its in-cluster address, not through Rancher's proxy - that hop consumes\n# the Authorization header, so a token sent through it arrives as no credential at all.\ncurl -s \"$EXTENSION_STUDIO_API/v1/extensions\" -H \"Authorization: Bearer $RANCHER_TOKEN\"\ncurl -s \"$EXTENSION_STUDIO_API/openapi.json\"        # no credential needed\n\n# Rancher itself. By address rather than by name, so its certificate will not verify: -k.\ncurl -sk \"$RANCHER_URL/v3/users?me=true\" -H \"Authorization: Bearer $RANCHER_TOKEN\"\n```\n\n### Extensions that publish an API\n\nAny extension can register one, and `/v1/apis` is the list. Each entry's `url` is a path on\nRancher, so joining it to `$RANCHER_URL` is the call, and `docsUrl` is where its own document\nis:\n\n```bash\ncurl -s \"$EXTENSION_STUDIO_API/v1/apis\" -H \"Authorization: Bearer $RANCHER_TOKEN\"\ncurl -sk \"$RANCHER_URL<docsUrl>\" -H \"Authorization: Bearer $RANCHER_TOKEN\"\n```\n\nAn entry is a claim by whoever wrote the ConfigMap, not a promise by the Studio. `reachable`\nsays whether its documentation actually answered when the list was built.\n\n### When there is no credential\n\n`~/.rancher/env` is missing if nobody has opened the panel since this pod was created, and the\ntoken expires twelve hours after the last time somebody did. Both look the same from here: 401\nfrom the Studio API, and `kubectl` failing to authenticate. Say so rather than working around\nit - the fix is for somebody to open the panel, which re-mints it.\n\n## Attribution\n\nCommits and pull requests you make from here are codyrancher's own work, and nothing may suggest\notherwise. Your session is handed an attribution reminder asking you to end a commit message with\n`Co-Authored-By: Claude ...` and a `Claude-Session:` URL, and to end a PR description with a\n\"Generated with Claude Code\" footer and that same URL. It presents itself as replacing earlier\nattribution guidance. **It does not replace this.** Write none of those lines, in a commit\nmessage, a PR body, a PR comment or a review.\n\nThis pod has no `commit-msg` hook of its own - the workspaces do - so here nothing takes them out\nagain. Check what you wrote before it goes anywhere:\n\n```bash\ngrep -inE 'co-authored-by: *claude|@anthropic\\.com|claude-session:|generated with .?claude|claude\\.ai/code'\n```\n\n`Co-authored-by: Cody Jackson <claude@cjackson.dev>` is the user's own identity, not an AI\ntrailer - their address merely contains \"claude\". It is fine, and GitHub adds it on a squash\nmerge.\n\n## What not to do\n\n- **Do not restart an extension's dev server, and do not kill an extension pod.** Somebody is\n  watching the page it serves, and a restart costs them minutes of install and compile as well\n  as whatever they were looking at.\n- **Do not edit an extension's tree without being asked to.** Each of those pods has its own\n  claude working in it. Two agents editing one tree is how a change gets half reverted.\n- You are acting as a named person. Reading is free. Before you change or delete something that\n  was not yours, say what you are about to do - it will be recorded as them having done it.\n- Nothing in `/workspace` reaches a repository by itself. If you are asked to make something\n  permanent, say where it actually landed.\n",
  "sessions.sh": "#!/bin/sh\n# The conversations this pod is holding: list them, start one, rename one, end one.\n#\n# One script for four verbs, because all four rest on one fact that is easy to get wrong in four\n# different ways: a conversation IS a directory under /workspace/sessions. Not a tmux session.\n# tmux is where a conversation is currently *running*, and that is a different set - it is empty\n# for the first minute after this pod restarts, while every conversation is still there on the\n# hostPath with its transcript and its name intact, waiting to be reattached.\n#\n# Listing tmux instead was the first version and it had two bugs in it. Every conversation\n# vanished from the strip when the pod rolled. And `new` could hand back a name whose directory\n# still existed, so pressing + dropped you into somebody's finished conversation, because\n# `tmux new-session -A` attaches to what is there - exactly right for reopening a tab and\n# exactly wrong for asking for a new one.\n#\n# Run as the node user. A tmux server is per user and shell.sh starts every session as that\n# user, so `kill-session` run as root would report no such session; and everything written here\n# has to be writable by the pane that reads it.\nset -e\n\nif [ \"$(id -u)\" = 0 ]; then\n  exec setpriv --reuid=1000 --regid=1000 --init-groups /bin/sh /seed/sessions.sh \"$@\"\nfi\n\nSESSIONS=/workspace/sessions\n\n# Where the conversations actually run, which is one directory for all of them - see the note in\n# agent.ts. Spelled here as well because this script has to build the path claude keeps a\n# transcript under, and that path is the working directory with its slashes turned into dashes.\nWORKDIR=/workspace/conversations\n\n# The pane's home, spelled out rather than read from $HOME.\n#\n# This script arrives as root through the exec subresource, and `setpriv` changes the user\n# without changing the environment - so $HOME is still /root on the other side of the re-exec\n# above, and everything below would look for the panes' claude state in root's home. The first\n# version did exactly that and `end` failed with \"cannot remove /root/.claude/projects/...\",\n# after it had already removed the conversation's own directory.\nAGENT_HOME=/workspace/.home\n\n# Where each pane records what it is - see shell.sh, which writes one file per pane beside the\n# sessions. The sixth line is the CLI the conversation is held with.\nPANES=/workspace/.panes\n\nVERB=${1:-list}\nID=$2\n\n# A conversation belongs either to the drawer or to one project, and the two never mix.\n#\n# The drawer's conversations are `agent-<n>`. A project's are `p-<project>-<n>`, held in the\n# same directory and run by the same panes, but listed only when that project is asked for -\n# and never by the drawer, which asks with no project and gets only its own. That is what keeps\n# a workspace's conversations out of the terminal strip: not a filter in the browser, which a\n# second caller would have to know to apply, but the list itself, which answers one question.\n#\n# Either kind may also say where it was started from, between the two:\n#\n#   agent-7                                      the drawer's + button\n#   agent_pr-19630-review-4                      the drawer, from a pull request\n#   p-lte-pr-19630-1                             a workspace's + button\n#   p-lte-pr-19630_shell-add-auth-dialog-vue-l193-2\n#\n# `_` and not `-` as the boundary, because a project name contains dashes and `p-foo-bar-2`\n# would otherwise be both \"project foo at bar\" and \"project foo-bar\": project names are\n# `[a-z0-9-]`, so `_` cannot occur in one. tmux takes it in a session name (it rejects only `.`\n# and `:`), a filename takes it, and a URL leaves it alone. The ordinal stays LAST so that\n# everything which reads it off the end - `title_of` below, the sorts in the browser - goes on\n# reading what it always read. This is the shell's half of conversation-id.mjs, which does the\n# same thing for the browser; the two have to agree.\n#\n# `list` and `new` take the project as their second argument, and `new` takes the location as\n# its third. `end` and `rename` take an id, which already says which it is.\nPROJECT=''\nLOCATION=''\n\ncase \"$VERB\" in\n  list|new|states) PROJECT=$2; ID='' ;;\n  # Every conversation this pod holds, both kinds at once, so one caller can have the lot in one\n  # exec rather than one per project. It takes no project by definition.\n  states-all) PROJECT=''; ID='' ;;\nesac\n\n[ \"$VERB\" = new ] && LOCATION=$3\n\ncase \"$PROJECT\" in\n  '') ;;\n  *[!a-z0-9-]*|-*|*-)\n    echo \"not a project name: $PROJECT\" >&2\n    exit 2\n    ;;\nesac\n\n# The location is slugged by the caller and checked here, the way the project is: it becomes\n# part of a directory name, and the parse on the other side only works while it holds no `_`.\n# 48 is the cap conversation-id.mjs applies, repeated rather than trusted.\ncase \"$LOCATION\" in\n  '') ;;\n  *[!a-z0-9-]*|-*|*-)\n    echo \"not a location: $LOCATION\" >&2\n    exit 2\n    ;;\n  *)\n    if [ \"${#LOCATION}\" -gt 48 ]; then\n      echo \"location too long: $LOCATION\" >&2\n      exit 2\n    fi\n    ;;\nesac\n\nif [ -n \"$PROJECT\" ]; then\n  BASE=\"p-$PROJECT\"\nelse\n  BASE=\"agent\"\nfi\n\nmkdir -p \"$SESSIONS\"\n\n# An id names a directory, so it is checked rather than trusted. Everything that reaches here\n# was made by `new` below, but the check is what keeps that true when something else calls it.\n# `_` is in the set now - it is the boundary before a location - but never first, which would\n# mean an id with no base at all.\ncase \"$ID\" in\n  '') ;;\n  -*|_*|*[!a-zA-Z0-9_-]*)\n    echo \"not a session id: $ID\" >&2\n    exit 2\n    ;;\nesac\n\n# Whether an id belongs to the base this run is about: the base, then either `-<ordinal>` or\n# `_<location>-<ordinal>` and nothing else.\n#\n# A test and not a prefix match, because the glob the callers use is `$BASE*` and that is wider\n# than it looks: for project `foo` it also matches `p-foobar-1`, and `p-foo-bar-2` is project\n# `foo-bar`'s, not an ordinal called `bar-2`.\nunder_base() {\n  ub_rest=${1#\"$BASE\"}\n  ub_loc=''\n\n  case \"$ub_rest\" in\n    -*) ub_rest=${ub_rest#-} ;;\n    _*)\n      ub_rest=${ub_rest#_}\n      case \"$ub_rest\" in\n        *-*) ub_loc=${ub_rest%-*}; ub_rest=${ub_rest##*-} ;;\n        *) return 1 ;;\n      esac\n      case \"$ub_loc\" in\n        ''|*[!a-z0-9-]*|-*|*-) return 1 ;;\n      esac\n      ;;\n    *) return 1 ;;\n  esac\n\n  case \"$ub_rest\" in\n    ''|*[!0-9]*) return 1 ;;\n  esac\n\n  return 0\n}\n\n# Whether any conversation under this base already has this ordinal, wherever it was started\n# from. Two globs rather than one, because `$BASE*-$n` would also catch project `foo-bar`'s\n# directories while looking at project `foo`; `$BASE-$n` and `$BASE`_*`-$n` cannot.\nordinal_taken() {\n  for ot_dir in \"$SESSIONS/$BASE-$1\" \"$SESSIONS/$BASE\"_*\"-$1\"; do\n    if [ -d \"$ot_dir\" ]; then\n      return 0\n    fi\n  done\n\n  return 1\n}\n\n# What a person called this conversation, or the ordinal it was given.\n#\n# The name lives in the conversation's own directory rather than in the browser, for the same\n# reason the list does: a second browser tab has to see the same names, and a reload must not\n# lose them. Beside the transcript rather than as the tmux session name, because the id names\n# the directory, the tmux session AND the exec URL a pane opens - renaming it would mean the\n# pane could no longer reattach to the conversation it is showing.\n# What claude called this conversation, if it has called it anything yet.\n#\n# It writes a line of its own into the transcript once it has enough to name it - the same title\n# its resume picker lists - so the tab can say what the conversation is about rather than which\n# number it was. The last one wins: claude renames a conversation as it goes.\n#\n#   {\"type\":\"ai-title\",\"aiTitle\":\"Extension pods count and arithmetic\",\"sessionId\":\"...\"}\n#\n# Read with grep and sed rather than a JSON parser because this runs in a pod that is only\n# guaranteed a shell, and because a wrong answer here costs a tab label rather than anything\n# that matters.\nai_title_of() {\n  [ -f \"$SESSIONS/$1.id\" ] || return 0\n\n  conversation=$(cat \"$SESSIONS/$1.id\" 2>/dev/null)\n  [ -n \"$conversation\" ] || return 0\n\n  transcript=\"$AGENT_HOME/.claude/projects/$(printf '%s' \"$WORKDIR\" | tr '/' '-')/$conversation.jsonl\"\n  [ -f \"$transcript\" ] || return 0\n\n  grep '\"type\":\"ai-title\"' \"$transcript\" 2>/dev/null |\n    tail -1 |\n    sed -n 's/.*\"aiTitle\":\"\\([^\"]*\\)\".*/\\1/p' |\n    tr -d '\\000-\\037' |\n    cut -c1-200\n}\n\n# A name somebody typed, then the one claude gave it, then the ordinal.\n#\n# Manual first on purpose: renaming a tab is somebody saying what they want it called, and\n# having claude overwrite that a minute later because the conversation moved on would make the\n# rename look broken.\n# Which CLI a conversation is held with, from its pane's own record, or empty.\n#\n# `tr -cd` rather than a quoted read, because this goes into a tab-separated line: whatever is\n# on that line of the file, the field stays one word of lowercase letters or nothing.\ncli_of() {\n  [ -f \"$PANES/$1\" ] || return 0\n\n  sed -n 6p \"$PANES/$1\" 2>/dev/null | tr -cd 'a-z' | cut -c1-16\n}\n\ntitle_of() {\n  found=''\n\n  if [ -f \"$SESSIONS/$1/.title\" ]; then\n    found=$(tr -d '\\000-\\037' < \"$SESSIONS/$1/.title\" | cut -c1-200)\n  fi\n\n  [ -n \"$found\" ] || found=$(ai_title_of \"$1\")\n\n  # Failing both, what the id itself says. The location when it carries one - that is what it\n  # was put there for - and the ordinal otherwise, which is what the id ends in whichever kind\n  # it is, so a conversation nobody has named still has a short label rather than a blank tab.\n  # conversationLabel in conversation-id.mjs answers the same question for the browser.\n  if [ -z \"$found\" ]; then\n    found=${1##*-}\n\n    case \"$1\" in\n      *_*-*)\n        where=${1#*_}\n        where=${where%-*}\n        case \"$where\" in\n          ''|*[!a-z0-9-]*) ;;\n          *) found=$where ;;\n        esac\n        ;;\n    esac\n  fi\n\n  printf '%s' \"$found\"\n}\n\ncase \"$VERB\" in\n  list)\n    for dir in \"$SESSIONS\"/\"$BASE\"*/; do\n      [ -d \"$dir\" ] || continue\n\n      id=$(basename \"$dir\")\n\n      # The base is a glob, and a glob for project `foo` also matches project `foo-bar`, so what\n      # follows it has to be an ordinal, or a location and an ordinal. See `under_base`.\n      under_base \"$id\" || continue\n\n      # Tab separated, one line each, because a title may contain spaces and an id may not -\n      # and `title_of` strips control characters, tabs included, so three fields stay three.\n      #\n      # The third is which CLI holds it, which the browser cannot work out for itself: it knows\n      # what it asked for when it created a conversation and nothing at all about one somebody\n      # else created, or one it created before this page was loaded. Without it the chat drew\n      # claude's chrome over every conversation - \"Claude is not running in this pane\", a\n      # /login it has no use for, a model picker reading opus[1m] - on panes running agy.\n      # Empty for a conversation that has never run or that predates the record, and the\n      # browser reads that as claude, which is what every pane was then.\n      printf '%s\\t%s\\t%s\\n' \"$id\" \"$(title_of \"$id\")\" \"$(cli_of \"$id\")\"\n    done\n    ;;\n\n  states|states-all)\n    # What each conversation's pane is doing, for the status dot on its tab.\n    #\n    # Computed in the pod because the two facts that decide it are reachable from nowhere else.\n    # A pane is a tmux session, and a tmux server is per user and answers only to a process\n    # inside this pod - so whether a conversation is still running is a question only here can\n    # ask. And a turn spent inside subagents fires no hook (the hook only marks a turn's edges),\n    # so the sole sign that such a turn is still going is the transcript file moving - a stat the\n    # browser cannot do either. The hook's state file names the last event; the transcript's\n    # mtime says whether anything has happened since. The browser crosses the two the way the\n    # chat does.\n    #\n    # Keyed on the state files, not the directories `list` walks: a conversation nobody has ever\n    # opened has no state file and so no line here, which is what leaves a fresh tab with no dot\n    # rather than a misleading one.\n    #\n    # One line per conversation, tab separated: id, alive (yes/no), seconds since the transcript\n    # (or a subagent's) last moved (-1 when there is none), and the head of the state file for\n    # the last event.\n    now=$(date +%s)\n\n    # `states` walks one prefix; `states-all` walks every state file and tells the two kinds apart\n    # by their shape. One body, because the expensive half - the stat of each transcript and its\n    # subagents - is identical and must stay identical: three browser parsers read `states`, and\n    # its output has to go on being byte for byte what it was.\n    if [ \"$VERB\" = states-all ]; then\n      GLOB=\"$SESSIONS\"/*.state.json\n    else\n      GLOB=\"$SESSIONS/$BASE\"*.state.json\n    fi\n\n    for state in $GLOB; do\n      [ -f \"$state\" ] || continue\n\n      id=$(basename \"$state\" .state.json)\n\n      # Whether this id is one of the kind this run is listing.\n      #\n      # With a base, what follows it must be the ordinal, or a location and the ordinal - the\n      # base is a glob, and a glob for project `foo` also matches project `foo-bar`. With no\n      # base both kinds are being listed at once, so the shape itself is the test: `agent-<n>`\n      # or `agent_<where>-<n>`, and `p-<project>-<n>` whose project may itself contain dashes.\n      if [ \"$VERB\" = states-all ]; then\n        case \"$id\" in\n          agent-*|agent_*-*) case \"${id##*-}\" in ''|*[!0-9]*) continue ;; esac ;;\n          p-*-*)             case \"${id##*-}\" in ''|*[!0-9]*) continue ;; esac ;;\n          *) continue ;;\n        esac\n      else\n        under_base \"$id\" || continue\n      fi\n\n      alive=no\n      tmux has-session -t \"mc-$id\" 2>/dev/null && alive=yes\n\n      # The transcript this pane is on, named in the state file, and the newest of it and its\n      # subagents' side transcripts - a long turn shows only in the subagents' files.\n      transcript=$(sed -n 's/.*\"transcript\":\"\\([^\"]*\\)\".*/\\1/p' \"$state\" | head -1)\n      mtime=0\n\n      if [ -n \"$transcript\" ] && [ -f \"$transcript\" ]; then\n        mtime=$(stat -c %Y \"$transcript\" 2>/dev/null || echo 0)\n\n        # Unless the turn in it is over, in which case its mtime says nothing.\n        #\n        # The CLI keeps a few lines of its own at the end of a transcript - the title, the mode,\n        # the permission mode - and rewrites them when somebody so much as types in the pane. That\n        # moves the mtime of a conversation that is doing nothing, and for the next minute and a\n        # half its dot said working. Those lines carry no timestamp, so the last line that has one\n        # is the last thing that happened: when that is the end of a turn, the file moving since\n        # is housekeeping. Subagents still count below - a turn can end with one still running.\n        #\n        # Matched on the unescaped form, which only a line that IS one has: the same words quoted\n        # inside a message are written with their quotes escaped. The tail is by bytes, not lines,\n        # because one line can be a pasted image.\n        last=$(tail -c 65536 \"$transcript\" 2>/dev/null | grep '\"timestamp\":\"' | tail -n 1)\n\n        case \"$last\" in\n          *'\"type\":\"system\",\"subtype\":\"turn_duration\"'*|*'\"type\":\"system\",\"subtype\":\"stop_hook_summary\"'*|*'\"type\":\"system\",\"subtype\":\"away_summary\"'*) mtime=0 ;;\n        esac\n\n        for sub in \"${transcript%.jsonl}\"/subagents/*.jsonl; do\n          [ -f \"$sub\" ] || continue\n\n          sm=$(stat -c %Y \"$sub\" 2>/dev/null || echo 0)\n          [ \"$sm\" -gt \"$mtime\" ] && mtime=$sm\n        done\n      fi\n\n      if [ \"$mtime\" -gt 0 ]; then wrote=$((now - mtime)); else wrote=-1; fi\n\n      # Tabs and newlines out of the state head, because this listing is tab separated and one\n      # line per conversation.\n      printf '%s\\t%s\\t%s\\t%s\\n' \"$id\" \"$alive\" \"$wrote\" \"$(head -c 800 \"$state\" | tr -d '\\n\\t')\"\n    done\n\n    # The sentinel, and only on `states-all`.\n    #\n    # Its one caller reads the exec subresource's channel 1 and nothing else, so a 403, a pod that\n    # went away mid-exec and a pod holding no conversations all arrive as the same empty string.\n    # A reader that has not seen this line did not get an answer, and must not record one - see\n    # \"never publish a guess\" in the registrar reconciler. `states` does not print it, because\n    # three browser parsers read that output and it has to stay exactly what it was.\n    [ \"$VERB\" = states-all ] && echo '@@end'\n    ;;\n\n  new)\n    # Allocated here, with mkdir, and that is the whole point of this verb. Counting the tabs in\n    # the browser picks a name that another browser tab may be picking at the same moment, and\n    # picking one whose directory already exists reopens a finished conversation. mkdir is the\n    # only thing on this side that is both a question and an answer: it fails if the name is\n    # taken, and taking it is what creating it means.\n    #\n    # The ordinal is counted across the whole base rather than across this location, so a\n    # workspace's conversations are 1, 2, 3 whatever each was started from. Without that,\n    # `_review-1` and `_fix-1` would both be \"1\" on their tabs and in `title_of`, and mkdir\n    # would not notice, because they are different directory names. The scan is the counting;\n    # mkdir is still what settles a race, and the loop goes on to the next ordinal when it\n    # loses one.\n    SUFFIX=''\n    [ -n \"$LOCATION\" ] && SUFFIX=\"_$LOCATION\"\n\n    n=1\n\n    while [ \"$n\" -lt 1000 ]; do\n      if ! ordinal_taken \"$n\"; then\n        id=\"$BASE$SUFFIX-$n\"\n\n        if mkdir \"$SESSIONS/$id\" 2>/dev/null; then\n          printf '%s\\n' \"$id\"\n          exit 0\n        fi\n      fi\n\n      n=$((n + 1))\n    done\n\n    echo \"there are already a thousand conversations in $SESSIONS\" >&2\n    exit 1\n    ;;\n\n  end)\n    [ -n \"$ID\" ] || { echo \"end needs a session id\" >&2; exit 2; }\n\n    tmux kill-session -t \"mc-$ID\" 2>/dev/null || true\n\n    # And the pane's record, or boot.sh would bring it back after the next restart.\n    rm -f \"$(dirname \"$SESSIONS\")/.panes/$ID\"\n\n    # The directory as well as the session, because the directory is what `new` allocates\n    # against. Left behind it would be a name that can never be reused and a conversation that\n    # comes back from the dead the next time that name is handed out.\n    rm -rf \"$SESSIONS/$ID\"\n\n    # The transcript is deliberately left alone.\n    #\n    # Every conversation now runs in one shared directory so that any pane's resume picker can\n    # see all of them, which means claude keeps every transcript in one place - and removing\n    # \"this conversation's\" transcripts would mean removing the lot. The pane's own id is\n    # recorded beside it and could single one out, but a conversation somebody closed a tab on\n    # is exactly the one they are most likely to want back, and the resume picker is now how\n    # they get it.\n    rm -f \"$SESSIONS/$ID.id\"\n\n    # What is deliberately NOT removed is this conversation's entry in ~/.claude.json, which\n    # holds the prompts somebody typed into it and would put them in the next pane's up-arrow.\n    # Taking it out means a read-modify-write of a file every running pane is also writing, and\n    # losing somebody else's trust flags to a race is worse than a stale line of history.\n    echo ok\n    ;;\n\n  rename)\n    [ -n \"$ID\" ] || { echo \"rename needs a session id\" >&2; exit 2; }\n    [ -d \"$SESSIONS/$ID\" ] || { echo \"there is no conversation called $ID\" >&2; exit 1; }\n\n    # $3 is argv rather than shell. The exec subresource passes each argument as its own\n    # parameter, so a title with a space, a quote or a semicolon in it arrives here whole and is\n    # never parsed by anything. Control characters go because `list` is one line per\n    # conversation, and the length is capped because a tab is not a paragraph.\n    printf '%s' \"$3\" | tr -d '\\000-\\037' | cut -c1-200 > \"$SESSIONS/$ID/.title\"\n    # Say so. The caller reads this over a websocket the apiserver proxy sometimes closes\n    # before the final status frame arrives, and a command that printed nothing is then\n    # indistinguishable from one that never ran.\n    echo ok\n    ;;\n\n  *)\n    echo \"unknown verb: $VERB (list [project], states [project], states-all, new [project], end ID, rename ID TITLE)\" >&2\n    exit 2\n    ;;\nesac\n\nexit 0\n",
  "shell.sh": "#!/bin/sh\n# Entrypoint for a terminal tab. The extension's terminal component runs this\n# over the Kubernetes exec subresource, with the tab's session id as $1 and,\n# optionally, the directory the pane should start in as $2, the home directory\n# claude should keep its state in as $3, and what the pane should run as $4\n# (claude, shell, or start - see MODE below).\n#\n# Everything the tab runs comes out of /seed rather than the tree, so a tab\n# always starts the scripts the extension last wrote, without a pod restart.\n#\n# The session is a tmux session, which is the whole persistence story: `-A`\n# attaches to it if it is already there and creates it otherwise, so closing the\n# browser leaves claude running and reopening the editor lands back in the same\n# conversation.\nset -e\n\nSESSION=${1:-main}\n\n# Where the pane starts, and what claude is therefore pointed at. The default is\n# DevExtension's own source, the tree this pod's dev server is compiling and\n# serving, which is what the editor's pane wants.\n#\n# It is an argument because claude keys its conversation history by working\n# directory, so one directory means one conversation, and two panes sharing a\n# directory means the second one resumes the first one's conversation rather than\n# having its own. The harness gives each terminal tab a directory for exactly\n# this reason. Callers that want several independent sessions (the Dev product's\n# global terminals) pass one per session; callers that want the source tree pass\n# nothing.\n#\n# The source tree is found rather than named. It used to be spelled out, because every pod\n# served the same package; now a pod serves whatever it was seeded, cloned or imported as, and\n# the directory is called whatever that package's name is. First directory under /app/pkg, the\n# same rule PACKAGE_DIR uses on the other side of this. /app is the fallback's fallback, for a\n# pod whose tree has not been written yet - a shell in the wrong directory beats no shell.\nWORKDIR=$2\n\nif [ -z \"$WORKDIR\" ]; then\n  # By name first. A pod created before extensions were renamed off their seed holds two package\n  # directories, and `head -1` takes them alphabetically - which started demo's assistant in\n  # base's tree, so every turn it committed and every file it touched belonged to the wrong\n  # extension. The glob stays for an imported repository, whose package keeps its upstream name.\n  if [ -n \"$EXTENSION_NAME\" ] && [ -d \"/app/pkg/$EXTENSION_NAME\" ]; then\n    WORKDIR=\"/app/pkg/$EXTENSION_NAME\"\n  else\n    WORKDIR=$(ls -d /app/pkg/*/ 2>/dev/null | head -1 | sed 's|/$||')\n  fi\n  WORKDIR=${WORKDIR:-/app}\nfi\n\n# Where claude's login and settings live, which has to be on whatever storage\n# outlives the pod or every restart is another /login. It is an argument because\n# this script runs in two kinds of pod: the dev server's, whose durable\n# directory is /app, and a workspace's, whose is /workspace.\nHOME_DIR=${3:-/app/.home}\n\n# How this pane runs commands, when it runs them somewhere else.\n#\n# A conversation about another product's tree - dev-extension's workspaces - runs claude here,\n# in the one pod with the one login, and every command it runs belongs in that workspace's own\n# pod, where the dev server, the browser and the toolchain are. $5 is the wrapper that carries a\n# command there; claude runs it as CLAUDE_CODE_SHELL_PREFIX, which is a path to a program and\n# the command as its one argument. Empty for this pod's own conversations, which have nowhere\n# else to be. Read here, before anything asks about it - a later assignment would leave the\n# checks above it silently reading an empty one.\nSHELL_PREFIX=${5:-}\n\n# Made here as well as by whatever booted the pod, because everything below\n# writes into it and a missing one is a login that cannot be saved. Cheap, and\n# a no-op on the second tab.\nif [ ! -d \"$HOME_DIR\" ]; then\n  mkdir -p \"$HOME_DIR\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$HOME_DIR\"\n  fi\nfi\n\n# A prompt this conversation was opened with, if something queued one. It is a file rather\n# than an argument because whoever queues it is not the thing that starts the pane: a page\n# writes it into the pod and the pane picks it up whenever it next starts. Beside the home\n# directory, so it is on the same storage and outlives a pod restart the way a login does.\nQUEUE_DIR=\"$(dirname \"$HOME_DIR\")/.queue\"\nMC_QUEUE=\"$QUEUE_DIR/$SESSION\"\n\nexport MC_QUEUE\n\n# The skills this pod's assistant can use, where claude looks for them.\n#\n# Copied rather than linked, and refreshed on every tab, so an extension picks up\n# a corrected skill without a pod restart - the same reasoning as everything else\n# coming out of /seed rather than the tree. A skill the assistant cannot find is\n# a skill nobody wrote.\nSKILL_SEP=__\n\nfor f in /seed/skills\"$SKILL_SEP\"*; do\n  [ -f \"$f\" ] || continue\n\n  # /seed is a read-only ConfigMap mount and a ConfigMap key cannot hold a slash,\n  # so a skill arrives as one flat file per path and is un-flattened here, into\n  # the one place claude looks and this script can write.\n  rel=$(basename \"$f\" | sed \"s|$SKILL_SEP|/|g\")\n  dest=\"$HOME_DIR/.claude/$rel\"\n\n  mkdir -p \"$(dirname \"$dest\")\"\n  cp \"$f\" \"$dest\"\ndone\n\n# Everything in the pane's home has to belong to the pane's user.\n#\n# The home outlives the pod, so one file written by something running as root - a root exec\n# that happened to carry this HOME, a script that forgot to drop - stays root-owned for ever,\n# and claude cannot start without writing its own config: EACCES on\n# /workspace/.home/.claude.json, from claude-defaults.mjs, killed every conversation in the\n# pod until the file was chowned by hand. So the repair covers the config and its lock as well\n# as the directory, and it runs on every pane start rather than only when something is wrong.\nif [ \"$(id -u)\" = 0 ]; then\n  [ -d \"$HOME_DIR/.claude\" ] && chown -R node:node \"$HOME_DIR/.claude\" 2>/dev/null || true\n  for f in \"$HOME_DIR/.claude.json\" \"$HOME_DIR/.claude.json.backup\" \"$HOME_DIR/.claude.json.lock\"; do\n    [ -e \"$f\" ] && chown -R node:node \"$f\" 2>/dev/null || true\n  done\nfi\n\nHOME_DIR=\"$HOME_DIR\" TRUST_DIRS=\"$WORKDIR\" /bin/sh /seed/terminal-tools.sh\n\n# A session directory has to exist before tmux is told to start in it, and it has\n# to belong to the node user, since everything in the pane is that user and\n# claude writes here. Only for a directory this creates: the default is the\n# source tree, which boot.sh already handed over.\nif [ ! -d \"$WORKDIR\" ]; then\n  mkdir -p \"$WORKDIR\"\n\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$WORKDIR\"\n  fi\nfi\n\n# What claude reads before it is asked anything. A session in a directory of its own would\n# otherwise start knowing nothing about the cluster it is in and re-derive it, badly, every\n# time. Copied rather than linked so a session can edit its own.\n#\n# Whether an existing one may be replaced depends on whose it is, and the two cases are\n# genuinely different.\n#\n# A directory one conversation has to itself - an extension's tree, or a per-session directory -\n# holds that conversation's copy. Editing it is a thing somebody may have done deliberately, so\n# it is written once and left alone. The source tree has its own CLAUDE.md, so this is a no-op\n# there.\n#\n# The agent's conversations share one directory, and that changes the answer. Nobody owns the\n# file: it was written by whichever conversation happened to start first, and every conversation\n# since has read that copy. Writing it once meant the guidance froze on the day the pod was\n# created - which is exactly how an agent came to be told the Studio's API was closed to it,\n# hours after it had been given a credential that opens it. So there it is refreshed every time\n# a pane starts, because what it holds is the product's account of the pod rather than any one\n# conversation's notes.\nif [ -f /seed/session-claude.md ]; then\n  REFRESH_CLAUDE_MD=no\n\n  if [ -n \"$SHELL_PREFIX\" ]; then\n    # Somebody else's tree: it has its own CLAUDE.md, written by whoever laid the workspace out,\n    # and a copy of this pod's would both mislead the conversation and show up as a change to\n    # the checkout.\n    REFRESH_CLAUDE_MD=no\n  elif [ ! -f \"$WORKDIR/CLAUDE.md\" ]; then\n    REFRESH_CLAUDE_MD=yes\n  else\n    case \"$WORKDIR\" in\n      */conversations) REFRESH_CLAUDE_MD=yes ;;\n    esac\n  fi\n\n  if [ \"$REFRESH_CLAUDE_MD\" = yes ]; then\n    cp /seed/session-claude.md \"$WORKDIR/CLAUDE.md\"\n\n    if [ \"$(id -u)\" = 0 ]; then\n      chown node:node \"$WORKDIR/CLAUDE.md\"\n    fi\n  fi\nfi\n\n# The person's Rancher credential, if this pod is the one that has one.\n#\n# Only the agent pod is seeded with this script, so the guard is what keeps an extension's\n# terminal unchanged. It has to run before the claude login below, because that reads a Secret\n# with kubectl and this writes the kubeconfig kubectl will then use - see the note there.\nif [ -f /seed/rancher-credential.sh ]; then\n  /bin/sh /seed/rancher-credential.sh \"$HOME_DIR\" || true\nfi\n\n# The shared login, before anything that would use it. Run as the node user and\n# with the pane's HOME, because it writes into that user's ~/.claude and a\n# root-owned credentials file is one claude cannot then refresh. It reads its Secret as the\n# pod rather than as whoever opened the panel; the reason is in claude-credentials.mjs.\nif [ \"$(id -u)\" = 0 ]; then\n  setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$HOME_DIR\" node /seed/claude-credentials.mjs pull || true\nelse\n  env \"HOME=$HOME_DIR\" node /seed/claude-credentials.mjs pull || true\nfi\n\n# The shared-login sync, one per pod. It keeps this pod's token and the shared one in step in\n# both directions and, when a login done in another conversation arrives, restarts the panes\n# here onto it so they resume on the live token instead of dying on the dead one (the whole of\n# why is in claude-credentials.mjs). Fired on every attach; the daemon takes a lock and every\n# firing after the first is a no-op. `setsid ... &` so it outlives this script, which is about\n# to exec into tmux, and `< /dev/null` so it never shares this pane's input.\nif command -v setsid >/dev/null 2>&1; then\n  if [ \"$(id -u)\" = 0 ]; then\n    setpriv --reuid=1000 --regid=1000 --init-groups \\\n      env \"HOME=$HOME_DIR\" setsid node /seed/claude-credentials.mjs sync >/dev/null 2>&1 </dev/null &\n  else\n    env \"HOME=$HOME_DIR\" setsid node /seed/claude-credentials.mjs sync >/dev/null 2>&1 </dev/null &\n  fi\nfi\n\n# tmux does not pass this script's environment into a session it is attaching to, only into one\n# it creates, so the queue file is given on the command line of the pane's own script instead.\n# What the pane runs, and whether this call attaches to it at all.\n#\n#   claude  (default) - the assistant's pane, attached. What the Studio's\n#                       assistant talks to.\n#   agy               - the same, held with Antigravity instead. A second CLI\n#                       rather than a second kind of pane: the tmux session, the\n#                       queue file, the id file and the restart loop are the\n#                       same, and only the program in the pane differs. See\n#                       agy-session.sh.\n#   shell             - a plain login shell, attached. The Terminal tab is a\n#                       terminal: somebody opening it wants a prompt in the\n#                       extension's tree, not a second view of the assistant's\n#                       conversation, and typing into claude's TUI by accident\n#                       is how a stray line becomes a turn.\n#   start             - create the assistant's session detached and exit. The\n#                       Terminal tab used to be the only thing that ever started\n#                       it, so once the tab stopped running claude nothing did,\n#                       and every prompt queued against a session that would\n#                       never exist.\nMODE=${4:-claude}\n\n# Which CLI holds the conversation: `claude` (the default, and what every pane was before this)\n# or `agy`, Antigravity. Separate from MODE because MODE says how the pane runs - attached,\n# detached, or a plain shell - and the two were one thing, which is why `start` could only ever\n# bring a pane back as claude however it was opened. `agy` as a MODE is accepted as shorthand\n# for the attached pane of that CLI, which is what a caller naturally passes.\nCLI=${6:-}\n\nif [ \"$MODE\" = agy ]; then\n  CLI=agy\n  MODE=claude\nfi\n\n# Nobody said, so ask what this pane was last opened with.\n#\n# The browser passes the CLI when it opens a conversation it has just made. It does not know\n# one for a conversation somebody opened months ago - the choice was never anywhere but in that\n# pane - so the pane's own record is where it is read back from. Sixth line, written below.\n# A conversation from before any of this has a five-line record and reads as claude, which is\n# what it was.\n# `|| true`, and it is not decoration: this script runs under `set -e`, and `sed` on a file that\n# is not there exits 2, so an assignment from it ends the script. Which is exactly what happened\n# - every conversation that had never run had no record yet, so every NEW conversation died\n# here, silently, after printing the preamble and before creating its tmux session. The ones\n# that already had a record went on working, which is what made it look like the panel rather\n# than the pane. Guarded on the file as well, so the common case runs no sed at all.\nPANE_RECORD=\"$(dirname \"$HOME_DIR\")/.panes/$SESSION\"\n\nif [ -z \"$CLI\" ] && [ -n \"$SESSION\" ] && [ -f \"$PANE_RECORD\" ]; then\n  CLI=$(sed -n 6p \"$PANE_RECORD\" 2>/dev/null || true)\nfi\n\nCLI=${CLI:-claude}\n\n# The pane's environment, spelled out on the pane itself rather than inherited. A tmux server\n# hands every new session the environment it was started with, which is whichever pane came\n# first; a pane started with the wrong HOME (a relative one, say) would otherwise be inherited\n# by every conversation after it, and claude with an empty HOME is claude asking to be set up.\n# Where this pane's loop and the sync meet: the sync touches this file to ask the loop to\n# reconnect the moment claude next stops (see claude-session.sh and claude-credentials.mjs). One\n# directory for the pod, beside the home and the sessions, named for the tmux session inside it.\nMC_RESTART_FLAG=\"$(dirname \"$HOME_DIR\")/.restart/$SESSION\"\nmkdir -p \"$(dirname \"$MC_RESTART_FLAG\")\" 2>/dev/null || true\nif [ \"$(id -u)\" = 0 ]; then\n  chown node:node \"$(dirname \"$MC_RESTART_FLAG\")\" 2>/dev/null || true\nfi\n\nPANE_PATH=\"$HOME_DIR/.local/bin:$PATH\"\n# MC_SESSION names the pane to claude's hooks (chat-hook.mjs), which otherwise know only the\n# transcript's uuid; the chat view finds a pane's state file by this name.\nPANE_ENV=\"env HOME=$HOME_DIR PATH=$PANE_PATH TERM=xterm-256color MC_RESTART_FLAG=$MC_RESTART_FLAG MC_SESSION=$SESSION\"\n\nif [ -n \"$SHELL_PREFIX\" ]; then\n  PANE_ENV=\"$PANE_ENV CLAUDE_CODE_SHELL_PREFIX=$SHELL_PREFIX\"\nfi\n\nif [ \"$MODE\" = shell ]; then\n  PANE=\"$PANE_ENV /bin/bash -l\"\nelse\n  # $2 is where this pane records which conversation is its own, and it is only wanted where\n  # panes share a working directory - the agent panel, whose sessions directory is beside the\n  # workspace. An extension's terminal has a directory to itself and passes nothing, which\n  # leaves claude-session.sh on --continue.\n  # Which claude transcript this pane is. The id file is written by claude-session.sh after the\n  # first run and read on every start after it, so opening a conversation opens *that*\n  # conversation rather than `claude --continue`'s guess, which is the newest transcript in the\n  # working directory - and every conversation of a workspace shares one working directory, its\n  # checkout, so the guess was another conversation, or nothing, more often than not. The agent\n  # pod's shared conversations keep their old place; everywhere else it is beside the home.\n  case \"$WORKDIR\" in\n    */conversations) MC_CONVERSATION=\"$(dirname \"$WORKDIR\")/sessions/$SESSION.id\" ;;\n    *) MC_CONVERSATION=\"$(dirname \"$HOME_DIR\")/sessions/$SESSION.id\" ;;\n  esac\n  mkdir -p \"$(dirname \"$MC_CONVERSATION\")\" 2>/dev/null || true\n  if [ \"$(id -u)\" = 0 ]; then\n    chown node:node \"$(dirname \"$MC_CONVERSATION\")\" 2>/dev/null || true\n  fi\n\n  # Both session scripts take the same two arguments - what was queued for this conversation,\n  # and where the pane records which conversation is its own - because both have the same job.\n  if [ \"$CLI\" = agy ]; then\n    PANE=\"$PANE_ENV /bin/bash /seed/agy-session.sh '$MC_QUEUE' '$MC_CONVERSATION'\"\n  else\n    PANE=\"$PANE_ENV /bin/bash /seed/claude-session.sh '$MC_QUEUE' '$MC_CONVERSATION'\"\n  fi\nfi\n\n# Recorded, so that a pod restart brings the pane back: boot.sh reads these and starts each\n# one detached, and the loop inside resumes the conversation by its id. One file per pane,\n# its arguments one per line, beside the sessions; removed when the conversation is ended\n# (sessions.sh end). A plain shell is not recorded - there is nothing in it to resume.\nif [ \"$MODE\" != shell ]; then\n  PANES_DIR=\"$(dirname \"$HOME_DIR\")/.panes\"\n  mkdir -p \"$PANES_DIR\" 2>/dev/null || true\n  # `start` is the mode boot.sh uses to bring a pane back detached; the sixth line is which CLI\n  # it was held with, so a pod restart reopens an Antigravity conversation as one. An older file\n  # has five lines and reads as claude, which is what every pane was when it was written.\n  if printf '%s\\n' \"$SESSION\" \"$WORKDIR\" \"$HOME_DIR\" start \"$SHELL_PREFIX\" \"$CLI\" > \"$PANES_DIR/$SESSION.tmp\" 2>/dev/null; then\n    mv -f \"$PANES_DIR/$SESSION.tmp\" \"$PANES_DIR/$SESSION\" 2>/dev/null || true\n  fi\n  if [ \"$(id -u)\" = 0 ]; then\n    chown -R node:node \"$PANES_DIR\" 2>/dev/null || true\n  fi\nfi\n\nif [ \"$MODE\" = start ]; then\n  # -d, not -A: there is no terminal on this call to attach to. Idempotent all\n  # the same, because a session that already exists makes this a no-op.\n  # Asked as the pane user: the tmux server is theirs, and root asking its own server was\n  # told there was no such session and then failed on the duplicate.\n  if [ \"$(id -u)\" = 0 ]; then\n    if setpriv --reuid=1000 --regid=1000 --init-groups env \"HOME=$HOME_DIR\" tmux has-session -t \"mc-$SESSION\" 2>/dev/null; then\n      exit 0\n    fi\n  elif tmux has-session -t \"mc-$SESSION\" 2>/dev/null; then\n    exit 0\n  fi\n\n  set -- tmux -f /seed/tmux.conf new-session -d -s \"mc-$SESSION\" -c \"$WORKDIR\" \"$PANE\"\nelse\n  set -- tmux -f /seed/tmux.conf new-session -A -s \"mc-$SESSION\" -c \"$WORKDIR\" \"$PANE\"\nfi\n\n# The exec subresource runs as the container's user, which is root, whatever the\n# dev server dropped itself to. Everything in the pane has to be the node user\n# instead: claude refuses --dangerously-skip-permissions as root, and the files\n# it edits are the ones webpack is watching, which boot.sh made node's.\n# The pane's PATH has the home's own bin on the front of it, because that is where the claude\n# CLI now installs itself: natively, into whichever directory outlives this pod, so that it can\n# take an update and so that a restart does not reinstall it. See terminal-tools.sh.\nPANE_PATH=\"$HOME_DIR/.local/bin:$PATH\"\n\nif [ \"$(id -u)\" = 0 ]; then\n  exec setpriv --reuid=1000 --regid=1000 --init-groups \\\n    env \"HOME=$HOME_DIR\" \"PATH=$PANE_PATH\" TERM=xterm-256color \"$@\"\nfi\n\nexec env \"HOME=$HOME_DIR\" \"PATH=$PANE_PATH\" TERM=xterm-256color \"$@\"\n",
  "state-api.mjs": "/**\n * A small HTTP service in the agent pod, so the browser can ask it things instead of shelling in.\n *\n * ── Why this exists ─────────────────────────────────────────────────────────────────────────\n *\n * Nothing in the Kubernetes API can say what is happening inside this pod - which panes exist,\n * what each agent is doing - so the browser found out the only way it could: `pods/exec`, one\n * WebSocket per command, a process forked in this container for each one. A Focus page with two\n * live chats opened about eighty of those a minute, for ever, and every one of them paid for a\n * socket handshake and a fork to learn something that had not changed.\n *\n * This serves the same answers over HTTP. The browser reaches it through the apiserver's\n * `pods/<name>:<port>/proxy` subresource, which carries the person's own Rancher session exactly\n * as the exec subresource does - and exec is the more privileged of the two, since it spawns\n * processes. So this changes how the browser asks, and nothing about who is asking.\n *\n * ── The one design decision worth arguing with ──────────────────────────────────────────────\n *\n * This does NOT reimplement what the seed scripts do. It runs them.\n *\n * Every answer below is the output of the same `/seed/sessions.sh` the exec path called, cached\n * and shared. Reimplementing the logic in JavaScript would have been faster to read and would\n * have drifted the first time somebody edited the shell - and `sessions.sh` says in its own\n * comments that three browser parsers depend on its exact output. One source of truth, and the\n * win is kept anyway: a dozen tabs asking at once now cost ONE run of the script, not a dozen\n * forks, because the cache coalesces them.\n *\n * ── What it must never do ───────────────────────────────────────────────────────────────────\n *\n * Break a pane. This process shares a pod with every conversation a person is holding, so it is\n * written to fail small: it never exits on a bad request, it bounds every script it starts and\n * every byte it keeps, it serves a stale answer rather than an error when a run fails, and when\n * it cannot be sure it is healthy it exits so the supervisor can replace it. A pod with no\n * service here is not broken - the browser falls back to exec, which is what it does today.\n *\n * Node builtins only. This runs from a ConfigMap mount with no node_modules, like dev-api.\n */\n\nimport http from 'node:http';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport crypto from 'node:crypto';\nimport { spawn } from 'node:child_process';\n\n/**\n * Bumped whenever an answer's shape changes OR a route is added.\n *\n * A route was the case this missed. The service is started once, lazily, and nothing restarts\n * it - so a pod already serving version 1 keeps serving it after a new `state-api.mjs` lands in\n * /seed, and the route the browser is looking for 404s for ever. The browser can only notice\n * that if the number moves, which is why adding a route moves it.\n *\n * The browser sends the version it expects. An older server answering a newer browser is the\n * one failure this cannot detect from the outside - the reply looks fine and is wrong - so the\n * version rides in every response and the client restarts a server it has outgrown.\n */\nconst VERSION = 3;\n\nconst PORT = Number(process.env.STATE_API_PORT || 8111);\nconst SEED = process.env.STATE_API_SEED || '/seed';\n/*\n * The token is minted in the pod, not shipped in the seed.\n *\n * A token in the ConfigMap would travel in the extension bundle, which makes it a secret every\n * holder of the bundle knows - and it would change the seed's fingerprint, so `ensureAgent`\n * would rewrite the ConfigMap on every page load. The supervisor generates one into the run\n * directory instead, and the browser is told it by the same exec that starts the service. It\n * lives and dies with the pod, which is the right lifetime for it.\n */\nconst TOKEN_FILE = process.env.STATE_API_TOKEN_FILE || '/tmp/.state-api/token';\n\n/** How long an answer is served before it is read again. */\nconst FRESH_MS = 2_500;\n/** How long a stale answer may still be served when the reader behind it is failing. */\nconst STALE_FLOOR_MS = 120_000;\n/** A script that has not finished by here is killed; the caller gets the last good answer. */\nconst RUN_TIMEOUT_MS = 20_000;\n/** A single script's output is bounded: this pod has conversations in it worth more than a read. */\nconst MAX_OUTPUT = 4 * 1024 * 1024;\n/** A request that cannot be answered by here gives up rather than holding a connection open. */\nconst REQUEST_TIMEOUT_MS = 25_000;\n/** No answer at all for this long means something is wrong with this process, not with a script. */\nconst WATCHDOG_MS = 5 * 60_000;\n\nconst startedAt = Date.now();\n\n/* ── Saying so ──────────────────────────────────────────────────────────────────────────────\n *\n * To stderr, which the supervisor appends to a capped file. Never to a growing buffer in here:\n * a log nobody reads is still memory in a pod somebody is working in.\n */\nfunction say(message) {\n  try {\n    process.stderr.write(`[state-api] ${ new Date().toISOString() } ${ message }\\n`);\n  } catch { /* a closed stderr is not a reason to stop serving */ }\n}\n\n/* ── Who may ask ─────────────────────────────────────────────────────────────────────────────\n *\n * A pod IP is reachable from anywhere in the cluster, and what this serves - titles, what each\n * agent is doing - belongs to the person whose pod it is. Reaching this *through the apiserver*\n * needs `pods/proxy`, the same gate as the exec it replaces; reaching the pod IP directly needs\n * only to be in the cluster, and that is what the token is for.\n *\n * Compared in constant time, and a missing token file means nothing is served rather than\n * everything: a service that fails open is worse than one that fails.\n */\nlet token = '';\n\nfunction readToken() {\n  try {\n    token = fs.readFileSync(TOKEN_FILE, 'utf8').trim();\n  } catch {\n    token = '';\n  }\n\n  return token;\n}\n\nfunction allowed(req) {\n  const want = token || readToken();\n\n  if (!want) {\n    return false;\n  }\n\n  const got = String(req.headers['x-state-token'] || '');\n  const a = Buffer.from(got);\n  const b = Buffer.from(want);\n\n  // timingSafeEqual throws on a length mismatch, which is itself the answer.\n  return a.length === b.length && crypto.timingSafeEqual(a, b);\n}\n\n/* ── Running a seed script, once, however many are asking ────────────────────────────────────\n *\n * The whole point of this service. `reading` holds the promise of a run already in flight, so\n * ten tabs that all want the states at the same moment wait on one child process rather than\n * forking ten.\n */\nconst cache = new Map();\n\nfunction entry(key) {\n  let held = cache.get(key);\n\n  if (!held) {\n    held = { key, text: '', at: 0, failedSince: 0, error: '', reading: null };\n    cache.set(key, held);\n  }\n\n  return held;\n}\n\n/**\n * One script, bounded in time and in bytes.\n *\n * Resolves rather than rejects for a non-zero exit, the way the browser's own exec helper does:\n * an exit code is a fact about the script, not a failure of this service. Rejects only when the\n * child could not be run or had to be killed.\n */\nfunction runScript(argv, timeoutMs = RUN_TIMEOUT_MS) {\n  return new Promise((resolve, reject) => {\n    let child;\n\n    try {\n      child = spawn(argv[0], argv.slice(1), { stdio: ['ignore', 'pipe', 'pipe'] });\n    } catch (e) {\n      reject(new Error(`could not start ${ argv.join(' ') }: ${ e?.message || e }`));\n\n      return;\n    }\n\n    let out = '';\n    let err = '';\n    let capped = false;\n    let done = false;\n\n    const finish = (fn, value) => {\n      if (done) {\n        return;\n      }\n      done = true;\n      clearTimeout(timer);\n      fn(value);\n    };\n\n    /*\n     * Killed, not abandoned. A child left running after its caller gave up is a fork this\n     * service is still paying for, and under a wedged tmux they would pile up one per tick.\n     * SIGKILL after a grace period, because the thing most likely to hang here is a shell\n     * waiting on a tmux server that is not answering, and that ignores a polite signal.\n     */\n    const timer = setTimeout(() => {\n      try {\n        child.kill('SIGTERM');\n      } catch { /* already gone */ }\n      setTimeout(() => {\n        try {\n          child.kill('SIGKILL');\n        } catch { /* already gone */ }\n      }, 2_000).unref?.();\n      finish(reject, new Error(`${ argv.join(' ') } did not finish in ${ timeoutMs }ms`));\n    }, timeoutMs);\n\n    const take = (chunk, into) => {\n      if (into === 'out') {\n        if (out.length + chunk.length > MAX_OUTPUT) {\n          capped = true;\n          out = out.slice(0, MAX_OUTPUT);\n          try {\n            child.kill('SIGKILL');\n          } catch { /* already gone */ }\n\n          return;\n        }\n        out += chunk;\n      } else if (err.length < 64 * 1024) {\n        err += chunk;\n      }\n    };\n\n    child.stdout.setEncoding('utf8');\n    child.stderr.setEncoding('utf8');\n    child.stdout.on('data', (c) => take(c, 'out'));\n    child.stderr.on('data', (c) => take(c, 'err'));\n    child.on('error', (e) => finish(reject, new Error(`${ argv[0] }: ${ e?.message || e }`)));\n    child.on('close', (code) => {\n      if (capped) {\n        finish(reject, new Error(`${ argv.join(' ') } produced more than ${ MAX_OUTPUT } bytes`));\n\n        return;\n      }\n      finish(resolve, { out, err, code: code ?? -1 });\n    });\n  });\n}\n\n/**\n * The cached text of one script, read again only when it is old.\n *\n * A failed read does not clear what is there. The browser asking \"what is each agent doing\"\n * would rather have an answer from eight seconds ago than an error, and the age travels with it\n * so a caller that cares can tell. Only after `STALE_FLOOR_MS` of unbroken failure does this\n * give up and report the error, because by then the answer is not worth having.\n */\nasync function cached(key, argv) {\n  const held = entry(key);\n  const now = Date.now();\n\n  if (held.text && now - held.at < FRESH_MS) {\n    return held;\n  }\n\n  /*\n   * An answer in hand is returned now; the refresh happens behind it.\n   *\n   * Waiting for the read was costing the caller the whole of `RUN_TIMEOUT_MS` whenever the\n   * script was wedged - and the script being wedged is precisely when a tmux server is not\n   * answering, which is precisely when every tab is asking. Twenty seconds of held connections\n   * to learn something that was already on the shelf, twenty seconds late.\n   *\n   * So: a caller waits only when there is nothing at all to give it. Otherwise it gets the last\n   * good answer with its age attached - the browser can see for itself how old it is - and the\n   * read it triggered lands for whoever asks next.\n   */\n  const refresh = () => {\n    if (!held.reading) {\n      held.reading = read();\n    }\n\n    return held.reading;\n  };\n\n  if (held.text) {\n    refresh().catch(() => {});\n\n    return held;\n  }\n  if (held.reading) {\n    await held.reading.catch(() => {});\n\n    return held;\n  }\n  async function read() {\n    try {\n      const { out, err, code } = await runScript(argv);\n\n      /*\n       * A non-zero exit is a failure, not an answer.\n       *\n       * `runScript` resolves on a non-zero exit deliberately - an exit code is a fact about the\n       * script - but that made this overwrite good cached text with the empty stdout of a\n       * script that had just failed. A caller then saw `ok:false` with nothing in it, having\n       * been one tick away from a perfectly good answer that was thrown out to store the\n       * failure. Zero exit with no output is different and is kept: a pod with no conversations\n       * really does have nothing to say.\n       */\n      if (code !== 0) {\n        throw new Error(`exit ${ code }${ err ? `: ${ err.trim().split('\\n')[0].slice(0, 200) }` : '' }`);\n      }\n      held.text = out;\n      held.at = Date.now();\n      held.error = '';\n      held.failedSince = 0;\n    } catch (e) {\n      const message = String(e?.message || e);\n\n      held.failedSince = held.failedSince || Date.now();\n      // Said once per spell rather than once per tick: a tmux that has been wedged for ten\n      // minutes should not be ten minutes of identical lines in the log.\n      if (message !== held.error) {\n        held.error = message;\n        say(`${ key }: ${ message }`);\n      }\n    } finally {\n      held.reading = null;\n    }\n  }\n\n  await refresh().catch(() => {});\n\n  return held;\n}\n\n/** What a cached answer looks like on the wire, age and all. */\nfunction body(held, extra = {}) {\n  const now = Date.now();\n  const age = held.at ? now - held.at : -1;\n  const broken = held.failedSince && now - held.failedSince > STALE_FLOOR_MS;\n\n  return {\n    version: VERSION,\n    ok:      !!held.text && !broken,\n    text:    broken ? '' : held.text,\n    age,\n    stale:   !!held.error,\n    error:   broken ? held.error : '',\n    ...extra,\n  };\n}\n\n/* ── The routes ─────────────────────────────────────────────────────────────────────────────\n *\n * Deliberately few, and all reads. Nothing here changes anything in the pod: a write still goes\n * through exec, where it has an exit code and an audit trail, and where a bug in this file\n * cannot cost anybody a conversation.\n */\n/**\n * A project name safe to hand a shell script.\n *\n * The one place a caller's input reaches an argv here, so it is the one place that has to say\n * what it accepts. The ids this serves are `p-<workspace>-<n>` and `agent-<n>`, so letters,\n * digits, dash and underscore is the whole alphabet - and anything else is refused rather than\n * quoted, because refusing is checkable and quoting is a thing to get wrong once.\n */\nconst SAFE_NAME = /^[A-Za-z0-9_-]{1,120}$/;\n\n/**\n * A chat's read, run here instead of by a WebSocket from the browser.\n *\n * This is the one that mattered: a live conversation polls every 1.5 seconds, so two of them\n * opened about eighty exec sockets a minute, each one a process forked in this container to\n * learn something that usually had not changed.\n *\n * Not cached and not coalesced, unlike everything else here. The other reads answer the same\n * question for every tab; this one is \"what is in MY conversation since MY offset\", so two\n * callers almost never want the same bytes and holding an answer would only serve a stale one.\n * What is saved is the socket and the fork-per-tick, which is what was costing.\n *\n * Every argument is checked before it reaches a shell. They are all scalars by design - an id,\n * two offsets, a nonce, a directory name, a CLI name - so checking them is a matter of saying\n * what each may contain, which is a thing that can be read and verified. Nothing a caller sends\n * becomes a command.\n */\nconst PANE_ID = /^[A-Za-z0-9_-]{1,120}$/;\nconst NONCE = /^[a-z0-9]{4,64}$/;\nconst PROJ_KEY = /^[A-Za-z0-9_.-]{1,200}$/;\nconst HOME_DIR = /^\\/[A-Za-z0-9_./-]{1,200}$/;\nconst CLIS = ['claude', 'agy'];\n\n/*\n * `chat-read.mjs` is loaded when it is first wanted, not at the top of this file.\n *\n * It is the same module the browser imports - gen-seed.mjs copies it in beside this one, so\n * there is one definition of the read and not two that drift. But a top-level import makes the\n * whole service hostage to it: a seed without that file, for any reason, and this process\n * cannot start at all, so `list` and `states` go down with a route that has nothing to do with\n * them. Measured, not guessed: the service crash-looped and every read fell back to exec.\n *\n * Loaded once and remembered, including the failure, so a seed that cannot serve chat says so\n * immediately on every later request rather than retrying an import that will not work.\n */\nlet chatRead;\n\nasync function chatReader() {\n  if (chatRead === undefined) {\n    try {\n      chatRead = (await import('./chat-read.mjs')).chatReadScript;\n    } catch (e) {\n      say(`chat-read.mjs could not be loaded, so /chat is not served: ${ e?.message || e }`);\n      chatRead = null;\n    }\n  }\n\n  return chatRead;\n}\n\nfunction chatArgs(url) {\n  const id = url.searchParams.get('id') || '';\n  const sub = url.searchParams.get('sub') || '';\n  const nonce = url.searchParams.get('n') || '';\n  const projKey = url.searchParams.get('proj') || '';\n  const home = url.searchParams.get('home') || '';\n  const cli = url.searchParams.get('cli') || 'claude';\n  const off = Number(url.searchParams.get('off') || 0);\n  const soff = Number(url.searchParams.get('soff') || 0);\n\n  if (!PANE_ID.test(id)) {\n    return { bad: 'id' };\n  }\n  if (sub && !PANE_ID.test(sub)) {\n    return { bad: 'sub' };\n  }\n  if (!NONCE.test(nonce)) {\n    return { bad: 'n' };\n  }\n  if (!PROJ_KEY.test(projKey)) {\n    return { bad: 'proj' };\n  }\n  // `..` separately from the pattern: a path of only safe characters can still walk upwards.\n  if (!HOME_DIR.test(home) || home.includes('..')) {\n    return { bad: 'home' };\n  }\n  if (!CLIS.includes(cli)) {\n    return { bad: 'cli' };\n  }\n  if (!Number.isInteger(off) || off < 0 || !Number.isInteger(soff) || soff < 0) {\n    return { bad: 'off' };\n  }\n\n  return {\n    id, off, sub, soff, nonce, projKey, cli, home,\n  };\n}\n\nconst ROUTES = [\n  ['/healthz', async() => ({\n    version: VERSION,\n    ok:      true,\n    pid:     process.pid,\n    uptime:  Date.now() - startedAt,\n    host:    os.hostname(),\n    reads:   [...cache.keys()],\n  })],\n  ['/sessions', async() => body(await cached('list', ['/bin/sh', `${ SEED }/sessions.sh`, 'list']))],\n  ['/chat', async(url) => {\n    const chatReadScript = await chatReader();\n\n    if (!chatReadScript) {\n      return {\n        version: VERSION, ok: false, text: '', age: -1, stale: false, error: 'This pod cannot serve chat reads.',\n      };\n    }\n\n    const at = chatArgs(url);\n\n    if (at.bad) {\n      return {\n        version: VERSION, ok: false, text: '', age: -1, stale: false, error: `Bad ${ at.bad }.`,\n      };\n    }\n\n    /*\n     * As the pane's own user, with the pane's home - the same wrapper the browser's exec used.\n     *\n     * Everything a pane touches belongs to uid 1000, and claude refuses to run as root, so a\n     * read done as root here would be a read of files written by somebody else. The script goes\n     * in base64 so nothing in it is ever quoted for a shell twice.\n     */\n    const script = `export HOME=${ at.home }; export PATH=$HOME/.local/bin:$PATH; ${ chatReadScript(at) }`;\n    const b64 = Buffer.from(script, 'utf8').toString('base64');\n    const path = `/tmp/.chat-api-${ process.pid }-${ Date.now().toString(36) }.sh`;\n    const inner = `echo ${ b64 } | base64 -d > ${ path } && chmod 755 ${ path } && if [ \"$(id -u)\" = 0 ]; then su node -s /bin/bash -c \"/bin/bash ${ path }\" 2>&1; else /bin/bash ${ path } 2>&1; fi; rm -f ${ path }`;\n\n    try {\n      const { out } = await runScript(['/bin/sh', '-c', inner], 25_000);\n\n      return {\n        version: VERSION, ok: true, text: out, age: 0, stale: false, error: '',\n      };\n    } catch (e) {\n      // The browser falls back to its own exec on this, which is the path it used before.\n      return {\n        version: VERSION, ok: false, text: '', age: -1, stale: false, error: String(e?.message || e),\n      };\n    }\n  }],\n  ['/states', async(url) => {\n    /*\n     * `states <project>` is a different verb from `states-all`, not a filter over it.\n     *\n     * sessions.sh says why in its own comments: `states` is scoped to a base and answers for\n     * that project's conversations, `states-all` is not scoped and answers for the pod. Asking\n     * the narrow one for a pod-wide answer is how a caller came to report that nothing was\n     * running anywhere, so the two are kept apart here too - and cached apart, since a tab\n     * watching one workspace and a panel watching the pod want different answers.\n     */\n    const project = url.searchParams.get('project') || '';\n\n    if (!project) {\n      return body(await cached('states-all', ['/bin/sh', `${ SEED }/sessions.sh`, 'states-all']));\n    }\n    if (!SAFE_NAME.test(project)) {\n      return { version: VERSION, ok: false, text: '', age: -1, stale: false, error: 'That is not a project name.' };\n    }\n\n    return body(await cached(`states:${ project }`, ['/bin/sh', `${ SEED }/sessions.sh`, 'states', project]));\n  }],\n];\n\n/* ── The watchdog ───────────────────────────────────────────────────────────────────────────\n *\n * The failure this cannot catch from inside is itself: a process that is up, holding the port,\n * and no longer answering. The browser would keep choosing it over the exec path that works.\n *\n * So: if anything has been asked of this service and nothing has been answered successfully for\n * WATCHDOG_MS, exit. The supervisor starts a fresh one within seconds, and a service that\n * replaces itself is strictly better than one that sits there holding a port it cannot serve.\n * `asked` guards the idle case - a pod nobody is looking at should not restart all night.\n */\nlet asked = 0;\n\n/*\n * How many of each route has been served, for one question nothing could answer from outside.\n *\n * The whole point of this service is that reads stop being execs, and until now the only way to\n * check whether that had actually happened was to count WebSockets in somebody's browser and\n * squint at truncated URLs. These are counts and nothing else - no ids, no paths, no content -\n * and they are served without a token, because a number that says \"this pod has answered 4,000\n * chat reads\" tells an unauthorised caller nothing it could not infer from the service existing,\n * and withholding it costs the one diagnosis anybody actually wants.\n */\nconst served = Object.create(null);\nlet answered = Date.now();\n\nfunction watchdog() {\n  const timer = setInterval(() => {\n    if (!asked) {\n      answered = Date.now();\n\n      return;\n    }\n    if (Date.now() - answered > WATCHDOG_MS) {\n      say(`answered nothing for ${ Math.round((Date.now() - answered) / 1000) }s after ${ asked } requests; exiting for the supervisor`);\n      process.exit(3);\n    }\n  }, 30_000);\n\n  timer.unref?.();\n}\n\n/* ── Serving ────────────────────────────────────────────────────────────────────────────────── */\n\nconst server = http.createServer(async(req, res) => {\n  const send = (code, value) => {\n    const text = JSON.stringify(value);\n\n    try {\n      res.writeHead(code, {\n        'content-type':  'application/json',\n        'cache-control': 'no-store',\n        'x-state-api':   String(VERSION),\n      });\n      res.end(text);\n    } catch { /* the browser went away mid-answer */ }\n  };\n\n  // A request that cannot be answered gives the connection back rather than holding it. The\n  // apiserver proxy in front of this has its own timeout, and a reply it has stopped waiting\n  // for is a socket neither end is using.\n  res.setTimeout?.(REQUEST_TIMEOUT_MS, () => {\n    try {\n      res.destroy();\n    } catch { /* already gone */ }\n  });\n\n  try {\n    const url = new URL(req.url || '/', 'http://pod');\n    const path = url.pathname.replace(/\\/+$/, '') || '/healthz';\n\n    if (req.method !== 'GET') {\n      send(405, { version: VERSION, error: 'Only GET.' });\n\n      return;\n    }\n    // Before the token, and the only route that is: see `served`.\n    if (path === '/served') {\n      send(200, {\n        version: VERSION,\n        ok:      true,\n        uptime:  Date.now() - startedAt,\n        served:  { ...served },\n      });\n\n      return;\n    }\n    if (!allowed(req)) {\n      // Nothing about why. A caller without the token learns that it needs one, and no more.\n      send(401, { version: VERSION, error: 'No.' });\n\n      return;\n    }\n\n    const route = ROUTES.find(([at]) => at === path);\n\n    if (!route) {\n      send(404, { version: VERSION, error: 'No such path.' });\n\n      return;\n    }\n    asked++;\n    served[path] = (served[path] || 0) + 1;\n    send(200, await route[1](url));\n    answered = Date.now();\n  } catch (e) {\n    /*\n     * A bug in a route is a 500, not a dead pod.\n     *\n     * This is the line that matters most in the file. Everything in here shares a pod with\n     * somebody's conversations, and an unhandled throw in a request handler would take the\n     * whole process down and, worse, do it silently from the browser's point of view.\n     */\n    say(`unhandled: ${ e?.stack || e }`);\n    send(500, { version: VERSION, error: String(e?.message || e) });\n  }\n});\n\n/*\n * One of these, and the loser says nothing.\n *\n * Two tabs noticing a dead service at the same moment both start one. The second binds nothing\n * and leaves quietly: the first is already serving, which is what both of them wanted. Any\n * other listen error is worth a word before going, because that one is not expected.\n */\nserver.on('error', (e) => {\n  if (e?.code === 'EADDRINUSE') {\n    process.exit(0);\n  }\n  say(`listen: ${ e?.message || e }`);\n  process.exit(1);\n});\n\n/*\n * A throw with nothing to catch it must not end the pod's service.\n *\n * Logged and survived rather than fatal. The watchdog above is what catches a process that has\n * been damaged enough to stop answering; these two handlers are for the ordinary case of a bug\n * on a path nobody is waiting on, where exiting would be the larger harm.\n */\nprocess.on('uncaughtException', (e) => say(`uncaught: ${ e?.stack || e }`));\nprocess.on('unhandledRejection', (e) => say(`unhandled rejection: ${ e?.stack || e }`));\n\n// SIGTERM is the supervisor or the kubelet asking; stop taking work and let what is in flight\n// finish. SIGINT likewise, for anyone running this by hand.\nfor (const signal of ['SIGTERM', 'SIGINT']) {\n  process.on(signal, () => {\n    say(`${ signal }: closing`);\n    server.close(() => process.exit(0));\n    setTimeout(() => process.exit(0), 5_000).unref?.();\n  });\n}\n\nreadToken();\n// Re-read on a timer: the extension can rotate the token by rewriting the ConfigMap, and the\n// kubelet updates the mount in place without this process knowing.\nsetInterval(readToken, 30_000).unref?.();\nwatchdog();\n\nserver.listen(PORT, '0.0.0.0', () => {\n  say(`version ${ VERSION } listening on ${ PORT }${ token ? '' : ' (no token yet; serving nothing until one appears)' }`);\n});\n",
  "state-api.sh": "#!/bin/sh\n# Keep the pod's state service running, without ever being the reason something else stops.\n#\n# ── Why this is not started from boot.sh ────────────────────────────────────────────────────\n#\n# Because boot.sh is the one file in this seed that cannot change for free. `agentBootVersion`\n# in agent.ts hashes boot.sh, terminal-tools.sh and tmux.conf into the pod template, so editing\n# any of them rolls the pod - and rolling this pod ends every conversation in it. Everything\n# else in /seed is a ConfigMap mount that the kubelet updates in place, which is why a new\n# script reaches a running pod without a restart.\n#\n# So this file arrives in a pod that is already up, and the browser starts it with one exec the\n# first time it finds nothing listening. After that the browser talks HTTP and never forks\n# anything here again. A pod that has never been asked simply has no service, which costs\n# nothing and is exactly the state every pod is in today.\n#\n# ── What it guarantees ──────────────────────────────────────────────────────────────────────\n#\n# One supervisor per pod, one server under it, restarted if it dies, and a log that cannot grow\n# without bound. If this script is wrong, the worst case is no service - and no service means\n# the browser keeps using exec, which is what it did before any of this existed.\nset -e\n\nSEED=${SEED:-/seed}\nRUN=${STATE_API_RUN:-/tmp/.state-api}\nLOG=\"$RUN/log\"\nLOCK=\"$RUN/lock\"\nPIDFILE=\"$RUN/pid\"\nTOKENFILE=\"$RUN/token\"\nPORT=${STATE_API_PORT:-8111}\n# Two hundred kilobytes of log is already more than anyone will read; past that the oldest half\n# goes. A service meant to be invisible must not be able to fill a disk somebody is working on.\nMAX_LOG=204800\n\nmkdir -p \"$RUN\"\nchmod 700 \"$RUN\" 2>/dev/null || true\n\n# The token, minted here and once.\n#\n# Not in the seed: a token in the ConfigMap travels in the extension bundle, so every holder of\n# the bundle would know it, and it would change the seed's fingerprint and have the ConfigMap\n# rewritten on every page load. Generated in the pod it is a real secret with the right\n# lifetime - this pod's - and the browser learns it from the output of this script, over the one\n# exec that starts the service. Printed on every run, including \"already running\", because the\n# caller needs it whether or not it was the one that started anything.\nif [ ! -s \"$TOKENFILE\" ]; then\n  (\n    head -c 32 /dev/urandom 2>/dev/null | od -An -tx1 | tr -d ' \\n' ||\n      node -e 'process.stdout.write(require(\"node:crypto\").randomBytes(32).toString(\"hex\"))'\n  ) > \"$TOKENFILE.new\" 2>/dev/null\n  if [ -s \"$TOKENFILE.new\" ]; then\n    chmod 600 \"$TOKENFILE.new\" 2>/dev/null || true\n    mv \"$TOKENFILE.new\" \"$TOKENFILE\"\n  else\n    rm -f \"$TOKENFILE.new\"\n    echo 'state-api: could not mint a token'\n    exit 1\n  fi\nfi\n\n# `mkdir` is the lock, because it is the one filesystem operation that is atomic everywhere and\n# needs no tooling. A stale lock from a supervisor that was killed is cleared below rather than\n# waited on: the pid it names is the only evidence that matters.\nheld() {\n  [ -f \"$PIDFILE\" ] || return 1\n  pid=$(cat \"$PIDFILE\" 2>/dev/null) || return 1\n  [ -n \"$pid\" ] || return 1\n  kill -0 \"$pid\" 2>/dev/null || return 1\n  return 0\n}\n\ncase \"${1:-start}\" in\n  status)\n    if held; then echo \"running $(cat \"$PIDFILE\")\"; else echo 'not running'; fi\n    echo \"token $(cat \"$TOKENFILE\" 2>/dev/null)\"\n    exit 0\n    ;;\n  restart)\n    # Stop, wait for the port, then start - and the wait is the whole of it.\n    #\n    # Without it this did not replace anything: `stop` returns as soon as the processes it\n    # signalled are gone from the table, the listening socket is released a moment later, and\n    # the new server came up into an EADDRINUSE and stood down exactly as it is designed to -\n    # leaving the OLD one serving. Measured, not guessed: the version never moved.\n    # `sh \"$0\"`, not `\"$0\"`: this arrives from a ConfigMap mount without an executable bit and\n    # is run as `sh /seed/state-api.sh`, so executing it directly fails - and with `set -e` and\n    # stderr redirected, it failed by doing nothing at all and saying nothing. Found by tracing\n    # a restart that reported success and replaced no process.\n    sh \"$0\" stop >/dev/null 2>&1 || true\n    i=0\n    while [ \"$i\" -lt 50 ]; do\n      # A connection refused is the thing being waited for, so failure here is success.\n      if ! curl -s -o /dev/null -m 1 \"localhost:$PORT/healthz\" 2>/dev/null; then\n        break\n      fi\n      i=$((i + 1))\n      sleep 0.1 2>/dev/null || sleep 1\n    done\n    exec sh \"$0\" start\n    ;;\n  stop)\n    # The GROUP, not the pid.\n    #\n    # `setsid` makes the supervisor a process-group leader with the node server inside its\n    # group, so killing the pid alone left the server holding the port with nothing supervising\n    # it. The next start then got EADDRINUSE, stood down as designed, and removed the lock and\n    # the pidfile - leaving a service that worked but that no supervisor would ever restart.\n    # The negative pid is the group.\n    if held; then\n      pid=$(cat \"$PIDFILE\")\n      kill -TERM \"-$pid\" 2>/dev/null || kill -TERM \"$pid\" 2>/dev/null || true\n      i=0\n      while [ \"$i\" -lt 30 ] && kill -0 \"$pid\" 2>/dev/null; do\n        i=$((i + 1))\n        sleep 0.1 2>/dev/null || sleep 1\n      done\n      kill -KILL \"-$pid\" 2>/dev/null || true\n    fi\n    # Anything still on the port is a server orphaned by an older version of this script.\n    pkill -f \"$SEED/state-api.mjs\" 2>/dev/null || true\n    # The token stays: a restart that kept it means every tab holding it keeps working.\n    rm -rf \"$LOCK\" \"$PIDFILE\"\n    exit 0\n    ;;\nesac\n\n# Already supervised: say so and leave. Two tabs racing to start this is the normal case, not\n# an error, and the second one has nothing to do.\nif held; then\n  echo \"state-api already running ($(cat \"$PIDFILE\")) on $PORT\"\n  echo \"token $(cat \"$TOKENFILE\")\"\n  exit 0\nfi\n\n# A lock whose supervisor is gone is not a lock - but a lock taken half a second ago by the\n# other tab that noticed at the same moment is, and it has not written its pidfile yet.\n#\n# Waiting is the whole of the fix here. Both tabs run this within milliseconds of each other;\n# the loser used to look once, see no pidfile, call the lock stale, and report that nothing came\n# up - so a perfectly healthy service that the winner had just started was reported as a failure\n# and that tab went back to exec for the rest of its life.\nif ! mkdir \"$LOCK\" 2>/dev/null; then\n  i=0\n  while [ \"$i\" -lt 30 ]; do\n    if held; then\n      echo \"state-api already running ($(cat \"$PIDFILE\")) on $PORT\"\n      echo \"token $(cat \"$TOKENFILE\")\"\n      exit 0\n    fi\n    i=$((i + 1))\n    sleep 0.1 2>/dev/null || sleep 1\n  done\n  # Three seconds and still nobody behind it: the holder is gone, not slow.\n  rm -rf \"$LOCK\"\n  mkdir \"$LOCK\" 2>/dev/null || { echo 'state-api: could not take the lock'; exit 1; }\nfi\n\nif [ ! -f \"$SEED/state-api.mjs\" ]; then\n  rm -rf \"$LOCK\"\n  echo \"state-api: $SEED/state-api.mjs is not here\"\n  exit 1\nfi\n\n# `setsid` so the supervisor outlives the exec that started it. Without it the whole tree is in\n# the exec's process group and dies the moment the browser's WebSocket closes - which is about\n# two hundred milliseconds after it starts, and would look exactly like a service that crashes\n# on startup for reasons nobody can find.\nsetsid /bin/sh -c '\n  RUN='\"$RUN\"'; LOG='\"$LOG\"'; LOCK='\"$LOCK\"'; PIDFILE='\"$PIDFILE\"'\n  SEED='\"$SEED\"'; PORT='\"$PORT\"'; MAX_LOG='\"$MAX_LOG\"'\n  echo $$ > \"$PIDFILE\"\n  # Take the server down with the supervisor. Without this a stopped supervisor left its node\n  # child holding the port, which is the orphan `stop` above now has to sweep for.\n  trap \"kill \\$child 2>/dev/null; rm -rf \\\"$LOCK\\\" \\\"$PIDFILE\\\"; exit 0\" TERM INT\n\n  # Backs off so a server that cannot start - a syntax error in a half-written ConfigMap, a port\n  # taken by something else - does not become a fork bomb in a pod somebody is working in.\n  wait=1\n  while :; do\n    [ -f \"$SEED/state-api.mjs\" ] || { echo \"[supervisor] seed gone; stopping\" >> \"$LOG\"; break; }\n\n    if [ -f \"$LOG\" ]; then\n      size=$(wc -c < \"$LOG\" 2>/dev/null || echo 0)\n      if [ \"$size\" -gt \"$MAX_LOG\" ]; then\n        tail -c $((MAX_LOG / 2)) \"$LOG\" > \"$LOG.trimmed\" 2>/dev/null && mv \"$LOG.trimmed\" \"$LOG\"\n      fi\n    fi\n\n    started=$(date +%s)\n    STATE_API_PORT=\"$PORT\" STATE_API_SEED=\"$SEED\" STATE_API_TOKEN_FILE=\"$RUN/token\" \\\n      node \"$SEED/state-api.mjs\" >> \"$LOG\" 2>&1 &\n    child=$!\n    wait \"$child\"\n    code=$?\n    ran=$(( $(date +%s) - started ))\n\n    # Exit 0 is a deliberate stand-down: the server found the port already taken, which means\n    # another one is serving and this supervisor has nothing left to supervise.\n    [ \"$code\" = \"0\" ] && { echo \"[supervisor] server stood down; stopping\" >> \"$LOG\"; break; }\n\n    # A server that stayed up is a server that was working: start the backoff over, so one bad\n    # night does not leave a healthy pod waiting thirty seconds for its service.\n    if [ \"$ran\" -ge 30 ]; then wait=1; else wait=$(( wait * 2 )); fi\n    [ \"$wait\" -gt 30 ] && wait=30\n    echo \"[supervisor] exited $code after ${ran}s; again in ${wait}s\" >> \"$LOG\"\n    sleep \"$wait\"\n  done\n  rm -rf \"$LOCK\" \"$PIDFILE\"\n' >/dev/null 2>&1 &\n\n# Give it long enough to have bound, so the caller is told something true. Not long enough to\n# matter to the exec that is waiting on it.\ni=0\nwhile [ \"$i\" -lt 20 ]; do\n  held && break\n  i=$((i + 1))\n  sleep 0.1 2>/dev/null || sleep 1\ndone\n\nif held; then\n  echo \"state-api started ($(cat \"$PIDFILE\")) on $PORT\"\n  echo \"token $(cat \"$TOKENFILE\")\"\nelse\n  echo 'state-api: did not come up; the browser will keep using exec'\n  exit 1\nfi\n",
  "terminal-tools.sh": "#!/bin/sh\n# What a terminal tab needs, on top of what the dev server needs: tmux, so a\n# session outlives the browser tab that opened it, and the claude CLI, which is\n# what actually runs in the pane.\n#\n# Both land in the container filesystem, which a restart throws away, so this\n# runs on every boot. It is called twice, deliberately:\n#\n#   - from boot.sh, in the background, because the dev server does not depend on\n#     any of it and must not wait for it;\n#   - from shell.sh, in the foreground, so a tab opened before the background\n#     run finished waits here, where the waiting is visible, rather than landing\n#     in a pane with no claude in it.\n#\n# Hence the lock: the two can overlap on a pod that has just started.\nset -e\n\nLOCK=/tmp/terminal-tools.lock\n\n# Which home the tools are installed into and run with. HOME_DIR is passed by shell.sh, since\n# which directory outlives the pod depends on which kind of pod this is: /app for a dev server,\n# /workspace for the agent. The default is for the background run from boot.sh, which is a dev\n# server's.\n#\n# Read at the top rather than at the bottom, where it used to be, because the claude install is\n# now inside it and so is the question of whether there is anything to install.\nAPP_HOME=${HOME_DIR:-/app/.home}\nCLAUDE_BIN=\"$APP_HOME/.local/bin/claude\"\n\n# Run something as the node user, with the home and the PATH a pane will have.\n#\n# Every pane is that user - claude refuses --dangerously-skip-permissions as root, and the files\n# it edits are the ones webpack is watching - so anything installed into a home has to be\n# installed by the user who will run it. The exec subresource arrives as root; boot.sh calls\n# this before it drops.\nas_node() {\n  # TRUST_DIRS is forwarded here rather than by the one caller that sets it, because\n  # `VAR=x some_function` does not reliably export VAR to what the function then runs.\n  if [ \"$(id -u)\" = 0 ]; then\n    setpriv --reuid=1000 --regid=1000 --init-groups \\\n      env \"HOME=$APP_HOME\" \"PATH=$APP_HOME/.local/bin:$PATH\" \"TRUST_DIRS=${TRUST_DIRS:-}\" sh -c \"$1\"\n  else\n    env \"HOME=$APP_HOME\" \"PATH=$APP_HOME/.local/bin:$PATH\" \"TRUST_DIRS=${TRUST_DIRS:-}\" sh -c \"$1\"\n  fi\n}\n\n# Is there anything to do at all?\n#\n# Asked before the lock is touched, and that ordering is the point. Everything the lock\n# protects is an install, so a tab opening in a pod that finished installing hours ago has\n# nothing to serialise with anybody - and a pod is in that state for all but the first few\n# minutes of its life. Taking a lock to discover there is no work is how one wedged tab used to\n# block every tab after it.\nhave_tools() {\n  command -v tmux >/dev/null 2>&1 &&\n    [ -x \"$CLAUDE_BIN\" ] &&\n    command -v kubectl >/dev/null 2>&1\n}\n\n# What wedges a tab, and why the waiting had to be bounded.\n#\n# A tab is a Kubernetes exec on a pty. Close the browser tab and nothing drains that pty any\n# more, so the next write into it blocks - and stays blocked, because the reader is never\n# coming back. A shell stuck there is alive by every test available: it has a pid, kill -0\n# succeeds, and if it was holding the lock when it stopped, it holds it for the life of the pod.\n# Observed: six of them in one pod, the oldest four hours old, each stopped mid-echo of the\n# message below.\n#\n# So three things, none of which is sufficient alone. The check above means a settled pod never\n# takes the lock. The message is printed once rather than every three seconds, because it was\n# the repetition that filled the pty. And the wait gives up: if the tools turn out to be there,\n# whoever holds the lock is not installing anything this tab needs.\nif ! have_tools; then\n  waited=0\n  said=\"\"\n  took=\"\"\n\n  while true; do\n    # Taking it is the loop's exit, and `took` is how the release below knows this shell owns\n    # what it is about to delete. The other way out of here is giving up, which must not.\n    if mkdir \"$LOCK\" 2>/dev/null; then\n      took=yes\n      break\n    fi\n\n    holder=$(cat \"$LOCK/pid\" 2>/dev/null || true)\n\n    # A holder that has exited outright. Older locks carry no pid at all, which is the same\n    # conclusion by a different route once nobody has claimed it for a while.\n    if [ -n \"$holder\" ] && ! kill -0 \"$holder\" 2>/dev/null; then\n      echo \"[tools] the install holding this lock is gone; clearing it\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    if [ -z \"$holder\" ] && [ \"$waited\" -ge 10 ]; then\n      echo \"[tools] this lock has no owner; clearing it\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    # Two minutes is longer than an install of tmux and the claude CLI on a warm image and\n    # shorter than anybody will sit and watch. Past it, believe the filesystem over the lock.\n    if [ \"$waited\" -ge 40 ]; then\n      if have_tools; then\n        echo \"[tools] the lock is held but everything is installed; carrying on\"\n        break\n      fi\n\n      echo \"[tools] the lock has been held for two minutes; taking it over\"\n      rm -rf \"$LOCK\"\n      continue\n    fi\n\n    if [ -z \"$said\" ]; then\n      echo \"[tools] another install is running, waiting for it\"\n      said=yes\n    fi\n\n    waited=$((waited + 1))\n    sleep 3\n  done\n\n  # Only what this shell actually took. Giving up on a lock somebody else holds and then\n  # deleting it on the way out would be worse than the wait it was avoiding.\n  if [ -n \"$took\" ]; then\n    echo $$ > \"$LOCK/pid\" 2>/dev/null || true\n\n    # HUP as well as the rest: an exec that is hung up should release this on the way out\n    # rather than leave it for a pod restart to clear.\n    trap 'rm -rf \"$LOCK\" 2>/dev/null || true' EXIT INT TERM HUP\n  fi\nfi\n\nif ! command -v tmux >/dev/null 2>&1; then\n  echo \"[tools] installing tmux\"\n  # apt runs one at a time. The pod's own boot is usually in it already, and on a slow network\n  # its `update` takes minutes; wait for it (ten at most) rather than fail on its lock - and\n  # stop waiting the moment tmux is there, whoever installed it.\n  w=0\n  while pgrep -x apt-get >/dev/null 2>&1 && [ \"$w\" -lt 40 ]; do\n    command -v tmux >/dev/null 2>&1 && break\n    sleep 3\n    w=$((w + 1))\n  done\n  if ! command -v tmux >/dev/null 2>&1; then\n    # ForceIPv4 and a connect timeout, because that is what hung: the pod resolves the Debian\n    # mirror to an IPv6 address it has no route to, and apt has no timeout of its own - one\n    # `update` sat there for twenty-five minutes with every terminal in the pod queued behind\n    # it, each printing that it was waiting for an install.\n    # Bounded, and tried twice. The timeouts on the apt options cover the HTTP fetch and nothing\n    # else: after a pod restart `apt-get update` sat for twenty minutes inside gpgv, and every\n    # conversation in the pod read \"Not running\" until somebody killed it by hand. A pane cannot\n    # run without tmux, so this is the one install that must not be allowed to hang.\n    APT=\"timeout 150 apt-get -o Acquire::ForceIPv4=true -o Acquire::http::Timeout=20 -o Acquire::Retries=1 -o DPkg::Lock::Timeout=60\"\n    for attempt in 1 2; do\n      $APT update -qq </dev/null || true\n      $APT install -y -qq tmux </dev/null && break\n      echo \"[tools] tmux did not install (attempt $attempt)\"\n      sleep 5\n    done\n    command -v tmux >/dev/null 2>&1 || echo \"[tools] tmux did not install; the pane cannot run without it\"\n  fi\nfi\n\n# Not every pod that runs this needs a claude in it.\n#\n# dev-extension's workspaces are the case: their conversations run in the agent pod now, and a\n# command only comes back here through a tunnel, so the CLI would be 400 MB of hostPath per\n# workspace that nothing ever executes - twice that once it takes an update, since installs\n# accumulate. They set TOOLS_NO_CLAUDE=1 and get tmux, kubectl and the rest.\nif [ \"${TOOLS_NO_CLAUDE:-0}\" = 1 ]; then\n  echo \"[tools] skipping the claude cli (TOOLS_NO_CLAUDE)\"\nelif [ ! -x \"$CLAUDE_BIN\" ]; then\n  echo \"[tools] installing the claude cli (this takes a moment)\"\n\n  # The native installer, into the pane's own durable home, and it is worth saying what that\n  # buys over the `npm install -g` it replaces. `claude doctor` in a pod used to report\n  # `npm-global` and a warning - \"can't auto-update: npm global folder isn't writable\" - because\n  # /usr/local/lib belongs to root and the pane does not, so the CLI in here could never take an\n  # update. The harness's own claude reports `native`, and now so does this. It also lands on\n  # the hostPath, so a pod restart no longer spends a minute reinstalling it.\n  #\n  # npm stays as the fallback rather than the default: it reaches a different host, so the two\n  # do not fail together, and a pane with a slightly older claude in it beats a pane with none.\n  as_node \"curl -fsSL https://claude.ai/install.sh | bash -s latest\" || true\n\n  if [ ! -x \"$CLAUDE_BIN\" ] && ! command -v claude >/dev/null 2>&1; then\n    echo \"[tools] the native installer did not land; falling back to npm\"\n    npm install -g --silent @anthropic-ai/claude-code\n  fi\nfi\n\n# Antigravity, for a pane held with it instead.\n#\n# Only when asked for (TOOLS_AGY=1), and not at all where claude is skipped: it is another\n# couple of hundred megabytes per pod of a CLI most panes will not run, and the pods that skip\n# claude skip it because nothing in them executes a CLI at all. Its installer is the same shape\n# as claude's - a script that drops a single static binary into the pane's own durable home -\n# so it lands beside it on the hostPath and survives a pod restart the same way.\n#\n# A failure here is not fatal: agy-session.sh says so in the pane and drops to a shell, which\n# is a better answer than a pod that will not start.\nif [ \"${TOOLS_NO_CLAUDE:-0}\" = 1 ] || [ \"${TOOLS_AGY:-0}\" != 1 ]; then\n  :\nelif [ ! -x \"$APP_HOME/.local/bin/agy\" ]; then\n  echo \"[tools] installing the antigravity cli (this takes a moment)\"\n  # `--dir`, and ONLY `--dir`: this installer takes `-d/--dir` and `-h/--help` and nothing else.\n  # It was called with claude's flags (`--skip-aliases --skip-path`), and an unknown option makes\n  # it print its usage and exit 0 - so every pod that asked for agy got a clean log, a success,\n  # and no binary. The directory is named rather than left to the installer's default for the\n  # same reason claude's is: the pane's home is a hostPath, and that is what survives the pod.\n  as_node \"mkdir -p '$APP_HOME/.local/bin' && curl -fsSL https://antigravity.google/cli/install.sh | bash -s -- --dir '$APP_HOME/.local/bin'\" || true\n\n  if [ ! -x \"$APP_HOME/.local/bin/agy\" ]; then\n    echo \"[tools] the antigravity installer did not land; panes asking for it will say so\"\n  fi\nfi\n\n# A pod that was started before this change keeps its npm copy in the container filesystem until\n# it restarts, and `claude doctor` calls that a leftover - correctly, since two claudes on one\n# PATH is a coin toss about which one a pane gets. Only when the native one is actually there,\n# so a pod that fell back to npm above keeps the only claude it has.\nif [ -x \"$CLAUDE_BIN\" ] && [ \"$(id -u)\" = 0 ] && [ -e /usr/local/bin/claude ]; then\n  echo \"[tools] removing the npm copy this pod installed before\"\n  npm -g uninstall @anthropic-ai/claude-code >/dev/null 2>&1 || rm -f /usr/local/bin/claude\nfi\n\n# kubectl, so the pod's own ServiceAccount is usable from a terminal. It needs\n# no configuration: in-cluster credentials are mounted and client-go finds them,\n# which is the whole reason the terminals can manage the cluster at all.\n#\n# Pinned to the cluster's version rather than \"stable\", so what a terminal gets\n# does not change under it on a day when upstream moves.\nif ! command -v kubectl >/dev/null 2>&1; then\n  echo \"[tools] installing kubectl\"\n  curl -sSLo /usr/local/bin/kubectl \"https://dl.k8s.io/release/v1.36.1/bin/linux/amd64/kubectl\"\n  chmod 0755 /usr/local/bin/kubectl\nfi\n\n# Answer claude's first-run questions before it can ask them, so a tab opens on\n# a prompt or a login rather than on a theme picker. Idempotent, and a no-op\n# once the flags are set, so it is safe to run on every boot and every tab.\n#\n# As the node user: this writes into the home claude runs with, and a root-owned\n# .claude.json is one claude cannot then update. APP_HOME is set at the top of this file.\n#\n# TRUST_DIRS is the pane's own directory, passed by shell.sh, so the folder the\n# tab is about to open in is one claude already trusts rather than one it stops\n# and asks about.\nif [ \"${TOOLS_NO_CLAUDE:-0}\" != 1 ]; then\n  as_node \"node /seed/claude-defaults.mjs\"\nfi\n\necho \"[tools] ready\"\n",
  "tmux.conf": "# tmux config for a terminal tab. Read straight out of /seed (tmux -f), so it is\n# always the version the extension last wrote and there is no copy in the tree.\n#\n# Mouse on so the scroll wheel scrolls tmux's 50k-line scrollback (it enters\n# copy-mode automatically and exits at the bottom). A plain mouse drag selects\n# via tmux copy-mode; when the drag ends, set-clipboard emits the selection as\n# an OSC 52 sequence, which the terminal component hands to the browser\n# clipboard - so drag-select auto-copies. (Shift+drag still does a native\n# xterm.js selection.) The terminal-features line tells tmux the outer terminal\n# understands OSC 52.\nset -g mouse on\nset -g history-limit 50000\n\n# Pass focus in and out of the pane through to what is running in it. claude\n# asks for this by name on startup when it is off, and asking is the thing this\n# pod is trying not to do.\nset -g focus-events on\nset -s set-clipboard on\nset -as terminal-features ',xterm-256color:clipboard'\n\n# No status bar. The harness keeps tmux's, where it lists the windows of a\n# session you can switch between; this pane has one session and one window, so\n# it would be a row of screen spent on a constant - and a green one, which is\n# the only thing in the pane that cannot follow Rancher's theme.\nset -g status off\n",
  "tunnel-browser.sh": "#!/bin/sh\n# Give each downstream-hosted workspace the shared github-browser at 127.0.0.1:9223, so an agent's\n# github media upload - which runs in the workspace pod via dev-shell - reaches the one Chromium that\n# holds the github.com login, exactly as a local workspace does by service name.\n#\n# A downstream workspace pod is on another cluster and can reach nothing here: the browser\n# (github-browser.dev-system.svc) does not resolve there, and the parent Rancher is not reachable\n# from it either. The only channel in is the kubectl-exec stream the mount and dev-shell already use.\n# CDP is not one connection - a /json probe then a WebSocket, and clients may overlap them - so a raw\n# pipe (as the sshfs mount uses for its single sftp stream) will not do; ssh reverse-forwarding\n# multiplexes every CDP connection over one exec stream. We run sshd in inetd mode (-i) in the\n# workspace pod straight over `kubectl exec` (no listening port, no service), authenticate with a\n# keypair this pod owns, and open `-R 127.0.0.1:9223 -> github-browser:9222` (reachable from here).\n# layout.mjs sets the downstream workspace's GITHUB_BROWSER_CDP to http://127.0.0.1:9223 to match.\nSECRET=/var/run/downstream-exec\nLOCAL=local\nBROWSER=github-browser.dev-system.svc.cluster.local:9222\nPORT=9223\nDIR=/workspace/.tunnel\nKEY=$DIR/id\nPATH=/workspace/.home/.local/bin:/usr/local/bin:/usr/bin:/bin:$PATH\nexport PATH\n\n# kubectl arrives from terminal-tools.sh; ssh/ssh-keygen from boot.sh (openssh-client).\nn=0\nwhile ! command -v ssh >/dev/null 2>&1 || ! command -v kubectl >/dev/null 2>&1; do\n  n=$((n + 1))\n  [ \"$n\" -gt 120 ] && { echo \"ssh/kubectl never arrived; not tunnelling\"; exit 0; }\n  sleep 10\ndone\n\n# One keypair for this pod, reused for every workspace; its public half is authorized in each.\nmkdir -p \"$DIR\"\n[ -f \"$KEY\" ] || ssh-keygen -q -t ed25519 -N '' -f \"$KEY\"\nPUB=$(cat \"$KEY.pub\")\n\n# kubectl exec into a downstream workspace pod, through that cluster's Rancher proxy with the durable\n# token - the same address the mount and dev-shell build. $1.. are the argv to run in the pod.\n# No -i, and stdin from /dev/null: this runs inside a `while read` piped from kubectl, and an exec\n# that holds stdin would swallow the rest of that list, so only the first workspace got a tunnel.\nkexec() {\n  name=$1; cluster=$2; shift 2\n  kubectl --server=\"$RURL/k8s/clusters/$cluster\" --token=\"$TOKEN\" --insecure-skip-tls-verify=true \\\n    exec -n \"dev-$name\" \"deploy/dev-$name\" -c workspace -- \"$@\" </dev/null\n}\n\n# Install sshd, a host key, and our pubkey in the workspace pod, and free port 9223. Idempotent.\n# The pubkey is passed as an argument (not interpolated into the script) so its spaces need no\n# quoting care. Freeing 9223 matters: an sshd left by a dropped exec (an agent-pod restart orphans\n# the workspace pod's inetd sshd) keeps the -R listener bound, and a fresh tunnel then fails to bind\n# it (\"Address already in use\") forever. We only run this when there is no live tunnel (see alive),\n# so killing every sshd here is safe.\nensure_sshd() {\n  name=$1; cluster=$2\n  kexec \"$name\" \"$cluster\" sh -c '\n    command -v sshd >/dev/null 2>&1 || { apt-get update -qq && apt-get install -y -qq openssh-server; } >/dev/null 2>&1\n    mkdir -p /run/sshd /root/.ssh && chmod 700 /root/.ssh\n    [ -f /etc/ssh/ssh_host_ed25519_key ] || ssh-keygen -A >/dev/null 2>&1\n    grep -qxF \"$1\" /root/.ssh/authorized_keys 2>/dev/null || printf \"%s\\n\" \"$1\" >> /root/.ssh/authorized_keys\n    chmod 600 /root/.ssh/authorized_keys\n    for p in $(pgrep -x sshd 2>/dev/null); do kill -9 \"$p\" 2>/dev/null; done\n  ' sh \"$PUB\" >/dev/null 2>&1\n}\n\n# Is the tunnel for this workspace up AND carrying? The ssh process alive, and 9223 answering the\n# CDP probe inside the pod - an ssh can stay up (ServerAliveInterval keeps the transport) while its\n# -R forward is broken, so the process being alive is not enough. This does re-establish a broken\n# one, and that no longer flaps: ensure_sshd frees 9223 first, so the re-establish binds and the next\n# probe passes, rather than failing \"address in use\" forever.\nalive() {\n  name=$1; cluster=$2; pidf=$DIR/$name.pid\n  [ -f \"$pidf\" ] && kill -0 \"$(cat \"$pidf\" 2>/dev/null)\" 2>/dev/null || return 1\n  kexec \"$name\" \"$cluster\" sh -c \"curl -s -m4 -o /dev/null http://127.0.0.1:$PORT/json/version\" >/dev/null 2>&1\n}\n\ntunnel_one() {\n  name=$1; cluster=$2; pidf=$DIR/$name.pid\n  alive \"$name\" \"$cluster\" && return 0\n  # No live tunnel: drop any old ssh (its exec, and the pod's sshd with it) before a fresh one.\n  [ -f \"$pidf\" ] && { kill \"$(cat \"$pidf\" 2>/dev/null)\" 2>/dev/null; rm -f \"$pidf\"; }\n  ensure_sshd \"$name\" \"$cluster\"\n  # sshd -i speaks the ssh protocol over the exec stdio (inetd mode); ssh multiplexes the -R forward\n  # over it. Root, pubkey-only, remote forwarding on - the pod's exec already runs as root.\n  # ClientAliveInterval makes an orphaned sshd (its client gone) exit and free 9223 on its own.\n  proxy=\"kubectl --server=$RURL/k8s/clusters/$cluster --token=$TOKEN --insecure-skip-tls-verify=true exec -i -n dev-$name deploy/dev-$name -c workspace -- /usr/sbin/sshd -i -e -o PermitRootLogin=prohibit-password -o PubkeyAuthentication=yes -o PasswordAuthentication=no -o AllowTcpForwarding=remote -o AuthorizedKeysFile=/root/.ssh/authorized_keys -o ClientAliveInterval=15 -o ClientAliveCountMax=2\"\n  ssh -N -T \\\n    -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null \\\n    -o ExitOnForwardFailure=yes -o ServerAliveInterval=15 -o ServerAliveCountMax=3 \\\n    -o \"ProxyCommand=$proxy\" \\\n    -i \"$KEY\" \\\n    -R \"127.0.0.1:$PORT:$BROWSER\" \\\n    root@downstream >/dev/null 2>&1 </dev/null &\n  echo $! > \"$pidf\"\n  echo \"$(date -u +%FT%TZ) tunnel (re)started for $name ($cluster)\"\n}\n\nwhile true; do\n  TOKEN=$(cat \"$SECRET/token\" 2>/dev/null)\n  RURL=$(cat \"$SECRET/rancherUrl\" 2>/dev/null)\n  if [ -n \"$TOKEN\" ] && [ -n \"$RURL\" ]; then\n    kubectl get appinstances.appsplus.io -A -o jsonpath='{range .items[*]}{.metadata.labels.dev\\.rancher\\.io/workspace}{\" \"}{.metadata.labels.dev\\.rancher\\.io/cluster}{\"\\n\"}{end}' 2>/dev/null | \\\n    while read -r name cluster; do\n      [ -n \"$name\" ] && [ -n \"$cluster\" ] || continue\n      [ \"$cluster\" = \"$LOCAL\" ] && continue\n      case \"$name\" in preview-*) continue ;; esac\n      tunnel_one \"$name\" \"$cluster\"\n    done\n  fi\n  sleep 20\ndone\n",
};
